# ===== 动画辅助类 =====
class Easing:
    @staticmethod
    def ease_out_cubic(t):
        return 1 - (1 - t) ** 3

    @staticmethod
    def ease_in_cubic(t):
        return t ** 3

    @staticmethod
    def ease_in_out_quad(t):
        return 2 * t * t if t < 0.5 else 1 - 2 * (1 - t) ** 2


class CTkAnimatedButton(ctk.CTkButton):
    """支持悬停抬升、点击缩放、脉冲动画的 CTkButton 子类"""
    def __init__(self, master, *args, **kwargs):
        super().__init__(master, *args, **kwargs)
        self._base_w = self.cget("width")
        self._base_h = self.cget("height")
        self._hover_lift = 4
        self._click_scale = 0.95
        self._pulse_scale = 1.08
        self._anim_duration = 200  # ms
        self._anim_id = None
        self._bind_hover_events()

    def _animate(self, target_w, target_h, duration, easing_func=None):
        if self._anim_id:
            self.after_cancel(self._anim_id)
        start_w = self.winfo_width()
        start_h = self.winfo_height()
        steps = max(1, duration // 20) 
        step_w = (target_w - start_w) / steps
        step_h = (target_h - start_h) / steps

        def step(i):
            if i >= steps:
                self.configure(width=int(target_w), height=int(target_h))
                self._anim_id = None
                return
            if easing_func:
                t = i / steps
                eased = easing_func(t)
                current_w = start_w + (target_w - start_w) * eased
                current_h = start_h + (target_h - start_h) * eased
            else:
                current_w = start_w + step_w * (i + 1)
                current_h = start_h + step_h * (i + 1)
            self.configure(width=int(current_w), height=int(current_h))
            self._anim_id = self.after(15, lambda: step(i + 1))

        self._anim_id = self.after(15, lambda: step(0))

    def _bind_hover_events(self):
        self.bind("<Enter>", self._on_enter)
        self.bind("<Leave>", self._on_leave)

    def _on_enter(self, event):
        self._animate(self._base_w + self._hover_lift, self._base_h + self._hover_lift,
                      self._anim_duration, Easing.ease_out_cubic)

    def _on_leave(self, event):
        self._animate(self._base_w, self._base_h, self._anim_duration, Easing.ease_in_out_quad)

    def _on_press(self, event):
        self._animate(self._base_w * self._click_scale, self._base_h * self._click_scale,
                      self._anim_duration // 2, Easing.ease_in_cubic)

    def _on_release(self, event):
        # 如果鼠标仍在控件内，恢复到悬停尺寸
        if self.winfo_containing(event.x_root, event.y_root) == self:
            self._animate(self._base_w + self._hover_lift, self._base_h + self._hover_lift,
                          self._anim_duration // 2, Easing.ease_out_cubic)
        else:
            self._animate(self._base_w, self._base_h, self._anim_duration // 2, Easing.ease_in_out_quad)

    def pulse_animation(self):
        """点击脉冲放大缩小"""
        self._animate(self._base_w * self._pulse_scale, self._base_h * self._pulse_scale,
                      100, Easing.ease_out_cubic)
        self.after(200, lambda: self._animate(self._base_w, self._base_h, 100, Easing.ease_in_out_quad))


def _make_safe_os():
    """
    返回一个 os 模块的代理对象：
    - 只读操作（listdir / path / stat / getcwd / environ 读）直接放行
    - 写/执行/进程操作（system / popen / remove / chmod / fork ...）被 stub 拦截
    """
    import io as _io
    import os as _real_os

    # 会改变宿主机状态或执行外部程序的函数
    DANGEROUS = {
        # 进程执行
        "system", "popen", "popen2", "popen3", "popen4",
        "spawnl", "spawnle", "spawnlp", "spawnlpe",
        "spawnv", "spawnve", "spawnvp", "spawnvpe",
        "execl", "execle", "execlp", "execlpe",
        "execv", "execve", "execvp", "execvpe",
        "fork", "forkpty", "kill", "killpg",
        "abort", "startfile",
        # 文件系统写
        "remove", "unlink", "rmdir", "removedirs",
        "mkdir", "makedirs", "rename", "renames", "replace",
        "chmod", "chown", "lchmod", "lchown",
        "link", "symlink", "truncate",
        # 环境变量写
        "putenv", "unsetenv",
    }

    class SafeOS:
        """沙盒化的 os 模块代理"""

        def __getattr__(self, name):
            if name in DANGEROUS:
                def blocker(*args, **kwargs):
                    # 打印拦截日志，返回"失败"结果
                    try:
                        print(f"[沙盒] 已拦截 os.{name}({args!r})")
                    except Exception:
                        pass
                    # 按函数名给合理的失败返回值
                    if name in ("popen", "popen2", "popen3", "popen4"):
                        return _io.StringIO("")     # 读出来是空字符串
                    if name == "system":
                        return 1                    # 非 0 = 失败
                    return None
                return blocker

            # 只读操作直接放行（getattr 会拿到真正的 os 属性）
            return getattr(_real_os, name)

        def __dir__(self):
            return dir(_real_os)

    return SafeOS()


def _make_safe_subprocess():
    """
    返回一个 subprocess 模块的代理对象：
    所有执行类函数（Popen / run / call / check_output）都被 stub，
    返回假的 CompletedProcess，不会真的执行命令。
    """
    class _FakeCompleted:
        returncode = 1
        stdout = ""
        stderr = "[沙盒] subprocess 已被拦截"

    class SafeSubprocess:
        def __getattr__(self, name):
            def blocker(*args, **kwargs):
                try:
                    print(f"[沙盒] 已拦截 subprocess.{name}({args!r})")
                except Exception:
                    pass
                if name in ("run", "call", "check_call", "check_output"):
                    return _FakeCompleted()
                if name == "Popen":
                    return None
                return None
            return blocker

        def __dir__(self):
            return []

    return SafeSubprocess()


# ==================== 沙盒环境工厂函数 ====================

def _create_sandbox_env(use_restricted_open=True, shell=None, allowed_modules=None):
    """创建统一的沙盒执行环境。

    Args:
        use_restricted_open: 是否限制 open 只能访问临时目录。
        shell: KIKIShell 实例（用于主线程弹窗，但子进程通常不传）。
        allowed_modules: 允许导入的额外模块列表（子进程使用）。
    """
    import os
    import sys
    import tempfile

    if allowed_modules is None:
        allowed_modules = []

    # 安全白名单
    SAFE_MODULES = {
        "math", "random", "time", "datetime", "json", "re", "string",
        "itertools", "functools", "collections", "copy", "textwrap",
        "unicodedata", "difflib", "heapq", "bisect", "array", "struct",
        "enum", "dataclasses", "typing", "abc", "queue",
        "io", "pathlib", "hashlib", "hmac", "base64", "decimal",
        "fractions", "statistics", "platform"
    }

    # 安全 sys 代理
    class SafeSys:
        __slots__ = ("_executable", "_path", "_stderr", "_stdin", "_stdout", "_version")
        def __init__(self):
            self._stdout = sys.stdout
            self._stderr = sys.stderr
            self._stdin = sys.stdin
            self._version = sys.version
            self._executable = sys.executable
            self._path = sys.path
        def __getattribute__(self, name):
            if name in ("modules", "argv", "exit", "exc_info", "getrefcount"):
                raise AttributeError(f"沙盒禁止访问 sys.{name}")
            if name.startswith("_"):
                return object.__getattribute__(self, name)
            try:
                return getattr(sys, name)
            except AttributeError:
                raise AttributeError(f"sys 没有属性 {name}")
        def __setattr__(self, name, value):
            if name == "modules":
                raise AttributeError("禁止修改 sys.modules")
            if name in ("argv", "exit", "exc_info", "getrefcount"):
                raise AttributeError(f"禁止修改 sys.{name}")
            super().__setattr__(name, value)

    safe_sys = SafeSys()

    # 受限 open
    def sandbox_open(file, mode="r", buffering=-1, encoding=None, errors=None, newline=None, closefd=True, opener=None):
        sandbox_temp = tempfile.gettempdir()
        abs_path = os.path.abspath(file)
        if not abs_path.startswith(sandbox_temp):
            raise PermissionError(f"沙盒禁止访问 {file} (不在临时目录中)")
        return open(file, mode, buffering, encoding, errors, newline, closefd, opener)

    # 安全导入 —— 允许导入 os/subprocess，但危险函数被 stub 掉
    def safe_import(name, *args, **kwargs):
        # 真正禁止的模块（泄露底层能力，无法安全包装）
        if name in ("ctypes", "multiprocessing", "pty", "tty", "termios", "winreg"):
            raise ImportError(f"沙盒禁止导入: {name}")

        # 允许导入但需要包装的模块
        if name == "os" or name.startswith("os."):
            return _make_safe_os()
        if name == "subprocess" or name.startswith("subprocess."):
            return _make_safe_subprocess()
        if name == "sys":
            return safe_sys

        # 白名单 + 允许列表直接放行
        base_name = name.split(".")[0]
        if base_name in SAFE_MODULES or base_name in allowed_modules:
            return __import__(name, *args, **kwargs)

        raise ImportError(f"沙盒禁止导入未白名单模块: {name}")

    # eval/exec
    def safe_eval(expr, globals=None, locals=None):
        if globals is None:
            globals = {}
        if "__builtins__" not in globals:
            globals["__builtins__"] = safe_builtins
        return eval(expr, globals, locals)

    def safe_exec(code, globals=None, locals=None):
        if globals is None:
            globals = {}
        if "__builtins__" not in globals:
            globals["__builtins__"] = safe_builtins
        exec(code, globals, locals)

    import builtins as _builtins

    safe_builtins = {
        # ---- 基础类型 ----
        "print": print, "len": len, "range": range,
        "list": list, "dict": dict, "tuple": tuple, "set": set,
        "frozenset": frozenset, "str": str, "bytes": bytes,
        "bytearray": bytearray, "int": int, "float": float,
        "complex": complex, "bool": bool, "object": object,

        # ---- 数学 / 迭代 ----
        "abs": abs, "round": round, "sum": sum, "min": min, "max": max,
        "sorted": sorted, "any": any, "all": all,
        "enumerate": enumerate, "zip": zip, "map": map, "filter": filter,
        "reversed": reversed, "iter": iter, "next": next,
        "range": range, "slice": slice, "pow": pow, "divmod": divmod,

        # ---- 类型 / 反射 ----
        "type": type, "isinstance": isinstance, "issubclass": issubclass,
        "callable": callable, "hasattr": hasattr, "getattr": getattr,
        "setattr": setattr, "delattr": delattr, "dir": dir, "vars": vars,
        "id": id, "hash": hash, "repr": repr, "format": format,
        "chr": chr, "ord": ord, "bin": bin, "hex": hex, "oct": oct,

        # ---- 类定义支持（关键修复）----
        "__build_class__": _builtins.__build_class__,
        "super": super, "property": property,
        "staticmethod": staticmethod, "classmethod": classmethod,
        "__name__": "__sandbox__",   # 类体里 __name__ 查得到的兜底

        # ---- 文件 / IO ----
        "open": sandbox_open if use_restricted_open else open,

        # ---- 沙盒封装 ----
        "eval": safe_eval, "exec": safe_exec,
        "globals": _builtins.globals,
        "locals": _builtins.locals,
        "__import__": safe_import,
    }

    # 清理系统模块中的危险函数
    try:
        import subprocess
        subprocess.Popen = lambda *a, **kw: (_ for _ in ()).throw(RuntimeError("subprocess.Popen disabled"))
        for attr in ["call", "check_call", "check_output", "run"]:
            if hasattr(subprocess, attr):
                setattr(subprocess, attr, lambda *a, **kw: (_ for _ in ()).throw(RuntimeError("subprocess disabled")))
    except Exception:
        pass
    try:
        import os
        for name in ["system", "popen", "spawnl", "spawnle", "spawnlp", "spawnlpe",
                     "spawnv", "spawnve", "spawnvp", "spawnvpe", "popen2", "popen3",
                     "popen4", "execl", "execle", "execlp", "execlpe",
                     "execv", "execve", "execvp", "execvpe"]:
            if hasattr(os, name):
                delattr(os, name)
    except Exception:
        pass

    return safe_sys, safe_builtins, safe_import, safe_eval, safe_exec


# ==================== 沙盒执行目标函数（需定义在顶层，确保可被 pickle） ====================


def _safe_exec_sandbox_target(code_str, output_queue, file_path=None, allowed_modules=None, cwd=None):
    """在子进程中执行 Python 代码（通用沙盒）"""
    import io
    import os
    import sys
    import traceback

    # 切换工作目录（如果指定）
    if cwd and os.path.isdir(cwd):
        os.chdir(cwd)

    safe_sys, safe_builtins, safe_import, safe_eval, safe_exec = _create_sandbox_env(
        use_restricted_open=True, allowed_modules=allowed_modules
    )

    namespace = {
        "__name__": "__sandbox__",
        "__file__": file_path or "<sandbox>",
        "__builtins__": safe_builtins,
        "__main__": None,
        "sys": safe_sys,
    }
    sys.stdout = io.StringIO()
    sys.stderr = io.StringIO()
    try:
        exec(compile(code_str, namespace["__file__"], "exec"), namespace)
        output = sys.stdout.getvalue()
        error = sys.stderr.getvalue()
        output_queue.put(("result", output, error))
    except Exception:
        error = traceback.format_exc()
        output_queue.put(("exception", error))


def _repl_sandbox_target(code_str, output_queue):
    """专门用于 REPL 的沙盒目标（与通用版本相同，但固定 file_path）"""
    _safe_exec_sandbox_target(code_str, output_queue, file_path="<repl>")


def _app_sandbox_target(code_str, args_str, output_queue):
    """在子进程中执行应用脚本的 main 函数，自适应参数个数，并提供假的 shell"""
    import inspect
    import io
    import shlex
    import sys
    import traceback

    safe_sys, safe_builtins, safe_import, safe_eval, safe_exec = _create_sandbox_env(use_restricted_open=True)

    namespace = {
        "__name__": "__app__",
        "__file__": "<app>",
        "__builtins__": safe_builtins,
        "__main__": None,
        "sys": safe_sys,
    }

    sys.stdout = io.StringIO()
    sys.stderr = io.StringIO()
    try:
        exec(compile(code_str, namespace["__file__"], "exec"), namespace)
        if "main" in namespace:
            main_func = namespace["main"]
            args_list = shlex.split(args_str) if args_str else []
            fake_shell = type("FakeShell", (), {"username": "sandbox"})()
            sig = inspect.signature(main_func)
            param_count = len(sig.parameters)
            if param_count == 1:
                main_func(args_list)
            elif param_count == 2:
                main_func(args_list, fake_shell)
            else:
                main_func(args_list)
        out = sys.stdout.getvalue()
        err = sys.stderr.getvalue()
        output_queue.put(("result", out, err))
    except Exception:
        err = traceback.format_exc()
        output_queue.put(("exception", err))


import multiprocessing
import os

# ==================== AI 动作沙盒 Worker ====================


def _ai_action_worker(task_queue, result_queue, data_dir):
    """AI 动作执行子进程：纯 VFS 操作，无任何 GUI 或主 Shell 依赖"""
    import io
    import os
    import queue
    import zipfile

    import kiki_os
    from kiki_os import Directory, File, VirtualFS

    kiki_os.DB_PATH = os.path.join(data_dir, "kiki_fs.db")
    kiki_os.init_db()
    fs = VirtualFS()

    while True:
        try:
            action, path, user, data = task_queue.get(timeout=1)
            if action is None:
                break
            result = False
            msg = ""
            try:
                if action == "MKDIR":
                    result = fs.mkdir(path, user)
                    msg = f"目录已创建: {path}" if result else "创建失败"
                elif action == "WRITE_FILE":
                    result = fs.write_file(path, data, user)
                    msg = f"文件已写入: {path}" if result else "写入失败"
                elif action == "DELETE_FILES":
                    node = fs.resolve(path, user)
                    if node:
                        if isinstance(node, Directory):
                            for child_name in list(node._children.keys()):
                                fs.delete(path + "/" + child_name, user, permanent=True)
                            result = True
                            msg = f"目录内容已清空: {path}"
                        elif isinstance(node, File):
                            result = fs.delete(path, user, permanent=True)
                            msg = f"文件已删除: {path}" if result else "删除失败"
                        else:
                            result = False
                            msg = "未知节点类型"
                    else:
                        result = False
                        msg = f"路径不存在: {path}"
                elif action == "COMPRESS":
                    try:
                        src_path, dst_path = path.split("|")
                    except ValueError:
                        result = False
                        msg = "COMPRESS 参数格式错误，应为 src|dst"
                        result_queue.put(
                            {
                                "action": action,
                                "path": path,
                                "result": result,
                                "msg": msg,
                            }
                        )
                        continue
                    src_node = fs.resolve(src_path, user)
                    if src_node is None:
                        result = False
                        msg = f"源路径不存在: {src_path}"
                        result_queue.put(
                            {
                                "action": action,
                                "path": path,
                                "result": result,
                                "msg": msg,
                            }
                        )
                        continue
                    zip_buffer = io.BytesIO()
                    with zipfile.ZipFile(zip_buffer, "w", zipfile.ZIP_DEFLATED) as zf:
                        if isinstance(src_node, File):
                            content = src_node.read()
                            zf.writestr(os.path.basename(src_path), content)
                        elif isinstance(src_node, Directory):

                            def add_dir_to_zip(current_node, current_path):
                                for name, child in current_node._children.items():
                                    child_path = current_path + "/" + name
                                    if isinstance(child, File):
                                        zf.writestr(child_path, child.read())
                                    elif isinstance(child, Directory):
                                        add_dir_to_zip(child, child_path)

                            add_dir_to_zip(src_node, os.path.basename(src_path))
                        else:
                            result = False
                            msg = "未知节点类型"
                            result_queue.put(
                                {
                                    "action": action,
                                    "path": path,
                                    "result": result,
                                    "msg": msg,
                                }
                            )
                            continue
                    zip_data = zip_buffer.getvalue()
                    if fs.write_file(dst_path, zip_data, user):
                        result = True
                        msg = f"压缩成功: {src_path} -> {dst_path}"
                    else:
                        result = False
                        msg = f"写入失败: {dst_path}"
                else:
                    result = False
                    msg = f"未知动作: {action}"
            except Exception as e:
                result = False
                msg = f"执行异常: {e}"
            result_queue.put({"action": action, "path": path, "result": result, "msg": msg})
        except queue.Empty:
            continue


def _run_app_script(app_code, args_str):
    """生成并执行一个隔离脚本，用于运行应用代码（不导入主模块）"""
    import subprocess
    import sys

    script = f"""
import sys
import shlex
import builtins
import inspect
import traceback

# 安全环境定义
SAFE_MODULES = {{
    "math", "random", "time", "datetime", "json", "re", "string",
    "itertools", "functools", "collections", "copy", "textwrap",
    "unicodedata", "difflib", "heapq", "bisect", "array", "struct",
    "enum", "dataclasses", "typing", "abc", "queue", "io", "pathlib",
    "hashlib", "hmac", "base64", "decimal", "fractions", "statistics",
    "platform", "os", "sys", "subprocess"
}}

def safe_import(name, *args, **kwargs):
    if name in ("ctypes", "socket", "select", "signal", "multiprocessing",
                 "threading", "pty", "tty", "termios", "winreg"):
        raise ImportError(f"沙盒禁止导入: {{name}}")
    if name == "builtins":
        return builtins
    base_name = name.split(".")[0]
    if base_name not in SAFE_MODULES:
        raise ImportError(f"沙盒禁止导入未白名单模块: {{name}}")
    module = __import__(name, *args, **kwargs)
    # 清理 os 危险函数
    if name == "os" or name.startswith("os."):
        for func in ["system", "popen", "spawnl", "spawnle", "spawnlp", "spawnlpe",
                     "spawnv", "spawnve", "spawnvp", "spawnvpe", "popen2", "popen3",
                     "popen4", "execl", "execle", "execlp", "execlpe",
                     "execv", "execve", "execvp", "execvpe"]:
            if hasattr(module, func):
                delattr(module, func)
    # 清理 subprocess 危险函数
    if name == "subprocess":
        module.Popen = lambda *a, **kw: (_ for _ in ()).throw(RuntimeError("subprocess.Popen disabled"))
        for func in ["call", "check_call", "check_output", "run"]:
            if hasattr(module, func):
                setattr(module, func, lambda *a, **kw: (_ for _ in ()).throw(RuntimeError("subprocess functions disabled")))
    return module

safe_builtins = dict(builtins.__dict__)
safe_builtins["__import__"] = safe_import
for dangerous in ["execfile", "input", "breakpoint", "help"]:
    safe_builtins.pop(dangerous, None)

namespace = {{
    "__name__": "__app__",
    "__file__": "<app>",
    "__builtins__": safe_builtins,
}}

try:
    exec(compile({app_code!r}, "<app>", "exec"), namespace)
    if "main" in namespace:
        main_func = namespace["main"]
        args_str_clean = {args_str!r} if {args_str!r} else ""
        args_list = shlex.split(args_str_clean) if args_str_clean else []
        sys.argv = ["app"] + args_list
        sig = inspect.signature(main_func)
        param_count = len(sig.parameters)
        if param_count == 1:
            main_func(args_str_clean)
        elif param_count == 2:
            class FakeShell:
                username = "sandbox"
            main_func(args_str_clean, FakeShell())
        else:
            main_func(args_str_clean)
    print("SUCCESS")
except Exception:
    traceback.print_exc()
    print("ERROR")
"""

    result = subprocess.run(
        [sys.executable, "-c", script],
        capture_output=True,
        text=True,
        timeout=10,
        creationflags=subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0,
    )

    if result.returncode != 0 or "ERROR" in result.stdout or "ERROR" in result.stderr:
        error_msg = (result.stderr + result.stdout).strip()
        return None, error_msg
    output = result.stdout.replace("SUCCESS", "").strip()
    return output, ""


def _run_plugin_script(plugin_path, func_name, args_str):
    """生成并执行一个隔离脚本，用于运行插件命令（不导入主模块）"""
    import subprocess
    import sys

    # 构造脚本内容
    script = f"""
import sys
import io
import shlex
import traceback

# 安全导入沙盒环境（从主模块复制，但不导入整个模块）
# 由于子进程无法直接导入主模块，我们仅使用内置的 _create_sandbox_env 函数定义？
# 但我们无法导入主模块，所以只能重新实现一个简化版。
# 为了不复杂化，我们在脚本中直接定义安全环境。

def create_sandbox_env():
    import builtins
    import io
    import sys
    safe_builtins = {{
        "print": print,
        "len": len,
        "range": range,
        "list": list,
        "dict": dict,
        "tuple": tuple,
        "set": set,
        "str": str,
        "int": int,
        "float": float,
        "bool": bool,
        "abs": abs,
        "round": round,
        "sum": sum,
        "min": min,
        "max": max,
        "sorted": sorted,
        "any": any,
        "all": all,
        "enumerate": enumerate,
        "zip": zip,
        "open": open,
        "eval": eval,
        "exec": exec,
        "globals": globals,
        "locals": locals,
        "hasattr": hasattr,
        "getattr": getattr,
        "setattr": setattr,
        "isinstance": isinstance,
        "callable": callable,
        "type": type,
        "issubclass": issubclass,
        "dir": dir,
        "vars": vars,
        "next": next,
        "iter": iter,
    }}
    return safe_builtins

safe_builtins = create_sandbox_env()
namespace = {{
    "__name__": "__plugin__",
    "__file__": {plugin_path!r},
    "__builtins__": safe_builtins,
}}

try:
    with open({plugin_path!r}, "r", encoding="utf-8") as f:
        code = f.read()
    exec(compile(code, {plugin_path!r}, "exec"), namespace)

    func = None
    if {func_name!r} in namespace:
        func = namespace[{func_name!r}]
    else:
        class FakeAPI:
            def __init__(self):
                self.commands = {{}}
            def register_command(self, name, func, help_text=""):
                self.commands[name] = func
            def add_menu_item(self, parent, text, callback):
                pass
        fake_api = FakeAPI()
        if "register" in namespace and callable(namespace["register"]):
            namespace["register"](fake_api)
            for cmd_name, f in fake_api.commands.items():
                if f.__name__ == {func_name!r}:
                    func = f
                    break

    if func is None:
        raise ValueError(f"插件中未找到函数 {{func_name}}")

    args_list = shlex.split({args_str!r}) if {args_str!r} else []
    result = func(args_list)
    print("SUCCESS")
except Exception:
    traceback.print_exc()
    print("ERROR")
"""

    # 执行脚本
    result = subprocess.run(
        [sys.executable, "-c", script],
        capture_output=True,
        text=True,
        timeout=10,
        creationflags=subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0,
    )

    if result.returncode != 0 or "ERROR" in result.stderr:
        return None, result.stderr
    return result.stdout, ""


# ===== 新增：独立的后台进程执行函数（避免 pickle） =====
def _subprocess_worker_global(cmd_line, output_queue):
    """
    这个函数会在独立线程中运行，但实际是启动一个子进程。
    注意：这个函数是在主进程中通过 threading 启动的，不是 multiprocessing，
         所以不需要 pickle，完全安全。
    """
    import subprocess
    import sys

    try:
        proc = subprocess.Popen(
            cmd_line,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            bufsize=1,
            creationflags=subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0,
        )
        # 实时读取输出
        for line in iter(proc.stdout.readline, ""):
            output_queue.put(("out", line))
        for line in iter(proc.stderr.readline, ""):
            output_queue.put(("err", line))
        proc.wait()
        output_queue.put(("status", proc.returncode))
    except Exception as e:
        output_queue.put(("err", f"子进程崩溃: {e}"))
    finally:
        output_queue.put(("done", None))


# ==================== 跨平台兼容层 ====================
class Platform:
    """平台抽象基类"""

    def __init__(self):
        self.name = "unknown"
        self._detect()

    def _detect(self):
        if sys.platform.startswith("win"):
            self.name = "windows"
        elif sys.platform.startswith("darwin"):
            self.name = "darwin"
        elif sys.platform.startswith("linux"):
            self.name = "linux"
        else:
            self.name = "other"

    def play_sound(self, sound_type="click"):
        """播放音效 - 子类重写"""

    def get_cpu_name(self):
        """获取CPU名称 - 子类重写"""
        return "Unknown CPU"

    def get_ram_mb(self):
        """获取内存大小(MB) - 子类重写"""
        return 128

    def get_storage_type(self):
        """获取存储类型 - 子类重写"""
        return "Unknown"

    def beep(self, freq, duration):
        """蜂鸣 - 子类重写"""


class WindowsPlatform(Platform):
    def __init__(self):
        super().__init__()
        try:
            import winsound

            self._winsound = winsound
            import winreg

            self._winreg = winreg
        except ImportError:
            self._winsound = None
            self._winreg = None

    def play_sound(self, sound_type="click"):
        if self._winsound is None:
            return
        try:
            alias_map = {
                "login": "SystemAsterisk",
                "shutdown": "SystemExit",
                "delete": "SystemHand",
                "click": "SystemDefault",
            }
            alias = alias_map.get(sound_type, "SystemDefault")
            self._winsound.PlaySound(alias, self._winsound.SND_ALIAS)
        except Exception:
            pass

    def get_cpu_name(self):
        if self._winreg is None:
            return "Intel Core i5 (Windows)"
        try:
            key = self._winreg.OpenKey(
                self._winreg.HKEY_LOCAL_MACHINE,
                r"HARDWARE\DESCRIPTION\System\CentralProcessor\0",
            )
            name = self._winreg.QueryValueEx(key, "ProcessorNameString")[0]
            self._winreg.CloseKey(key)
            return name.strip()
        except Exception:
            return "Intel Core i5-12400 (x86_64)"

    def get_ram_mb(self):
        try:
            import ctypes

            class MEMORYSTATUSEX(ctypes.Structure):
                _fields_ = [
                    ("dwLength", ctypes.c_ulong),
                    ("dwMemoryLoad", ctypes.c_ulong),
                    ("ullTotalPhys", ctypes.c_ulonglong),
                    ("ullAvailPhys", ctypes.c_ulonglong),
                    ("ullTotalPageFile", ctypes.c_ulonglong),
                    ("ullAvailPageFile", ctypes.c_ulonglong),
                    ("ullTotalVirtual", ctypes.c_ulonglong),
                    ("ullAvailVirtual", ctypes.c_ulonglong),
                    ("ullAvailExtendedVirtual", ctypes.c_ulonglong),
                ]

            mem = MEMORYSTATUSEX()
            mem.dwLength = ctypes.sizeof(MEMORYSTATUSEX)
            ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(mem))
            return int(mem.ullTotalPhys // (1024 * 1024))
        except Exception:
            return 128

    def get_storage_type(self):
        try:
            # 简单检测：检查是否 NVMe
            if os.path.exists("C:"):
                return "SSD"
            return "SATA SSD"
        except Exception:
            return "SSD"

    def beep(self, freq, duration):
        if self._winsound:
            try:
                self._winsound.Beep(freq, duration)
            except Exception:
                pass


class UnixPlatform(Platform):
    def __init__(self):
        super().__init__()
        self._has_termios = False
        try:
            import termios
            import tty

            self._termios = termios
            self._tty = tty
            self._has_termios = True
        except ImportError:
            pass

    def play_sound(self, sound_type="click"):
        # 使用系统 bell (控制台响铃)
        try:
            if sound_type in ("login", "shutdown", "delete"):
                sys.stdout.write("\a")
                sys.stdout.flush()
            else:
                sys.stdout.write("\a")
                sys.stdout.flush()
        except Exception:
            pass

    def get_cpu_name(self):
        try:
            with open("/proc/cpuinfo") as f:
                for line in f:
                    if "model name" in line:
                        return line.split(":")[1].strip()
        except Exception:
            pass
        try:
            import platform

            return platform.processor() or platform.uname().processor or "Unknown CPU"
        except Exception:
            return "Unknown CPU"

    def get_ram_mb(self):
        try:
            import os

            pages = os.sysconf("SC_PAGE_SIZE")
            phys_pages = os.sysconf("SC_PHYS_PAGES")
            return int((pages * phys_pages) // (1024 * 1024))
        except Exception:
            try:
                with open("/proc/meminfo") as f:
                    for line in f:
                        if line.startswith("MemTotal:"):
                            return int(line.split()[1]) // 1024
            except Exception:
                pass
            return 128

    def get_storage_type(self):
        try:
            if os.path.exists("/sys/block/nvme0n1"):
                return "NVMe SSD"
            elif os.path.exists("/sys/block/sda"):
                return "SATA SSD"
            else:
                return "SSD"
        except Exception:
            return "SSD"

    def beep(self, freq, duration):
        # Linux/macOS 使用命令行 beep
        try:
            import subprocess

            if sys.platform.startswith("darwin"):
                # macOS 使用 os.system 的 beep
                subprocess.run(["osascript", "-e", "beep"], check=False)
            else:
                # Linux 使用 echo -e 或者 /usr/bin/beep
                subprocess.run(["beep", "-f", str(freq), "-l", str(duration)], check=False)
        except Exception:
            # fallback: 终端响铃
            sys.stdout.write("\a")
            sys.stdout.flush()


class PlatformManager:
    """平台管理器 - 提供统一接口"""

    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._platform = cls._detect_platform()
        return cls._instance

    @staticmethod
    def _detect_platform():
        if sys.platform.startswith("win"):
            return WindowsPlatform()
        elif sys.platform.startswith("darwin") or sys.platform.startswith("linux"):
            return UnixPlatform()
        else:
            return UnixPlatform()  # fallback

    def __getattr__(self, name):
        return getattr(self._platform, name)


# 全局平台实例
PLATFORM = PlatformManager()


# ==================== 性能统计 ====================
class PerformanceStats:
    """性能统计 - 单例"""

    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._init()
        return cls._instance

    def _init(self):
        self.fs_ops = {
            "read": 0,
            "write": 0,
            "mkdir": 0,
            "delete": 0,
            "copy": 0,
            "move": 0,
        }
        self.vm_stats = {
            "page_faults": 0,
            "allocations": 0,
            "evictions": 0,
        }
        self.net_stats = {
            "packets_sent": 0,
            "packets_received": 0,
            "packets_lost": 0,
            "connections": 0,
        }
        self.sys_stats = {
            "cpu_usage": 0.0,
            "memory_usage": 0,
            "uptime": 0,
        }
        self._lock = threading.Lock()
        self.start_time = time.time()

    def record_fs_op(self, op_type):
        with self._lock:
            if op_type in self.fs_ops:
                self.fs_ops[op_type] += 1

    def record_vm_page_fault(self):
        with self._lock:
            self.vm_stats["page_faults"] += 1

    def record_vm_allocation(self):
        with self._lock:
            self.vm_stats["allocations"] += 1

    def record_vm_eviction(self):
        with self._lock:
            self.vm_stats["evictions"] += 1

    def record_net_sent(self):
        with self._lock:
            self.net_stats["packets_sent"] += 1

    def record_net_received(self):
        with self._lock:
            self.net_stats["packets_received"] += 1

    def record_net_lost(self):
        with self._lock:
            self.net_stats["packets_lost"] += 1

    def record_net_connection(self):
        with self._lock:
            self.net_stats["connections"] += 1

    def get_all(self):
        with self._lock:
            elapsed = time.time() - self.start_time
            return {
                "fs_ops": self.fs_ops.copy(),
                "vm": self.vm_stats.copy(),
                "net": self.net_stats.copy(),
                "uptime": elapsed,
            }

    def reset(self):
        with self._lock:
            self._init()
            self.start_time = time.time()


# 全局实例
PERF = PerformanceStats()


