    def __new__(cls):
        if not hasattr(cls, "_inst"):
            cls._inst = super().__new__(cls)
            cls._inst._lang = "en"
        return cls._inst

    def set_language(self, lang):
        if lang in self._data:
            self._lang = lang

    def get(self, key, *args):
        txt = self._data[self._lang].get(key, key)
        return txt.format(*args) if args else txt


