    # ===== 新增：长期记忆管理器（嵌套类） =====
    class LongTermMemory:
        """嵌套在 KIKIShell 内部的记忆管理器，直接使用 shell 的 VFS 和用户信息"""

        def __init__(self, shell):
            self.shell = shell
            # 使用用户目录下的数据库，实现用户隔离
            if shell.username:
                # 确保用户家目录存在
                home = f"/home/{shell.username}"
                if not shell.fs.resolve(home, "root"):
                    shell.fs.mkdir(home, user="root", owner=shell.username, mode=0o700)
                self.db_path = f"{home}/.kiki_memory.db"
            else:
                self.db_path = "kiki_memory.db"
            try:
                self._init_db()
            except sqlite3.OperationalError:
                # 如果家目录不存在或无法写入，回退到系统临时目录
                import os
                import tempfile

                fallback_dir = tempfile.gettempdir()
                self.db_path = os.path.join(
                    fallback_dir, f"kiki_memory_{shell.username or 'default'}.db"
                )
                self._init_db()

        def _init_db(self):
            import sqlite3

            conn = sqlite3.connect(self.db_path)
            # 开启 WAL 模式，提升并发读写性能
            conn.execute("PRAGMA journal_mode=WAL;")
            # 使用 FTS5 全文搜索
            conn.execute(
                "CREATE VIRTUAL TABLE IF NOT EXISTS memory_fts USING fts5(key, value, metadata, timestamp)"
            )
            conn.commit()
            conn.close()

        def add(self, key: str, value: str, metadata: str = ""):
            """存储一条记忆（覆盖已有）"""
            import sqlite3
            import time

            conn = sqlite3.connect(self.db_path)
            conn.execute("DELETE FROM memory_fts WHERE key = ?", (key,))
            conn.execute(
                "INSERT INTO memory_fts (key, value, metadata, timestamp) VALUES (?, ?, ?, ?)",
                (key, value, metadata, time.time()),
            )
            conn.commit()
            conn.close()
            return True

        def search(self, query: str, top_k: int = 5):
            """语义检索：返回 (key, value, metadata) 列表"""
            import sqlite3

            conn = sqlite3.connect(self.db_path)
            cur = conn.execute(
                "SELECT key, value, metadata FROM memory_fts WHERE value MATCH ? OR key MATCH ? LIMIT ?",
                (query, query, top_k),
            )
            results = cur.fetchall()
            conn.close()
            return results

        def remove(self, key: str) -> bool:
            import sqlite3

            conn = sqlite3.connect(self.db_path)
            cur = conn.execute("DELETE FROM memory_fts WHERE key = ?", (key,))
            conn.commit()
            conn.close()
            return cur.rowcount > 0

        def list_all(self):
            import sqlite3

            conn = sqlite3.connect(self.db_path)
            cur = conn.execute("SELECT key, value, metadata FROM memory_fts")
            results = cur.fetchall()
            conn.close()
            return results

