    def _sign_data(self, data_str):
        """使用 HMAC-SHA256 生成签名"""
        import hashlib
        import hmac

        return hmac.new(
            self._HASH_SECRET.encode(), data_str.encode("utf-8"), hashlib.sha256
        ).hexdigest()

    def _update_signature(self, data_str):
        import os

        signature = self._sign_data(data_str)
        sig_path = os.path.join(KIKI_DATA_DIR, "integrity.sig")
        try:
            with open(sig_path, "w") as f:
                f.write(signature)
        except Exception as e:
            print(f"⚠️ 宿主签名文件写入失败: {e}")

    def _verify_integrity(self):
        self.fs._node_cache.clear()
        self.fs._perm_cache.clear()

        passwd_content = self.fs.read_file("/etc/passwd", "root") or ""
        current_hash = self._sign_data(passwd_content)

        sig_path = os.path.join(KIKI_DATA_DIR, "integrity.sig")
        stored_signature = ""
        if os.path.exists(sig_path):
            with open(sig_path, "r") as f:
                stored_signature = f.read().strip()
        else:
            self._update_signature(passwd_content)
            return True

        return current_hash == stored_signature

    @command("sign", "system", "初始化或更新系统安全签名")
    def sign_cmd(self, args, src=None):
        # 允许 admin 初始化签名（新系统第一次需要），或者 root 执行
        if not self._is_admin():
            print("❌ 只有 root 或 admin 用户允许执行此命令。")
            return
        passwd_content = self.fs.read_file("/etc/passwd", "root") or ""
        self._update_signature(passwd_content)
        print("✅ 系统安全签名已成功更新！")

    def _auto_rollback_if_needed(self):
        """如果数据完整性校验失败，自动回滚到最近可用的快照"""
        if self._verify_integrity():
            return True

        print("\n⚠️ 检测到数据可能被篡改，正在尝试自动回滚...")

        snapshots = self.snapshot_mgr.list()
        if not snapshots:
            print("❌ 没有可用的快照，无法回滚！系统将拒绝启动。")
            return False

        latest_name = snapshots[0][0]
        print(f"🔄 正在恢复快照: {latest_name}")

        if not self.snapshot_mgr.restore(latest_name):
            print("❌ 快照恢复失败，系统将拒绝启动。")
            return False

        print("✅ 快照恢复成功！重新加载配置和数据...")

        self._load_users()
        self.config.config = self.config._load()

        # ===== 新增：强制重新签名，确保恢复后的数据与签名一致 =====
        print("📝 正在为恢复后的数据重新生成签名...")
        passwd_content = self.fs.read_file("/etc/passwd", "root") or ""
        self._update_signature(passwd_content)
        # ========================================================

        if not self._verify_integrity():
            print("❌ 即使恢复快照后数据仍然不匹配，可能是快照本身已损坏，拒绝启动。")
            return False

        print("✅ 恢复后数据完整性验证通过，继续启动。")
        return True

    @command("snapshot", "system", "创建、列出或恢复系统快照")
    def snapshot_cmd(self, args, src=None):
        parts = args.split()
        if not parts or parts[0] == "help":
            print("用法: snapshot create <说明> | list | restore <快照名/编号>")
            return

        sub = parts[0].lower()
        if sub == "create":
            desc = " ".join(parts[1:]) if len(parts) > 1 else ""
            self.snapshot_mgr.create(desc)
        elif sub == "list":
            snapshots = self.snapshot_mgr.list()
            if not snapshots:
                print("📭 还没有任何快照")
                return
            print("📋 可用快照:")
            for i, (name, ts, desc) in enumerate(snapshots, 1):
                print(f"  {i}. {name}  ({ts})  {desc}")
        elif sub == "restore":
            if len(parts) < 2:
                print("请指定要恢复的快照名或编号")
                return
            arg = parts[1]
            snapshots = self.snapshot_mgr.list()
            # 如果输入的是数字，则按编号恢复
            if arg.isdigit():
                idx = int(arg) - 1
                if 0 <= idx < len(snapshots):
                    snap_name = snapshots[idx][0]
                else:
                    print("❌ 编号超出范围")
                    return
            else:
                snap_name = arg
                # 检查是否存在
                if not any(s[0] == snap_name for s in snapshots):
                    print(f"❌ 快照 '{snap_name}' 不存在")
                    return
            self.snapshot_mgr.restore(snap_name)
        else:
            print("未知子命令。")

    @command("rollback", "system", "快速回滚到最近的一次快照")
    def rollback_cmd(self, args, src=None):
        snapshots = self.snapshot_mgr.list()
        if not snapshots:
            print("❌ 没有任何快照可回滚")
            return
        latest = snapshots[0][0]  # 列表第一个就是最新的
        print(f"🔄 正在回滚到最近快照: {latest}")
        self.snapshot_mgr.restore(latest)

