    # ===== 真·进程隔离（使用 threading + subprocess，无 pickle 问题） =====
    import os
    import queue
    import signal
    import subprocess
    import threading

    def start_isolated_process(self, cmd_line):
        """
        启动一个真正的系统进程，并返回其 PID。
        安全限制：
          - 仅允许 admin 用户调用
          - 只允许执行白名单命令（python, node, npm, git）
          - 禁止使用 -c / --eval / -e / -p 等执行代码的参数
          - 防止路径遍历（命令必须为白名单命令）
        """
        if not self._is_admin():
            raise PermissionError("只有管理员可以启动宿主机子进程")

        import shlex
        import subprocess
        import sys

        cmd_line = cmd_line.strip()
        if not cmd_line:
            raise ValueError("命令不能为空")

        ALLOWED_COMMANDS = {"python", "node", "npm", "git", "pip", "cmd", "powershell"}

        parts = shlex.split(cmd_line, posix=False)
        if not parts:
            raise ValueError("无法解析命令")

        cmd_name = os.path.basename(parts[0]).lower().replace(".exe", "")
        if cmd_name not in ALLOWED_COMMANDS:
            raise ValueError(f"只允许执行以下命令: {', '.join(ALLOWED_COMMANDS)}")

        # 禁止危险参数
        for arg in parts[1:]:
            if arg in ("-c", "--eval", "-e", "-p", "--print"):
                raise ValueError("禁止使用 -c/-e/-p 等执行代码的参数")

        # 强制 python 必须指定脚本文件
        if cmd_name == "python" and (len(parts) < 2 or parts[1].startswith("-")):
            raise ValueError("Python 命令必须指定一个脚本文件，不能使用 -c 等参数")

        proc = subprocess.Popen(
            parts,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            bufsize=1,
            creationflags=subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0,
        )
        pid = proc.pid

        if not hasattr(self, "real_processes"):
            self.real_processes = {}
        self.real_processes[pid] = proc

        def read_output():
            try:
                for line in iter(proc.stdout.readline, ""):
                    if self.gui_app and self.gui_app.winfo_exists():
                        self.gui_app._print(line)
                for line in iter(proc.stderr.readline, ""):
                    if self.gui_app and self.gui_app.winfo_exists():
                        self.gui_app._print(f"[错误] {line}")
                proc.wait()
                if self.gui_app and self.gui_app.winfo_exists():
                    self.gui_app._print(f"\n[子进程结束，返回码: {proc.returncode}]\n")
                    self.gui_app._do_print_prompt()
            except Exception as e:
                if self.gui_app and self.gui_app.winfo_exists():
                    self.gui_app._print(f"[子进程读取错误] {e}\n")
            finally:
                self.real_processes.pop(pid, None)

        threading.Thread(target=read_output, daemon=True).start()
        return pid

