    def _gui_input_dialog(self, prompt, title="输入", show=None, callback=None):
        if not hasattr(self, "gui_app") or not self.gui_app.winfo_exists():
            if callback:
                self.gui_app.after(0, lambda: callback(None))
            return

        import tkinter as tk

        dialog = tk.Toplevel(self.gui_app)
        dialog.title(title)
        dialog.geometry("320x150")
        dialog.resizable(False, False)
        dialog.transient(self.gui_app)
        dialog.grab_set()

        tk.Label(dialog, text=prompt, wraplength=300, justify="left").pack(pady=(10, 5))
        entry_var = tk.StringVar()
        entry = tk.Entry(dialog, textvariable=entry_var, show=show or "", width=25)
        entry.pack(pady=5)
        entry.focus_set()

        def on_ok():
            result = entry_var.get()
            dialog.destroy()
            if callback:
                self.gui_app.after(0, lambda: callback(result))

        def on_cancel():
            dialog.destroy()
            if callback:
                self.gui_app.after(0, lambda: callback(None))

        btn_frame = tk.Frame(dialog)
        btn_frame.pack(pady=5)
        tk.Button(btn_frame, text="确定", command=on_ok, width=8).pack(side="left", padx=5)
        tk.Button(btn_frame, text="取消", command=on_cancel, width=8).pack(side="left", padx=5)

        dialog.bind("<Return>", lambda e: on_ok())
        dialog.bind("<Escape>", lambda e: on_cancel())

    @command("register", "user", "cmd_register")
    def register(self, args, src=None):
        print(_("register"))
        if not hasattr(self, "gui_app") or not self.gui_app.winfo_exists():
            # 纯终端模式
            self._register_terminal()
            return

        # GUI 模式：启动第一步
        self.gui_app.after(0, self._gui_register_step1)

    # ---------- 终端注册 ----------
    def _register_terminal(self):
        new = input(_("choose_username")).strip().lower()
        if not new:
            print(_("username_empty"))
            return

        # 禁止注册保留用户名
        if new in self.RESERVED_USERNAMES:
            print(f"❌ 禁止创建系统保留用户名: {new}")
            return

        with self._lock:
            if new in self.users:
                print(_("user_exists", new))
                return

        p1 = getpass_star(_("password"))
        p2 = getpass_star(_("confirm_password"))
        if p1 != p2:
            print(_("passwords_mismatch"))
            return
        min_len = self.config.get("security.passwd_min_len", 6)
        if len(p1) < min_len:
            print(f"密码太短，至少需要 {min_len} 个字符。")
            return

        with self._lock:
            self.users[new] = hash_password(p1)
        self._save_users()
        self.ensure_home(new)
        self.fs._audit(f"REGISTER {new}", new)
        print(_("register_success", new))

    # ---------- GUI 注册状态机 ----------
    def _gui_register_step1(self):
        self._gui_input_dialog("请输入用户名:", "注册新用户", callback=self._gui_register_step2)

    def _gui_register_step2(self, username):
        if username is None:
            print("注册已取消")
            self.gui_app._do_print_prompt()
            return
        username = username.strip().lower()
        if not username:
            print(_("username_empty"))
            self.gui_app._do_print_prompt()
            return
        if username in self.RESERVED_USERNAMES:
            print(f"❌ 禁止创建系统保留用户名: {username}")
            self.gui_app._do_print_prompt()
            return
        with self._lock:
            if username in self.users:
                print(_("user_exists", username))
                self.gui_app._do_print_prompt()
                return
        self._gui_register_username = username
        self.gui_app.after(0, self._gui_register_step3)

    def _gui_register_step3(self):
        self._gui_input_dialog(
            f"用户 {self._gui_register_username} 的密码:",
            "输入密码",
            show="*",
            callback=self._gui_register_step4,
        )

    def _gui_register_step4(self, p1):
        if p1 is None:
            print("注册已取消")
            self.gui_app._do_print_prompt()
            return
        self._gui_register_password = p1
        self.gui_app.after(0, self._gui_register_step5)

    def _gui_register_step5(self):
        self._gui_input_dialog("确认密码:", "确认密码", show="*", callback=self._gui_register_step6)

    def _gui_register_step6(self, p2):
        if p2 is None:
            print("注册已取消")
            self.gui_app._do_print_prompt()
            return
        username = self._gui_register_username
        password = self._gui_register_password
        if password != p2:
            print(_("passwords_mismatch"))
            self.gui_app._do_print_prompt()
            return
        min_len = self.config.get("security.passwd_min_len", 6)
        if len(password) < min_len:
            print(f"密码太短，至少需要 {min_len} 个字符。")
            self.gui_app._do_print_prompt()
            return
        with self._lock:
            self.users[username] = hash_password(password)
        self._save_users()
        self.ensure_home(username)
        self.fs._audit(f"REGISTER {username}", username)
        print(_("register_success", username))
        self.gui_app._do_print_prompt()

    @command("deluser", "user", "删除当前用户账户并强制重新登录")
    def deluser_cmd(self, args, src=None):
        if not args:
            print("用法: deluser <用户名>")
            self._finalize_prompt()
            return
        target = args.strip().lower()

        # 只能删除自己
        if target != self.username:
            print("❌ 只能删除当前登录的用户")
            self._finalize_prompt()
            return

        # 禁止删除保留用户
        if target in self.RESERVED_USERNAMES:
            print(f"❌ 不能删除保留用户: {target}")
            self._finalize_prompt()
            return

        with self._lock:
            if target not in self.users:
                print(f"❌ 用户 '{target}' 不存在")
                self._finalize_prompt()
                return

            # 确认删除
            if hasattr(self, "gui_app") and self.gui_app and self.gui_app.winfo_exists():
                from tkinter import messagebox

                if not messagebox.askyesno(
                    "删除用户",
                    f"确定要删除用户 '{target}' 及其所有数据吗？\n此操作不可逆！",
                    icon="warning",
                ):
                    print("删除已取消")
                    self._finalize_prompt()
                    return
            else:
                ans = input(f"⚠️ 确定要删除用户 '{target}' 及其所有数据吗？(y/n): ").strip().lower()
                if ans != "y":
                    print("删除已取消")
                    self._finalize_prompt()
                    return

            # 删除家目录
            home_dir = f"/home/{target}"
            home_node = self.fs.resolve(home_dir, "root")
            if home_node and isinstance(home_node, Directory):
                self.fs.delete(home_dir, "root", permanent=True)
                print(f"✅ 已删除用户家目录: {home_dir}")
            else:
                print(f"⚠️ 用户家目录不存在或不是目录: {home_dir}")

            # 从用户字典移除
            del self.users[target]
            self._save_users()
            self.fs._audit(f"DELUSER {target}", self.username)
            print(f"✅ 用户 '{target}' 已删除，即将退出登录...")

        # 强制注销
        if hasattr(self, "gui_app") and self.gui_app and self.gui_app.winfo_exists():
            try:
                self.gui_app._logout()
            except Exception as e:
                print(f"⚠️ 注销过程出现异常: {e}")
                self.gui_app.destroy()
                import os
                import sys

                python = sys.executable
                os.execl(python, python, *sys.argv)
        else:
            self.running = False
            print("请重新登录。")

    @command("force_deluser", "admin", "强制删除任意用户（仅限管理员，不能删除 root）")
    def force_deluser_cmd(self, args, src=None):
        if not args:
            print("用法: force_deluser <用户名>")
            self._finalize_prompt()
            return
        target = args.strip().lower()

        if not self._is_admin():
            print("❌ 只有管理员可以使用此命令")
            self._finalize_prompt()
            return

        if target == "root":
            print("❌ 不能删除 root 超级管理员")
            self._finalize_prompt()
            return

        if target not in self.users:
            print(f"❌ 用户 '{target}' 不存在")
            self._finalize_prompt()
            return

        if hasattr(self, "gui_app") and self.gui_app and self.gui_app.winfo_exists():
            from tkinter import messagebox

            if not messagebox.askyesno(
                "强制删除用户", f"确定要强制删除用户 '{target}' 吗？", icon="warning"
            ):
                print("取消操作")
                self._finalize_prompt()
                return
        else:
            ans = input(f"⚠️ 确定要强制删除用户 '{target}' 吗？(y/n): ").strip().lower()
            if ans != "y":
                print("取消操作")
                self._finalize_prompt()
                return

        home_dir = f"/home/{target}"
        home_node = self.fs.resolve(home_dir, "root")
        if home_node and isinstance(home_node, Directory):
            self.fs.delete(home_dir, "root", permanent=True)
            print(f"✅ 已删除用户家目录: {home_dir}")
        else:
            print(f"⚠️ 用户家目录不存在或不是目录: {home_dir}")

        with self._lock:
            del self.users[target]
        self._save_users()
        self.fs._audit(f"FORCE_DELUSER {target}", self.username)
        print(f"✅ 用户 '{target}' 已强制删除！")
        self._finalize_prompt()

        if target == self.username:
            print("⚠️ 你已删除自己，即将退出登录...")
            if hasattr(self, "gui_app") and self.gui_app and self.gui_app.winfo_exists():
                try:
                    self.gui_app._logout()
                except Exception:
                    self.gui_app.destroy()
                    import os
                    import sys

                    python = sys.executable
                    os.execl(python, python, *sys.argv)
            else:
                self.running = False

    @command("passwd", "user", "cmd_passwd")
    def passwd(self, args, src=None):
        if not self.username:
            print("Not logged in.")
            return

        if not hasattr(self, "gui_app") or not self.gui_app.winfo_exists():
            self._passwd_terminal()
            return

        self.gui_app.after(0, self._passwd_step1)

    # ---------- 终端改密 ----------
    def _passwd_terminal(self):
        old = getpass_star("Current password: ")
        with self._lock:
            if not verify_password(self.users[self.username], old):
                print(_("incorrect_password"))
                return
        n1 = getpass_star("New password: ")
        n2 = getpass_star("Confirm new: ")
        if n1 != n2:
            print(_("passwords_mismatch"))
            return
        min_len = self.config.get("security.passwd_min_len", 6)
        if len(n1) < min_len:
            print(f"密码太短，至少需要 {min_len} 个字符。")
            return
        with self._lock:
            self.users[self.username] = hash_password(n1)
        self._save_users()
        self.fs._audit(f"PASSWD {self.username}", self.username)
        print(_("password_changed"))

    # ---------- GUI 改密状态机 ----------
    def _passwd_step1(self):
        self._gui_input_dialog("当前密码:", "修改密码", show="*", callback=self._passwd_step2)

    def _passwd_step2(self, old_pwd):
        if old_pwd is None:
            print("操作已取消")
            self.gui_app._do_print_prompt()
            return
        with self._lock:
            if not verify_password(self.users[self.username], old_pwd):
                print(_("incorrect_password"))
                self.gui_app._do_print_prompt()
                return
        self.gui_app.after(0, self._passwd_step3)

    def _passwd_step3(self):
        self._gui_input_dialog("新密码:", "修改密码", show="*", callback=self._passwd_step4)

    def _passwd_step4(self, new_pwd):
        if new_pwd is None:
            print("操作已取消")
            self.gui_app._do_print_prompt()
            return
        min_len = self.config.get("security.passwd_min_len", 6)
        if len(new_pwd) < min_len:
            print(f"密码太短，至少需要 {min_len} 个字符。")
            self.gui_app._do_print_prompt()
            return
        self._passwd_new_pwd = new_pwd
        self.gui_app.after(0, self._passwd_step5)

    def _passwd_step5(self):
        self._gui_input_dialog("确认新密码:", "修改密码", show="*", callback=self._passwd_step6)

    def _passwd_step6(self, confirm):
        if confirm is None:
            print("操作已取消")
            self.gui_app._do_print_prompt()
            return
        if self._passwd_new_pwd != confirm:
            print(_("passwords_mismatch"))
            self.gui_app._do_print_prompt()
            return
        with self._lock:
            self.users[self.username] = hash_password(self._passwd_new_pwd)
        self._save_users()
        self.fs._audit(f"PASSWD {self.username}", self.username)
        print(_("password_changed"))
        self.gui_app._do_print_prompt()

    @command("users", "admin", "cmd_users")
    def list_users(self, args, src=None):
        if not self._is_admin():
            print(_("permission_denied"))
            return
        print(_("registered_users"))
        with self._lock:
            for u in self.users:
                print(f"  {u}")

    @command("su", "user", "cmd_su")
    def su(self, args, src=None):
        if not args:
            print("用法: su <username>")
            return

        target = args.strip().lower()
        with self._lock:
            if target not in self.users:
                print(_("user_not_exist", target))
                return
            if target == self.username:
                print(_("already_logged_in"))
                return

        # 判断是否为 GUI 模式
        in_gui = hasattr(self, "gui_app") and self.gui_app and self.gui_app.winfo_exists()

        if in_gui:
            # GUI 模式：异步获取密码（使用自定义对话框）
            self._su_target = target
            self.gui_app.after(0, self._su_step1)
        else:
            # 终端模式
            self._su_terminal(target)

    # ---------- 终端模式 ----------
    def _su_terminal(self, target):
        pwd = getpass_star(_("password"))
        with self._lock:
            if not verify_password(self.users[target], pwd):
                print(_("auth_failed"))
                return
        # 安全加固：非 admin 不能切换到 root
        if target == "root" and not self._is_admin():
            print("❌ 只有 admin 可以切换到 root")
            return
        # 切换用户
        self.username = target
        self.memory_manager = self.LongTermMemory(self)
        # 清理文件系统缓存
        self.fs._node_cache.clear()
        self.fs._perm_cache.clear()
        if hasattr(self, "gui_app") and self.gui_app and self.gui_app.winfo_exists():
            self.gui_app.username = target
            self.gui_app._update_status()
            self.gui_app._refresh_all_file_managers(f"/home/{target}")
        home = self.ensure_home(target)
        self.fs.cwd = self.fs.resolve(home, target)
        self.config.load_user_config(target)
        self.apply_config()
        self._load_user_env()
        self.fs._audit(f"SU {target}", self.username)
        print(_("switched_user", target))

    # ---------- GUI 异步模式 ----------
    def _su_step1(self):
        self._gui_input_dialog(
            f"请输入 {self._su_target} 的密码:",
            "切换用户",
            show="*",
            callback=self._su_step2,
        )

    def _su_step2(self, pwd):
        if pwd is None:
            print("切换已取消")
            self.gui_app._do_print_prompt()
            return
        with self._lock:
            if not verify_password(self.users[self._su_target], pwd):
                print(_("auth_failed"))
                self.gui_app._do_print_prompt()
                return
        # 安全加固：非 admin 不能切换到 root
        if self._su_target == "root" and not self._is_admin():
            print("❌ 只有 admin 可以切换到 root")
            self.gui_app._do_print_prompt()
            return
        target = self._su_target
        self.username = target
        home = self.ensure_home(target)
        self.memory_manager = self.LongTermMemory(self)
        self.fs._node_cache.clear()
        self.fs._perm_cache.clear()
        home = self.ensure_home(target)
        root_resolved = self.fs.resolve(home, "root")
        if root_resolved is not None:
            self.fs.cwd = root_resolved
        else:
            self.fs.cwd = self.fs.root
            path_parts = home.split("/")[1:]
            temp = self.fs.cwd
            for part in path_parts:
                if part in temp._children:
                    temp = temp._children[part]
                else:
                    break
            if isinstance(temp, Directory):
                self.fs.cwd = temp
            else:
                self.fs.cwd = self.fs.root
        # ★ 先清缓存
        self.fs._node_cache.clear()
        self.fs._perm_cache.clear()

        # ★ 加载新用户配置
        self.config.load_user_config(target)
        self.apply_config()
        self._load_user_env()

        # ★ 同步更新 GUI
        self.gui_app.username = target
        self.gui_app._update_status()

        # ★ 重载固定项 / 挂件 / 壁纸
        try:
            self.gui_app._load_pinned_items()
        except Exception:
            pass
        try:
            if hasattr(self.gui_app, "_load_widgets"):
                self.gui_app._load_widgets()
        except Exception:
            pass
        try:
            self.gui_app._update_wallpaper()
        except Exception:
            pass

        # ★ 刷新文件管理器
        self.gui_app._refresh_all_file_managers(f"/home/{target}")

        # ★ 重建桌面图标（最后做）
        self.gui_app._create_desktop_icons()

        # ★ 刷新 Dock
        try:
            self.gui_app._update_dock()
        except Exception:
            pass

        self.fs._audit(f"SU {target}", self.username)
        print(_("switched_user", target))
        self.gui_app._do_print_prompt()

