    @command("find", "files", "cmd_find")
    def find_cmd(self, args, src=None):
        parts = args.split()
        if len(parts) != 2:
            print("Usage: find <path> <name>")
            return
        path, name = parts[0], parts[1]
        start = self.fs.resolve(path, self.username)
        if start is None:
            print(_("dir_not_found"))
            return
        total = 0

        def count_nodes(node):
            nonlocal total
            total += 1
            if isinstance(node, Directory):
                for child in node._children.values():
                    count_nodes(child)

        count_nodes(start)
        results = []
        if TQDM_AVAILABLE:
            with tqdm(total=total, desc="搜索中") as pbar:

                def search(node, current_path):
                    nonlocal results
                    if node.name == name:
                        results.append(
                            current_path + "/" + node.name if current_path else node.name
                        )
                    pbar.update(1)
                    if isinstance(node, Directory):
                        for child in node._children.values():
                            search(
                                child,
                                (current_path + "/" + node.name if current_path else node.name),
                            )

                search(start, "")
        else:
            results = self.fs.find(path, name, self.username)
        if results:
            for r in results:
                print(r)
        else:
            print(_("no_files_found"))

    @command("grep", "files", "cmd_grep")
    def grep_cmd(self, args, src=None):
        ignore = False
        parts = args.split()
        pattern = None
        target = None
        i = 0
        while i < len(parts):
            if parts[i] == "-i":
                ignore = True
                i += 1
            else:
                if pattern is None:
                    pattern = parts[i]
                else:
                    target = parts[i]
                i += 1
        if pattern is None:
            print("Usage: grep [-i] <pattern> [file]")
            return
        if src is not None:
            for line in src.splitlines():
                if ignore:
                    if pattern.lower() in line.lower():
                        print(line)
                else:
                    if pattern in line:
                        print(line)
            return
        if target is None:
            print("Usage: grep [-i] <pattern> <file>")
            return
        obj = self.fs.resolve(target, self.username)
        if obj is None:
            print(_("file_not_found"))
            return
        results = []
        if isinstance(obj, Directory):
            total_files = 0

            def count_files(node):
                nonlocal total_files
                if isinstance(node, File):
                    total_files += 1
                elif isinstance(node, Directory):
                    for child in node._children.values():
                        count_files(child)

            count_files(obj)
            if total_files == 0:
                print("目录中没有文件。")
                return
            if TQDM_AVAILABLE:
                with tqdm(total=total_files, desc="搜索中") as pbar:

                    def grep_dir(node, path_prefix=""):
                        if isinstance(node, File):
                            if self.fs.check_permission(self.username, node, "r"):
                                content = node.content
                                for idx, line in enumerate(content.splitlines(), 1):
                                    if ignore:
                                        if pattern.lower() in line.lower():
                                            results.append(
                                                (
                                                    f"{path_prefix}/{node.name}:{idx}",
                                                    line,
                                                )
                                            )
                                    else:
                                        if pattern in line:
                                            results.append(
                                                (
                                                    f"{path_prefix}/{node.name}:{idx}",
                                                    line,
                                                )
                                            )
                            pbar.update(1)
                        elif isinstance(node, Directory):
                            for child in node._children.values():
                                new_path = (
                                    f"{path_prefix}/{child.name}" if path_prefix else child.name
                                )
                                grep_dir(child, new_path)

                    grep_dir(obj)
            else:
                results = self.fs.grep(target, pattern, self.username, ignore)
        else:
            if isinstance(obj, File):
                content = obj.content
                for idx, line in enumerate(content.splitlines(), 1):
                    if ignore:
                        if pattern.lower() in line.lower():
                            results.append((f"{target}:{idx}", line))
                    else:
                        if pattern in line:
                            results.append((f"{target}:{idx}", line))
            else:
                print("目标不是文件或目录。")
                return
        if results:
            for loc, line in results:
                print(f"{loc}: {line}")
        else:
            print(_("no_matches"))

