    @command("kill", "system", "cmd_kill")
    def kill_cmd(self, args, src=None):
        if not self._is_admin():
            print(_("permission_denied"))
            return
        parts = args.split()
        if not parts:
            print("Usage: kill [-SIG] <PID>")
            return
        sig = None
        if parts[0].startswith("-"):
            sig_name = parts[0][1:].upper()
            if sig_name in self.signal_mgr.signals:
                sig = self.signal_mgr.signals[sig_name]
                pid = int(parts[1]) if len(parts) > 1 else None
            else:
                print(f"未知信号 {sig_name}")
                return
        else:
            pid = int(parts[0])
            sig = 15
        if pid is None:
            print("无效 PID")
            return
        if sig == 2:
            for job in self.proc.jobs.values():
                if job.get("pid") == pid:
                    job["status"] = "interrupted"
                    print(f"进程 {pid} 已中断")
                    return
        elif sig == 17:
            for job in self.proc.jobs.values():
                if job.get("pid") == pid:
                    job["status"] = "stopped"
                    print(f"进程 {pid} 已停止")
                    return
        else:
            if self.proc.kill(pid, self.username):
                self.fs._audit(
                    f"KILL {pid} SIG{list(self.signal_mgr.signals.keys())[list(self.signal_mgr.signals.values()).index(sig)]}",
                    self.username,
                )
                print(f"进程 {pid} 已终止")
            else:
                print(f"无进程 {pid}")

