    @command("tictac", "game", "井字棋")
    def tictac_cmd(self, args, src=None):
        """井字棋人机对战"""
        import queue
        import random

        in_gui = hasattr(self, "gui_app") and self.gui_app is not None

        board = [" "] * 9
        player = "X"
        ai = "O"
        game_over = False

        def print_board():
            lines = [
                "\n   " + " | ".join(board[0:3]),
                "  " + "-" * 11,
                "   " + " | ".join(board[3:6]),
                "  " + "-" * 11,
                "   " + " | ".join(board[6:9]) + "\n",
            ]
            if in_gui:
                for line in lines:
                    self.gui_app._print(line + "\n")
            else:
                for line in lines:
                    print(line)

        def check_winner(b, mark):
            wins = [
                (0, 1, 2),
                (3, 4, 5),
                (6, 7, 8),
                (0, 3, 6),
                (1, 4, 7),
                (2, 5, 8),
                (0, 4, 8),
                (2, 4, 6),
            ]
            for a, c, d in wins:
                if b[a] == b[c] == b[d] == mark:
                    return True
            return False

        def is_full(b):
            return " " not in b

        def ai_move(b):
            # 检查自己能否赢
            for i in range(9):
                if b[i] == " ":
                    b[i] = ai
                    if check_winner(b, ai):
                        b[i] = " "
                        return i
                    b[i] = " "
            # 阻止玩家赢
            for i in range(9):
                if b[i] == " ":
                    b[i] = player
                    if check_winner(b, player):
                        b[i] = " "
                        return i
                    b[i] = " "
            # 优先中心
            if b[4] == " ":
                return 4
            # 随机走
            empty = [i for i in range(9) if b[i] == " "]
            return random.choice(empty)

        def get_input_gui(prompt):
            """在主线程中显示对话框"""
            if not in_gui:
                return input(prompt)
            result_queue = queue.Queue()

            def ask():
                from tkinter import simpledialog

                try:
                    result = simpledialog.askstring("井字棋", prompt, parent=self.gui_app)
                    result_queue.put(result)
                except Exception:
                    result_queue.put(None)

            self.gui_app.after(0, ask)
            try:
                return result_queue.get(timeout=60)
            except Exception:
                return None

        def get_input(prompt):
            if in_gui:
                return get_input_gui(prompt)
            else:
                return input(prompt)

        def print_msg(msg):
            if in_gui:
                self.gui_app._print(msg + "\n")
            else:
                print(msg)

        print_msg("\n" + "=" * 50)
        print_msg("❌ 井字棋 (人机对战)".center(50))
        print_msg("=" * 50)
        print_msg("位置编号:")
        print_msg("   1 | 2 | 3 ")
        print_msg("  -----------")
        print_msg("   4 | 5 | 6 ")
        print_msg("  -----------")
        print_msg("   7 | 8 | 9 \n")
        print_msg("你是 X，电脑是 O\n")

        while not game_over:
            print_board()

            pos_input = get_input("请输入位置 (1-9, q退出): ")
            if pos_input is None:
                return
            pos_input = str(pos_input).strip()
            if pos_input.lower() == "q":
                print_msg("游戏结束！")
                return

            try:
                pos = int(pos_input) - 1
                if pos < 0 or pos > 8 or board[pos] != " ":
                    print_msg("❌ 无效位置！\n")
                    continue
            except ValueError:
                print_msg("❌ 请输入数字！\n")
                continue

            board[pos] = player
            if check_winner(board, player):
                print_board()
                print_msg("🎉 你赢了！")
                game_over = True
                return
            if is_full(board):
                print_board()
                print_msg("🤝 平局！")
                game_over = True
                return

            ai_pos = ai_move(board)
            board[ai_pos] = ai
            print_msg(f"🤖 AI 选择了位置 {ai_pos + 1}")

            if check_winner(board, ai):
                print_board()
                print_msg("😅 AI 赢了！")
                game_over = True
                return
            if is_full(board):
                print_board()
                print_msg("🤝 平局！")
                game_over = True
                return

    @command("breakout", "game", "打砖块")
    def breakout_cmd(self, args, src=None):
        """打砖块游戏 - 使用 Canvas"""
        if not hasattr(self, "gui_app") or not self.gui_app:
            print("❌ 打砖块游戏需要 GUI 环境！")
            print("请在图形界面中运行。")
            return

        # 使用 after 在主线程中创建窗口
        def create_game():
            try:
                import tkinter as tk

                root = tk.Toplevel(self.gui_app)
                root.title("🧱 打砖块")
                root.geometry("600x450")
                root.resizable(False, False)

                canvas = tk.Canvas(root, width=600, height=450, bg="#1a1a2e")
                canvas.pack()

                # 球
                ball = canvas.create_oval(290, 400, 310, 420, fill="white")
                ball_dx, ball_dy = 3, -4

                # 挡板
                paddle = canvas.create_rectangle(250, 430, 350, 440, fill="#4CAF50")

                # 砖块
                bricks = []
                colors = [
                    "#ff6b6b",
                    "#ffd93d",
                    "#6bcb77",
                    "#4d96ff",
                    "#ff6b6b",
                    "#ffd93d",
                ]
                for row in range(6):
                    for col in range(8):
                        x1 = col * 70 + 25
                        y1 = row * 25 + 30
                        x2 = x1 + 60
                        y2 = y1 + 20
                        brick = canvas.create_rectangle(
                            x1,
                            y1,
                            x2,
                            y2,
                            fill=colors[row % len(colors)],
                            outline="#1a1a2e",
                        )
                        bricks.append(brick)

                score = 0
                score_label = canvas.create_text(
                    580, 10, text=f"得分: {score}", fill="white", anchor="ne"
                )
                lives = 3
                lives_label = canvas.create_text(
                    20, 10, text=f"❤️ {lives}", fill="white", anchor="nw"
                )

                def move_paddle(event):
                    x = event.x
                    x = max(x, 30)
                    x = min(x, 570)
                    canvas.coords(paddle, x - 50, 430, x + 50, 440)

                canvas.bind("<Motion>", move_paddle)

                def game_loop():
                    nonlocal ball_dx, ball_dy, score, lives
                    if not root.winfo_exists():
                        return

                    ball_pos = canvas.coords(ball)
                    if ball_pos[0] <= 0 or ball_pos[2] >= 600:
                        ball_dx = -ball_dx
                    if ball_pos[1] <= 0:
                        ball_dy = -ball_dy

                    if ball_pos[3] >= 450:
                        lives -= 1
                        canvas.itemconfig(lives_label, text=f"❤️ {lives}")
                        if lives <= 0:
                            canvas.create_text(
                                300,
                                200,
                                text="游戏结束",
                                fill="red",
                                font=("Arial", 30),
                            )
                            return
                        canvas.coords(ball, 290, 400, 310, 420)
                        ball_dx, ball_dy = 3, -4
                        root.after(1000, game_loop)
                        return

                    paddle_pos = canvas.coords(paddle)
                    if (
                        ball_pos[2] >= paddle_pos[0]
                        and ball_pos[0] <= paddle_pos[2]
                        and ball_pos[3] >= paddle_pos[1]
                        and ball_pos[3] <= paddle_pos[3]
                    ):
                        ball_dy = -ball_dy

                    canvas.move(ball, ball_dx, ball_dy)

                    ball_pos = canvas.coords(ball)
                    for brick in bricks[:]:
                        brick_pos = canvas.coords(brick)
                        if (
                            ball_pos[2] >= brick_pos[0]
                            and ball_pos[0] <= brick_pos[2]
                            and ball_pos[3] >= brick_pos[1]
                            and ball_pos[1] <= brick_pos[3]
                        ):
                            canvas.delete(brick)
                            bricks.remove(brick)
                            ball_dy = -ball_dy
                            score += 10
                            canvas.itemconfig(score_label, text=f"得分: {score}")
                            break

                    if not bricks:
                        canvas.create_text(
                            300,
                            200,
                            text="🎉 你赢了！",
                            fill="green",
                            font=("Arial", 30),
                        )
                        return

                    root.after(16, game_loop)

                game_loop()
                root.mainloop()
            except Exception as e:
                self.gui_app._print(f"❌ 游戏启动失败: {e}\n")

        # 在主线程中执行
        self.gui_app.after(0, create_game)

    @command("settings", "admin", "cmd_settings")
    def settings_cmd(self, args, src=None):
        if not self._is_admin():
            print(_("permission_denied"))
            return
        parts = args.split()
        if not parts:
            print(_("settings_usage"))
            return
        sub = parts[0].lower()
        if sub == "list":
            groups = self.config.get_groups()
            all_items = dict(self.config.list_all())
            for g, keys in groups.items():
                print(f"\n=== {g} ===")
                for k in keys:
                    if k in all_items:
                        print(f"  {k} = {all_items[k]}")
        elif sub == "get":
            if len(parts) < 2:
                print(_("settings_get_usage"))
                return
            print(f"{parts[1]} = {self.config.get(parts[1])}")
        elif sub == "set":
            if len(parts) < 3:
                print(_("settings_set_usage"))
                return
            key = parts[1]
            value = " ".join(parts[2:])
            if value.lower() == "true":
                value = True
            elif value.lower() == "false":
                value = False
            else:
                try:
                    value = int(value)
                except ValueError:
                    try:
                        value = float(value)
                    except ValueError:
                        pass
            if self.config.set(key, value, self.username):
                print(_("settings_set_ok", key, value))
                if key.startswith("prompt.style"):
                    self.prompt_style = value
                elif key.startswith("network.hostname"):
                    self.hostname = value
                elif key.startswith("animations.speed"):
                    self.anim_speed = float(value) if isinstance(value, (int, float)) else 1.0
                elif key.startswith("game.auto_save"):
                    self.game_auto_save = int(value) if isinstance(value, int) else 30
                elif key.startswith("theme.colorscheme"):
                    self.theme = value
                elif key == "locale.language":
                    Translator().set_language(value)
                elif key.startswith("ai."):
                    self._apply_ai()
                elif key.startswith("desktop."):
                    if hasattr(self, "gui_app") and self.gui_app:
                        self.gui_app._update_wallpaper()
            else:
                print(_("permission_denied"))
        elif sub == "reset":
            self.config.reset()
            self.apply_config()
            print(_("settings_reset"))
        elif sub == "save":
            self.config.save_user_config(self.username)
            print(_("settings_saved"))
        elif sub == "tui":
            if hasattr(self, "gui_app") and self.gui_app and self.gui_app.winfo_exists():
                self.gui_app._open_settings()
            else:
                self._settings_tui()
        else:
            print(_("settings_unknown"))

    def _settings_tui(self):
        try:
            import curses

            curses.wrapper(self._tui_curses)
        except Exception:
            print(_("settings_tui_unavailable"))

    def _tui_curses(self, stdscr):
        import curses

        curses.curs_set(0)
        stdscr.clear()
        groups = self.config.get_groups()
        items = []
        for cat, keys in groups.items():
            items.append((cat, None))
            for k in keys:
                items.append((k, self.config.get(k)))
        cur = 0
        while True:
            stdscr.clear()
            h, _w = stdscr.getmaxyx()
            for idx, (name, value) in enumerate(items):
                if idx == cur:
                    stdscr.attron(curses.A_REVERSE)
                if value is None:
                    stdscr.addstr(idx, 0, f"=== {name} ===")
                else:
                    display = (
                        value
                        if not name.endswith(".api_key")
                        else (value[:4] + "..." if value else "")
                    )
                    stdscr.addstr(idx, 0, f"{name}: {display}")
                if idx == cur:
                    stdscr.attroff(curses.A_REVERSE)
            stdscr.addstr(h - 2, 0, _("settings_tui_nav"))
            stdscr.refresh()
            key = stdscr.getch()
            if key == curses.KEY_UP:
                cur = (cur - 1) % len(items)
            elif key == curses.KEY_DOWN:
                cur = (cur + 1) % len(items)
            elif key == ord("\n"):
                name, value = items[cur]
                if value is not None:
                    stdscr.move(h - 1, 0)
                    stdscr.clrtoeol()
                    stdscr.addstr(h - 1, 0, f"New value for {name}: ")
                    curses.echo()
                    new = stdscr.getstr(h - 1, len(f"New value for {name}: "), 60).decode("utf-8")
                    curses.noecho()
                    stdscr.move(h - 1, 0)
                    stdscr.clrtoeol()
                    if isinstance(value, bool):
                        new = new.lower() == "true"
                    elif isinstance(value, int):
                        try:
                            new = int(new)
                        except ValueError:
                            new = value
                    elif isinstance(value, float):
                        try:
                            new = float(new)
                        except ValueError:
                            new = value
                    if self.config.set(name, new, self.username):
                        if name.startswith("prompt.style"):
                            self.prompt_style = new
                        elif name.startswith("network.hostname"):
                            self.hostname = new
                        elif name.startswith("animations.speed"):
                            self.anim_speed = float(new) if isinstance(new, (int, float)) else 1.0
                        elif name.startswith("game.auto_save"):
                            self.game_auto_save = int(new) if isinstance(new, int) else 30
                        elif name.startswith("theme.colorscheme"):
                            self.theme = new
                        elif name == "locale.language":
                            Translator().set_language(new)
                        elif name.startswith("ai."):
                            self._apply_ai()
                        items[cur] = (name, self.config.get(name))
            elif key == 27:
                break
        self.config.save_user_config(self.username)

