    @command("basic", "program", "cmd_basic")
    def basic_cmd(self, args, src=None):
        """BASIC 解释器：basic <file.bas>"""
        if not args:
            print("Usage: basic <filename.bas>")
            return

        content = self.fs.read_file(args, self.username)
        if content is None:
            print(_("basic_file_not_found", args))
            return

        # ---------- 1. 解析行号 ----------
        program = {}
        for lineno_str, raw in enumerate(content.splitlines(), 1):
            line = raw.strip()
            if not line:
                continue
            if line.upper().startswith("REM ") or line.startswith("'"):
                continue
            parts = line.split(maxsplit=1)
            if not parts[0].isdigit():
                print(_("basic_syntax_error", f"第 {lineno_str} 行缺少行号: {line}"))
                return
            program[int(parts[0])] = parts[1].strip() if len(parts) > 1 else ""

        if not program:
            print(_("basic_no_lines"))
            return

        # ---------- 2. 运行时状态 ----------
        variables = {}

        def is_valid_var(name):
            """合法变量名：字母开头，可含字母/数字/下划线，可选 $ 结尾"""
            return bool(re.match(r"^[A-Za-z][A-Za-z0-9_]*\$?$", name))

        def get_value(token):
            """把操作数解析成值。"""
            token = token.strip()
            if not token:
                raise NameError("空操作数")

            # 纯字符串字面量（内部不含引号）
            if re.fullmatch(r'"[^"]*"', token):
                return token[1:-1]

            # 整数字面量（支持 +/- 前缀）
            if token.isdigit():
                return int(token)
            if token[0] in ("+", "-") and token[1:].isdigit():
                return int(token)

            # 变量
            if token in variables:
                return variables[token]

            raise NameError(f"变量未定义: {token}")

        def eval_expr(expr):
            """求值：字符串 / 数字 / 变量 / 数学表达式"""
            expr = expr.strip()
            if not expr:
                raise ValueError("空表达式")

            # 纯字符串字面量（内部不含引号）
            if re.fullmatch(r'"[^"]*"', expr):
                return expr[1:-1]

            # 单变量
            if expr in variables:
                return variables[expr]

            # 整数字面量（支持 +/- 前缀）
            if expr.isdigit():
                return int(expr)
            if expr[0] in ("+", "-") and expr[1:].isdigit():
                return int(expr)

            # ★ 关键修复：标识符扫描前，先把字符串字面量抠掉
            no_strings = re.sub(r'"[^"]*"', "", expr)
            MATH_FUNCS = {
                "sin", "cos", "tan", "asin", "acos", "atan",
                "sqrt", "log", "log10", "exp", "pi", "e",
            }
            for ident in re.findall(r"[A-Za-z][A-Za-z0-9_]*\$?", no_strings):
                if ident in variables or ident in MATH_FUNCS:
                    continue
                raise NameError(f"变量未定义: {ident}")

            # 变量替换（按长度倒序，避免 a 命中 abc）
            temp = expr
            for var in sorted(variables.keys(), key=len, reverse=True):
                if var in temp:
                    val = variables[var]
                    if isinstance(val, str):
                        temp = temp.replace(var, f'"{val}"')
                    else:
                        temp = temp.replace(var, str(val))

            # 含字符串 → 必须是 "字符串" (+ "字符串")* 的形式
            if '"' in temp:
                pattern = r'^\s*"[^"]*"\s*(?:\+\s*"[^"]*"\s*)*$'
                if not re.fullmatch(pattern, temp):
                    raise ValueError(
                        f"字符串表达式格式错误，只允许 \"字符串\" + \"字符串\" 的形式: {expr}"
                    )
                str_parts = re.findall(r'"([^"]*)"', temp)
                return "".join(str_parts)

            # 纯数学表达式
            result = self._safe_math_eval(temp)
            if result is None:
                raise ValueError(f"Invalid expression: {expr}")
            return result

        def next_line(n):
            for k in sorted(program.keys()):
                if k > n:
                    return k
            return None

        # ---------- 3. 主循环 ----------
        ip = min(program.keys())
        stack = []

        while True:
            if ip not in program:
                print(f"Runtime error: line {ip} missing")
                break

            stmt = program[ip].strip()
            if not stmt:
                ip = next_line(ip)
                continue

            upper = stmt.upper()

            # ----- NEXT -----
            if upper.startswith("NEXT"):
                if not stack:
                    print("Runtime error: NEXT without FOR")
                    break
                var, start, end, step, next_ip = stack.pop()
                variables[var] += step
                if (step > 0 and variables[var] <= end) or (step < 0 and variables[var] >= end):
                    ip = next_ip
                    stack.append((var, start, end, step, next_ip))
                else:
                    ip = next_line(ip)
                continue

            # ----- PRINT -----
            if upper.startswith("PRINT"):
                rest = stmt[5:].strip()
                if not rest:
                    print()
                else:
                    out = []
                    for p in rest.split(";"):
                        p = p.strip()
                        if not p:
                            continue
                        if p.startswith('"') and p.endswith('"'):
                            out.append(p[1:-1])
                        else:
                            try:
                                v = eval_expr(p)
                                out.append(str(v))
                            except (NameError, ValueError) as e:
                                print(f"Runtime error at line {ip}: {e}")
                                out = None
                                break
                    if out is not None:
                        print(" ".join(out))

            # ----- INPUT -----
            elif upper.startswith("INPUT"):
                is_string_input = upper.startswith("INPUT$")
                offset = 6 if is_string_input else 5
                rest = stmt[offset:].strip()

                if not rest:
                    print(f"Runtime error at line {ip}: INPUT 缺少变量名")
                    break

                if rest.startswith('"'):
                    endq = rest.find('"', 1)
                    if endq == -1:
                        print(f"Runtime error at line {ip}: INPUT 提示字符串未闭合")
                        break
                    prompt = rest[1:endq]
                    var = rest[endq + 1:].strip().lstrip(";").strip()
                else:
                    prompt = "? "
                    var = rest.strip()

                if not var:
                    print(f"Runtime error at line {ip}: INPUT 缺少变量名")
                    break
                if not is_valid_var(var):
                    print(f"Runtime error at line {ip}: 非法变量名 {var}")
                    break

                inp = self._basic_input(prompt)
                if inp is None:
                    ip = next_line(ip)
                    continue
                if is_string_input or var.endswith("$"):
                    variables[var] = str(inp)
                else:
                    try:
                        variables[var] = int(inp)
                    except (ValueError, TypeError):
                        variables[var] = str(inp)

            # ----- LET / 直接赋值 -----
            elif upper.startswith("LET"):
                rest = stmt[3:].strip() if upper.startswith("LET ") else stmt
                if "=" not in rest:
                    print(f"Syntax error: LET {rest}")
                    break
                var, expr = rest.split("=", 1)
                var = var.strip()
                if not is_valid_var(var):
                    print(f"Runtime error at line {ip}: 非法变量名 {var}")
                    break
                try:
                    variables[var] = eval_expr(expr.strip())
                except (NameError, ValueError) as e:
                    print(f"Runtime error at line {ip}: {e}")
                    break

            # ----- 隐式赋值：A = 5 -----
            elif "=" in stmt and not upper.startswith(
                ("IF", "FOR", "PRINT", "INPUT", "GOTO", "END", "NEXT", "CLS", "REM")
            ):
                if not any(op in stmt for op in ("==", "<>", "<=", ">=")):
                    var, expr = stmt.split("=", 1)
                    var = var.strip()
                    if is_valid_var(var):
                        try:
                            variables[var] = eval_expr(expr.strip())
                        except (NameError, ValueError) as e:
                            print(f"Runtime error at line {ip}: {e}")
                            break
                    else:
                        print(f"Runtime error at line {ip}: 非法变量名 {var}")
                        break
                else:
                    print(f"Unknown statement: {stmt}")
                    break

            # ----- IF ... THEN <line> -----
            elif upper.startswith("IF"):
                rest = stmt[2:].strip()
                if " THEN " not in rest.upper():
                    print("Syntax error: missing THEN")
                    break
                idx = rest.upper().index(" THEN ")
                cond = rest[:idx].strip()
                target = rest[idx + 6:].strip()
                if not target.isdigit():
                    print(f"THEN target must be line number, got {target}")
                    break

                m = re.match(
                    r'^(.+?)\s*(==|=|!=|<>|<=|>=|<|>)\s*(.+)$',
                    cond,
                )
                if not m:
                    print(f"Invalid condition {cond}")
                    break
                left, op, right = m.groups()

                try:
                    lv = get_value(left)
                    rv = get_value(right)
                except NameError as e:
                    print(f"Runtime error at line {ip}: {e}")
                    break

                if isinstance(lv, str) or isinstance(rv, str):
                    if op in ("=", "=="):
                        truth = lv == rv
                    elif op in ("<>", "!="):
                        truth = lv != rv
                    else:
                        print(f"Runtime error at line {ip}: 字符串只支持 = 和 <> 比较")
                        break
                else:
                    try:
                        if op in ("=", "=="):
                            truth = lv == rv
                        elif op in ("<>", "!="):
                            truth = lv != rv
                        elif op == "<":
                            truth = lv < rv
                        elif op == ">":
                            truth = lv > rv
                        elif op == "<=":
                            truth = lv <= rv
                        elif op == ">=":
                            truth = lv >= rv
                        else:
                            print(f"Runtime error at line {ip}: 未知运算符 {op}")
                            break
                    except TypeError as e:
                        print(f"Runtime error at line {ip}: 类型不匹配 ({e})")
                        break

                if truth:
                    ip = int(target)
                    continue

            # ----- GOTO -----
            elif upper.startswith("GOTO"):
                target = stmt[4:].strip()
                if not target.isdigit():
                    print(f"GOTO target must be line number, got {target}")
                    break
                ip = int(target)
                continue

            # ----- FOR var = a TO b [STEP c] -----
            elif upper.startswith("FOR"):
                rest = stmt[3:].strip()
                m = re.match(
                    r"^([A-Za-z][A-Za-z0-9_]*\$?)\s*=\s*(-?\d+)\s+TO\s+(-?\d+)(?:\s+STEP\s+(-?\d+))?$",
                    rest,
                    re.IGNORECASE,
                )
                if not m:
                    print(f"Runtime error at line {ip}: FOR 语法错误: {stmt}")
                    break
                var, start, end, step = m.groups()
                if var.endswith("$"):
                    print(f"Runtime error at line {ip}: FOR 循环变量不能是字符串变量 ({var})")
                    break
                start = int(start)
                end = int(end)
                step = int(step) if step else 1
                variables[var] = start
                next_ip = next_line(ip)
                stack.append((var, start, end, step, next_ip))

            # ----- END -----
            elif upper.startswith("END"):
                break

            # ----- CLS -----
            elif upper.startswith("CLS"):
                if hasattr(self, "gui_app") and self.gui_app:
                    self.gui_app._clear_terminal()
                else:
                    os.system("cls" if os.name == "nt" else "clear")

            else:
                print(f"Unknown statement: {stmt}")
                break

            ip = next_line(ip)

    @command("attrib", "files", "cmd_attrib")
    def attrib_cmd(self, args, src=None):
        parts = args.split()
        if not parts:
            print("Usage: attrib [+r|-r] <file>  or  attrib <file>")
            return
        if parts[0].startswith("+") or parts[0].startswith("-"):
            if len(parts) < 2:
                print("Need file name")
                return
            op = parts[0][0]
            attr = parts[0][1:]
            path = parts[1]
            node = self.fs.resolve(path, self.username)
            if node is None:
                print(_("file_not_found"))
                return
            if attr == "r":
                if op == "+":
                    node.mode &= ~0o200
                    print(f"Set read-only for {path}")
                else:
                    node.mode |= 0o200
                    print(f"Removed read-only for {path}")
            else:
                print("Only +r/-r supported for read-only attribute")
            return
        path = parts[0]
        node = self.fs.resolve(path, self.username)
        if node is None:
            print(_("file_not_found"))
            return
        perm = self._format_perm(node)
        print(f"{perm}  {node.owner}  {node.name}")

    @command("chkdsk", "system", "cmd_chkdsk")
    def chkdsk_cmd(self, args, src=None):
        print("Checking file system...")
        errors = 0
        visited = set()

        def check_node(node, path=""):
            nonlocal errors
            node_id = id(node)
            if node_id in visited:
                print(f"  Circular reference detected at {path}")
                errors += 1
                return
            visited.add(node_id)
            if isinstance(node, Directory):
                for name, child in node._children.items():
                    child_path = f"{path}/{name}" if path else name
                    check_node(child, child_path)
            else:
                if node.mode & 0o400 == 0 and self.username != "root":
                    print(f"  Warning: {path} has no read permission")
                    errors += 1

        check_node(self.fs.root)
        if errors == 0:
            print("File system is clean.")
        else:
            print(f"Found {errors} errors.")

    @command("fc", "files", "cmd_fc")
    def fc_cmd(self, args, src=None):
        parts = args.split()
        if len(parts) != 2:
            print("Usage: fc <file1> <file2>")
            return
        f1, f2 = parts[0], parts[1]
        content1 = self.fs.read_file(f1, self.username)
        content2 = self.fs.read_file(f2, self.username)
        if content1 is None or content2 is None:
            print("One or both files not found")
            return
        lines1 = content1.splitlines()
        lines2 = content2.splitlines()
        max_len = max(len(lines1), len(lines2))
        diff = False
        for i in range(max_len):
            l1 = lines1[i] if i < len(lines1) else ""
            l2 = lines2[i] if i < len(lines2) else ""
            if l1 != l2:
                print(f"Line {i+1} differs:")
                print(f"< {l1}")
                print(f"> {l2}")
                diff = True
        if not diff:
            print("Files are identical.")

    @command("join", "files", "cmd_join")
    def join_cmd(self, args, src=None):
        parts = args.split()
        if len(parts) < 3:
            print("Usage: join <output> <file1> <file2> ...")
            return
        output = parts[0]
        files = parts[1:]
        all_content = []
        for f in files:
            content = self.fs.read_file(f, self.username)
            if content is None:
                print(f"File {f} not found, aborting")
                return
            all_content.append(content)
        combined = "\n".join(all_content)
        if self.fs.write_file(output, combined, self.username):
            print(f"Files joined into {output}")
        else:
            print("Failed to write output")

