    @command("tail", "files", "cmd_tail")
    def tail_cmd(self, args, src=None):
        if src is not None:
            lines = src.splitlines()
            n = 10
            parts = args.split()
            if parts and parts[0] == "-n" and len(parts) > 1:
                try:
                    n = int(parts[1])
                except Exception:
                    pass
            if n <= 0:
                return
            start = max(0, len(lines) - n)
            for line in lines[start:]:
                print(line)
            return
        parts = args.split()
        n = 10
        file = None
        i = 0
        while i < len(parts):
            if parts[i] == "-n" and i + 1 < len(parts):
                try:
                    n = int(parts[i + 1])
                    i += 2
                except Exception:
                    i += 1
            else:
                file = parts[i]
                i += 1
        if file is None:
            print("Usage: tail [-n N] <file>")
            return
        content = self.fs.read_file(file, self.username)
        if content is None:
            print(_("tail_error", file))
            return
        lines = content.splitlines()
        if n <= 0:
            return
        start = max(0, len(lines) - n)
        for line in lines[start:]:
            print(line)

