    @command("3d", "game", "3D 渲染演示（支持 cube, sphere, field, sine）")
    def render_3d_cmd(self, args, src=None):
        """3d [模式] - 3D 图形演示
        模式: cube, sphere, field, sine
        """
        import math
        import threading
        import time
