    @command("xcopy", "files", "cmd_xcopy")
    def xcopy_cmd(self, args, src=None):
        parts = args.split()
        src = dst = None
        rec = over = False
        for p in parts:
            if p.startswith("/"):
                if p[1:].lower() in ("s", "e"):
                    rec = True
                elif p[1:].lower() == "y":
                    over = True
            else:
                if src is None:
                    src = p
                elif dst is None:
                    dst = p
        if not src or not dst:
            print(_("xcopy_usage"))
            return
        src_obj = self.fs.resolve(src, self.username)
        if src_obj is None:
            print(_("xcopy_source_not_found", src))
            return
        dst_is_dir = dst.endswith("/") or (
            self.fs.resolve(dst, self.username) is not None
            and isinstance(self.fs.resolve(dst, self.username), Directory)
        )
        dst_abs = dst + ("/" + src_obj.name if dst_is_dir else "")
        gui_app = self.gui_app if hasattr(self, "gui_app") else None
        if isinstance(src_obj, Directory):
            if not rec:
                print(_("xcopy_missing_s"))
                return
            total_files = 0

            def count_files(node):
                nonlocal total_files
                if isinstance(node, File):
                    total_files += 1
                elif isinstance(node, Directory):
                    for child in node._children.values():
                        count_files(child)

            count_files(src_obj)
            if total_files == 0:
                print("空目录，无需复制。")
                return
            if TQDM_AVAILABLE:
                with tqdm(total=total_files, desc=f"复制目录 {src}") as pbar:

                    def copy_with_progress(src_node, dst_parent, dst_name):
                        if isinstance(src_node, File):
                            if dst_name in dst_parent._children and not over:
                                if gui_app and gui_app.winfo_exists():
                                    if not messagebox.askyesno(
                                        "覆盖确认",
                                        _("overwrite", dst_name),
                                        parent=gui_app,
                                    ):
                                        pbar.update(1)
                                        return
                                else:
                                    print(_("overwrite", dst_name), end="")
                                    if input().strip().lower() != "y":
                                        pbar.update(1)
                                        return
                            dst_parent._children[dst_name] = File(
                                dst_name,
                                dst_parent,
                                src_node.content,
                                self.username,
                                src_node.mode,
                            )
                            pbar.update(1)
                        elif isinstance(src_node, Directory):
                            new_dir = Directory(dst_name, dst_parent, self.username, src_node.mode)
                            dst_parent._children[dst_name] = new_dir
                            for child in src_node._children.values():
                                copy_with_progress(child, new_dir, child.name)

                    dst_parent = self.fs.resolve(os.path.dirname(dst_abs), self.username)
                    if dst_parent is None:
                        print("目标路径不存在")
                        return
                    copy_with_progress(src_obj, dst_parent, src_obj.name)
                print(_("xcopy_dir_success", src, dst_abs))
            else:
                if self.fs.copy(src, dst_abs, self.username, interactive=not over, gui_app=gui_app):
                    print(_("xcopy_dir_success", src, dst_abs))
                else:
                    print("Copy failed.")
        else:
            if TQDM_AVAILABLE:
                with tqdm(total=1, desc=f"复制文件 {src}") as pbar:
                    if self.fs.copy(
                        src,
                        dst_abs,
                        self.username,
                        interactive=not over,
                        gui_app=gui_app,
                    ):
                        pbar.update(1)
                        print(_("xcopy_file_success", src, dst_abs))
                    else:
                        print("Copy failed.")
            else:
                if self.fs.copy(src, dst_abs, self.username, interactive=not over, gui_app=gui_app):
                    print(_("xcopy_file_success", src, dst_abs))
                else:
                    print("Copy failed.")

    @command("mount", "files", "cmd_mount")
    def mount_cmd(self, args, src=None):
        parts = args.split()
        if len(parts) < 2:
            print("Usage: mount <remote_url> <mount_point> [username] [password]")
            return
        url = parts[0]
        mount_point = parts[1].rstrip("/")
        username = parts[2] if len(parts) > 2 else "guest"
        password = parts[3] if len(parts) > 3 else None
        if not HAS_REQUESTS:
            print("requests 库未安装，无法挂载远程")
            return
        if mount_point in self.remote_mounts:
            print(f"挂载点 {mount_point} 已存在")
            return
        remote = RemoteNode(url, username, password)
        remote_fs = RemoteFS(self.fs, mount_point, remote)
        if not self.fs.resolve(mount_point, self.username):
            self.fs.mkdir(mount_point, user=self.username, owner=self.username, mode=0o755)
        self.remote_mounts[mount_point] = remote_fs
        print(f"挂载 {url} 到 {mount_point} 成功")

    @command("umount", "files", "cmd_umount")
    def umount_cmd(self, args, src=None):
        if not args:
            print("Usage: umount <mount_point>")
            return
        mp = args.strip().rstrip("/")
        if mp in self.remote_mounts:
            del self.remote_mounts[mp]
            print(f"卸载 {mp} 成功")
        else:
            print(f"{mp} 未挂载")

    @command("pipe", "ipc", "cmd_pipe")
    def pipe_cmd(self, args, src=None):
        parts = args.split()
        if len(parts) < 2:
            print("Usage: pipe create|read|write|delete <name> [data]")
            return
        action = parts[0]
        name = parts[1]
        if action == "create":
            self.ipc.create_pipe(name)
            print(f"管道 {name} 创建")
        elif action == "read":
            p = self.ipc.get_pipe(name)
            if p:
                data = p.read(timeout=1)
                print(data if data is not None else "(空)")
            else:
                print(f"管道 {name} 不存在")
        elif action == "write":
            if len(parts) < 3:
                print("缺少数据")
                return
            data = " ".join(parts[2:])
            p = self.ipc.get_pipe(name)
            if p:
                p.write(data)
                print("写入成功")
            else:
                print(f"管道 {name} 不存在")
        elif action == "delete":
            self.ipc.delete_pipe(name)
            print(f"管道 {name} 删除")
        else:
            print("未知操作")

    @command("shm", "ipc", "cmd_shm")
    def shm_cmd(self, args, src=None):
        parts = args.split()
        if len(parts) < 2:
            print("Usage: shm create|read|write|delete <name> [offset] [data] [size]")
            return
        action = parts[0]
        name = parts[1]
        if action == "create":
            size = int(parts[2]) if len(parts) > 2 else 1024
            self.ipc.create_shm(name, size)
            print(f"共享内存 {name} 创建，大小 {size}")
        elif action == "read":
            offset = int(parts[2]) if len(parts) > 2 else 0
            length = int(parts[3]) if len(parts) > 3 else 100
            shm = self.ipc.get_shm(name)
            if shm:
                data = shm.read(offset, length)
                print(data)
            else:
                print(f"共享内存 {name} 不存在")
        elif action == "write":
            if len(parts) < 4:
                print("用法: shm write <name> <offset> <data>")
                return
            offset = int(parts[2])
            data = parts[3]
            shm = self.ipc.get_shm(name)
            if shm:
                shm.write(offset, data)
                print("写入成功")
            else:
                print(f"共享内存 {name} 不存在")
        elif action == "delete":
            self.ipc.delete_shm(name)
            print(f"共享内存 {name} 删除")
        else:
            print("未知操作")

    @command("profile", "system", "cmd_profile")
    def profile_cmd(self, args, src=None):
        """profile [reset|all] - 显示性能统计"""
        parts = args.split()
        if parts and parts[0] == "reset":
            PERF.reset()
            print("性能统计已重置")
