        self.dir_entry = ctk.CTkEntry(path_frame, placeholder_text="/home/admin", width=250)
        self.dir_entry.pack(side="left", padx=5)
        # 👇 核心修复：创建时立刻判断是否有传入路径
        if self.target_path:
            self.dir_entry.delete(0, "end")
            self.dir_entry.insert(0, self.target_path)
        else:
            self.dir_entry.insert(0, "/home/admin")

        mode_frame = ctk.CTkFrame(tab, fg_color="transparent")
        mode_frame.pack(fill="x", padx=10, pady=5)
        ctk.CTkLabel(mode_frame, text="扫描模式:").pack(side="left", padx=5)
        self.mode_var = ctk.StringVar(value="quick")
