class VideoPlayer(KikiWindow):
    def __init__(self, master, video_data, title="视频播放器"):
        super().__init__(master, title=title, width=850, height=550)

        # ===== 锁死 self.gui 指向主窗口 =====
        import tkinter as tk

        if tk._default_root and isinstance(tk._default_root, KIKIGUI):
            self.gui = tk._default_root

        self._temp_file = None
        self._closed = False

        self._main_gui = self.gui
        self._my_id = id(self)

        # ===== 导入 vlc 并检查 =====
        try:
            import tempfile

            import vlc

            self.vlc = vlc
        except ImportError:
            ctk.CTkLabel(
                self.content_frame,
                text="请安装 python-vlc: pip install python-vlc",
                font=("Arial", 14),
            ).pack(expand=True)
            return

        # ===== 预处理视频数据 =====
        try:
            if isinstance(video_data, str):
                import base64

                video_data = base64.b64decode(video_data)

            self._temp_file = tempfile.NamedTemporaryFile(
                suffix=".mp4", delete=True, prefix="kiki_video_"
            )
            self._temp_file.write(video_data)
            self._temp_file.flush()
        except Exception as e:
            ctk.CTkLabel(
                self.content_frame, text=f"❌ 视频数据读取失败: {e}", font=("Arial", 14)
            ).pack(expand=True)
            self.after(100, self.destroy)
            return

        # ===== 创建视频显示框架 =====
        self.video_frame = ctk.CTkFrame(self.content_frame, fg_color="#000000", height=350)
        self.video_frame.pack(fill="both", expand=True, padx=5, pady=5)

        # ===== VLC 初始化 =====
        import io
        import sys

        old_stdout = sys.stdout
        old_stderr = sys.stderr
        sys.stdout = io.StringIO()
        sys.stderr = io.StringIO()

        try:
            self.instance = vlc.Instance(["--quiet"])
            if self.instance is None:
                raise Exception("vlc.Instance() 初始化失败，请检查 VLC 是否安装正确。")

            self.player = self.instance.media_player_new()
            media = self.instance.media_new(self._temp_file.name)
            self.player.set_media(media)

            self._create_controls()
            self.after(300, self._embed_player)
            self.after(500, self._start_playback)

        except Exception as e:
            self._cleanup_temp_file()
            ctk.CTkLabel(self.content_frame, text=f"❌ 视频加载失败: {e}", font=("Arial", 14)).pack(
                expand=True
            )
            self.after(100, self.destroy)

        finally:
            captured_out = sys.stdout.getvalue()
            captured_err = sys.stderr.getvalue()
            sys.stdout = old_stdout
            sys.stderr = old_stderr

            def filter_lines(text):
                return "\n".join(
                    line for line in text.splitlines() if "SetThumbNailClip" not in line
                )

            filtered_out = filter_lines(captured_out)
            filtered_err = filter_lines(captured_err)

            if filtered_out:
                print(filtered_out, file=sys.stdout, flush=True)
            if filtered_err:
                print(filtered_err, file=sys.stderr, flush=True)

    def _cleanup_temp_file(self):
        if self._temp_file:
            try:
                self._temp_file.close()
            except Exception:
                pass
            self._temp_file = None

    def _embed_player(self):
        try:
            self.update_idletasks()
            hwnd = self.video_frame.winfo_id()
            self.player.set_hwnd(hwnd)
            self._embedded = True
        except Exception as e:
            print(f"VLC 嵌入失败: {e}")
            self._embedded = False

    def _start_playback(self):
        try:
            self.player.play()
            self._playing = True
            self.play_btn.configure(text="⏸ 暂停")

            # ===== 新增：判断当前媒体是否是纯音频 =====
            self.after(500, self._check_media_type)  # 延迟判断，等 VLC 解析完媒体信息

            self._update_progress()
        except Exception as e:
            print(f"播放启动失败: {e}")

    def _check_media_type(self):
        """检测媒体是否包含视频流，如果纯音频则隐藏黑色画布"""
        if not self.winfo_exists():
            return
        try:
            # VLC 获取视频宽高，如果为0说明没有视频流
            video_width = self.player.video_get_width()
            video_height = self.player.video_get_height()

            if video_width == 0 and video_height == 0:
                # 纯音频模式：隐藏黑色画布，显示音频封面/文字
                self.video_frame.pack_forget()
                self.audio_cover = ctk.CTkLabel(
                    self.content_frame,
                    text="🎵 正在播放音频",
                    font=("Arial", 24),
                    fg_color="#1a1a1e",
                )
                self.audio_cover.pack(fill="both", expand=True, padx=5, pady=5)
            else:
                # 有视频模式：确保视频画布显示
                self.audio_cover.pack_forget() if hasattr(self, "audio_cover") else None
                self.video_frame.pack(fill="both", expand=True, padx=5, pady=5)
        except Exception:
            pass

    def _create_controls(self):
        control_frame = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        control_frame.pack(fill="x", padx=10, pady=5)

        progress_frame = ctk.CTkFrame(control_frame, fg_color="transparent")
        progress_frame.pack(fill="x", pady=2)

        self.time_label = ctk.CTkLabel(
            progress_frame, text="00:00 / 00:00", font=("Arial", 10), width=100
        )
        self.time_label.pack(side="left", padx=5)

        self.progress_slider = ctk.CTkSlider(
            progress_frame, from_=0, to=1000, command=self._on_progress_drag
        )
        self.progress_slider.pack(side="left", fill="x", expand=True, padx=5)

        btn_frame = ctk.CTkFrame(control_frame, fg_color="transparent")
        btn_frame.pack(pady=5)

        self.play_btn = ctk.CTkButton(
            btn_frame, text="▶ 播放", command=self._toggle_pause, width=80
        )
        self.play_btn.pack(side="left", padx=3)

        ctk.CTkButton(btn_frame, text="⏹ 停止", command=self._stop, width=80).pack(
            side="left", padx=3
        )

        ctk.CTkLabel(btn_frame, text="🔊", font=("Arial", 14)).pack(side="left", padx=5)
        self.volume_slider = ctk.CTkSlider(
            btn_frame, from_=0, to=100, command=self._on_volume_change, width=80
        )
        self.volume_slider.set(80)
        self.volume_slider.pack(side="left", padx=5)

        ctk.CTkButton(btn_frame, text="⛶ 全屏", command=self._toggle_fullscreen, width=80).pack(
            side="left", padx=3
        )
        ctk.CTkButton(btn_frame, text="✕ 关闭", command=self.destroy, width=80).pack(
            side="left", padx=3
        )

    def _toggle_pause(self):
        if self._playing:
            self.player.pause()
            self._playing = False
            self.play_btn.configure(text="▶ 播放")
        else:
            self.player.play()
            self._playing = True
            self.play_btn.configure(text="⏸ 暂停")

    def _stop(self):
        self.player.stop()
        self._playing = False
        self.play_btn.configure(text="▶ 播放")
        self.progress_slider.set(0)

    def _on_volume_change(self, value):
        self.player.audio_set_volume(int(value))

    def _on_progress_drag(self, value):
        self._progress_dragging = True
        if self.player.get_length() > 0:
            new_time = int((value / 1000) * self.player.get_length())
            self.player.set_time(new_time)
            self.after(100, lambda: setattr(self, "_progress_dragging", False))

    def _update_progress(self):
        if not self.winfo_exists():
            return
        try:
            length = self.player.get_length() // 1000
            current = self.player.get_time() // 1000
            if length > 0:
                self.time_label.configure(
                    text=f"{current//60:02d}:{current%60:02d} / {length//60:02d}:{length%60:02d}"
                )
                if not self._progress_dragging:
                    self.progress_slider.set((current / length) * 1000)
        except Exception:
            pass
        self.after(500, self._update_progress)

    def _toggle_fullscreen(self):
        if self._maximized:
            if self._normal_geometry:
                self.geometry(self._normal_geometry)
            self._maximized = False
        else:
            self._normal_geometry = self.geometry()
            sw = self.winfo_screenwidth()
            sh = self.winfo_screenheight()
            self.geometry(f"{sw}x{sh}+0+0")
            self._maximized = True

    def destroy(self):
        if self._closed:
            return
        self._closed = True

        # 第一步：确保 VLC 完全停止并释放资源
        try:
            if hasattr(self, "player") and self.player:
                self.player.stop()
                # 解除嵌入（关键！）
                if hasattr(self.player, "set_hwnd"):
                    self.player.set_hwnd(0)  # Windows
                elif hasattr(self.player, "set_xwindow"):
                    self.player.set_xwindow(0)  # Linux
                # 释放媒体和播放器实例
                media = self.player.get_media()
                if media:
                    media.release()
                self.player.release()
        except Exception as e:
            print(f"VLC 资源释放异常: {e}")

        # 第二步：清除临时文件
        self._cleanup_temp_file()

        # 第三步：物理除名（同步执行，抢在 Tk 销毁前）
        if self.gui and hasattr(self.gui, "_remove_window"):
            self.gui._remove_window(self)

        # 第四步：父类销毁（此时 VLC 已断开，窗口可彻底释放）
        super().destroy()


class KIKIPetPanel(KikiWindow):
    def __init__(self, master, shell):
        super().__init__(master, title="🐱 KIKI Pet 属性面板", width=400, height=350, resizable=False)
        self.shell = shell
        self.master_gui = master

        self._alive = True
        self._after_ids = []
        self._msg_timer = None          # 消息定时器 ID

        # 获取桌面那只真正的 Pet
        if not hasattr(self.master_gui, 'pet') or self.master_gui.pet is None:
            self.master_gui.pet = Pet(self.master_gui)
        self.pet = self.master_gui.pet

        self.pet_stats = {"hunger": 5, "happiness": 5}

        self.emoji_display = ctk.CTkLabel(self.content_frame, text="🐱", font=("Segoe UI Emoji", 70), anchor="center")
        self.emoji_display.pack(pady=(20, 10))

        self.term = ctk.CTkTextbox(self.content_frame, font=("Courier New", 12), state="disabled", wrap="none", height=100)
        self.term.pack(fill="x", padx=20, pady=10)

        self.msg_label = ctk.CTkLabel(self.content_frame, text="按 [1]喂食 [2]抚摸 [3]睡觉 [Q]退出", font=("Arial", 11))
        self.msg_label.pack(pady=10)

        self._update_display()
        self.bind("<Key>", self._on_key)
        self.focus_set()
        self.protocol("WM_DELETE_WINDOW", self._safe_destroy)

    def _add_safe_after(self, ms, func):
        """安全的 after 包装器：记录任务ID，且只在窗口存活时执行"""
        if not self._alive:
            return None
        def safe_func(*args, **kwargs):
            if self.winfo_exists() and self._alive:
                func(*args, **kwargs)
        tid = self.after(ms, safe_func)
        self._after_ids.append(tid)
        return tid

    def _safe_destroy(self):
        """取消所有排队的任务，再销毁窗口"""
        self._alive = False
        for tid in self._after_ids:
            try:
                self.after_cancel(tid)
            except Exception:
                pass
        self._after_ids.clear()

        if self._msg_timer is not None:
            try:
                self.after_cancel(self._msg_timer)
            except Exception:
                pass
            self._msg_timer = None

        try:
            if self.winfo_exists():
                self.destroy()
        except Exception:
            pass

    def _update_display(self):
        if not self.winfo_exists() or not self._alive:
            return
        self.term.configure(state="normal")
        self.term.delete("1.0", "end")

        hunger = "█" * self.pet_stats["hunger"] + "░" * (10 - self.pet_stats["hunger"])
        happy = "█" * self.pet_stats["happiness"] + "░" * (10 - self.pet_stats["happiness"])

        self.term.insert("end", f"😺 心情: {happy}\n🍖 饥饿: {hunger}\n")
        self.term.configure(state="disabled")

    def _show_message(self, text):
        if not self.winfo_exists() or not self._alive:
            return
        self.msg_label.configure(text=text, text_color="#00ff00")

        if self._msg_timer is not None:
            try:
                self.after_cancel(self._msg_timer)
            except Exception:
                pass
            self._msg_timer = None

        def clear_msg():
            if self.winfo_exists() and self._alive:
                self.msg_label.configure(text="按 [1]喂食 [2]抚摸 [3]睡觉 [Q]退出", text_color="white")
            self._msg_timer = None

        self._msg_timer = self._add_safe_after(2000, clear_msg)

    def _on_key(self, event):
        key = event.keysym.lower()
        if key == 'q':
            self._show_message("👋 属性面板已关闭，小猫继续在桌上溜达")
            self._add_safe_after(500, self._safe_destroy)
            return

        if key == '1':
            self.pet_stats["hunger"] = min(10, self.pet_stats["hunger"] + 3)
            self.pet._set_emoji_temporarily("😻", 3000)
            self.pet.set_mood("😊")
            self.pet.show_bubble("🍣 谢谢你喂我小鱼干！")
            self._show_message("🍣 喂食成功，小猫超开心！")
        elif key == '2':
            self.pet_stats["happiness"] = min(10, self.pet_stats["happiness"] + 3)
            self.pet._set_emoji_temporarily("😊", 3000)
            self.pet.set_mood("😊")
            self.pet.show_bubble("✋ 呼噜呼噜...好舒服~")
            self._show_message("✋ 你摸了摸小猫的头，它很舒服~")
        elif key == '3':
            self.pet._set_emoji_temporarily("😴", 3000)
            self.pet.set_mood("😴")
            self.pet.show_bubble("💤 我要睡觉啦... Zzz")
            self._show_message("💤 小猫闭上眼睛睡了...")

        self._update_display()


import threading

from pypinyin import Style, pinyin


class PinyinIMEWindow(KikiWindow):
    def __init__(self, master, shell):
        super().__init__(master, title="KIKI笑话输入法", width=500, height=420)
        self.shell = shell
        self._alive = True
        self._last_result = ""
        self._saved_ime_text = ""
        self._last_candidates = []
        self._processing = False  # 防止重复提交

        # 硬编码拦截表
        self.hardcode_map = {
            "woshishabi": "我是傻逼",
            "woyaoyaosinidemama": "我要咬死你妈妈",
            "caonima": "草泥马",
            "wobengbuzhule": "我绷不住了",
            "woyaotiaolou": "我要跳楼",
            "wotainanle": "我太难了",
            "zhenshabi": "真傻逼",
            "zhuangbiworangnifeiqilai": "装逼我让你飞起来",
            "woyouyiduiyinxingdechibang": "我有一对隐形的翅膀",
            "niyaoshibugaosuwowobuzhidao": "你要是不告诉我我不知道",
            "wo qu ni ma le ge bi de": "我去你妈的了个逼的",
            "nihaoyoumoya": "你好幽默呀",
        }

        self._build_index()

        ctk.CTkLabel(
            self.content_frame,
            text="输入拼音（空格分隔），回车自动翻译",
            font=("Arial", 11),
        ).pack(pady=10)

        self._ime_input = ctk.CTkEntry(
            self.content_frame, width=300, placeholder_text="例如: wo xiang chi fan"
        )
        self._ime_input.pack(pady=5)
        self._ime_input.bind("<Return>", self._on_enter)

        self._ime_input.bind("<KeyRelease>", self._save_current_text)

        # 焦点守卫
        self._ime_input.bind("<FocusOut>", lambda e: self.after(10, self._force_focus))
        self._ime_input.bind("<FocusIn>", self._restore_text)
        self.bind("<FocusIn>", self._force_focus)
        self.after(100, self._force_focus)

        self.term = ctk.CTkTextbox(
            self.content_frame, height=80, font=("Arial", 11), state="disabled"
        )
        self.term.pack(fill="x", padx=10, pady=5)

        self.result_frame = ctk.CTkFrame(self.content_frame, fg_color="#2a2a2a", corner_radius=8)
        self.result_frame.pack(fill="x", padx=10, pady=5)
        self.result_frame.pack_forget()

        self.result_label = ctk.CTkLabel(
            self.result_frame, text="", font=("Arial", 16, "bold"), text_color="#ffffff"
        )
        self.result_label.pack(side="left", padx=15, pady=10)

        self.copy_btn = ctk.CTkButton(
            self.result_frame,
            text="📋 复制",
            width=80,
            font=("Arial", 12),
            fg_color="#4a9eff",
            command=self._copy_result,
        )
        self.copy_btn.pack(side="right", padx=15, pady=10)

        self.msg_label = ctk.CTkLabel(
            self.content_frame,
            text="[Q] 退出 | 翻译结果不自动填入终端，请点击复制",
            font=("Arial", 10),
            text_color="#aaa",
        )
        self.msg_label.pack(pady=5)

        self.protocol("WM_DELETE_WINDOW", self._safe_destroy)

    # -------- 辅助方法 --------
    def _save_current_text(self, event=None):
        try:
            self._saved_ime_text = self._ime_input.get()
        except Exception:
            pass

    def _restore_text(self, event=None):
        if not self._alive or not self.winfo_exists():
            return
        try:
            if self._ime_input.winfo_exists():
                current_text = self._ime_input.get()
                if not current_text and self._saved_ime_text:
                    self._ime_input.delete(0, "end")
                    self._ime_input.insert(0, self._saved_ime_text)
                    self._ime_input.icursor(len(self._saved_ime_text))
        except Exception:
            pass

    def _force_focus(self, event=None):
        if not self._alive or not self.winfo_exists():
            return
        try:
            if self._ime_input.winfo_exists():
                self._ime_input.configure(state="normal")
                self._ime_input.focus_set()
                self._ime_input.selection_clear()
        except Exception:
            pass

    def _copy_result(self):
        if not self._last_result:
            return
        self.clipboard_clear()
        self.clipboard_append(self._last_result)
        self.copy_btn.configure(text="✅ 已复制", fg_color="#27ae60")
        self.after(1500, lambda: self.copy_btn.configure(text="📋 复制", fg_color="#4a9eff"))

    def _safe_destroy(self):
        self._alive = False
        try:
            self.unbind_all("<Key>")
            self.unbind_all("<Return>")
            if self.winfo_exists():
                self.destroy()
        except Exception:
            pass

    def _build_index(self):
        self.word_list = ["你好", "世界", "文件", "电脑", "系统", "终端", "宠物"]
        self.pinyin_dict = {}
        for word in self.word_list:
            try:
                p_str = "".join([p[0] for p in pinyin(word, style=Style.NORMAL)])
                if p_str not in self.pinyin_dict:
                    self.pinyin_dict[p_str] = []
                self.pinyin_dict[p_str].append(word)
            except Exception:
                pass

    # -------- 输入处理（主线程只负责触发，耗时部分线程化） --------
    def _on_enter(self, event):
        if self._processing:
            return  # 正在处理中，忽略重复回车

        text = self._ime_input.get().strip().lower()
        if text == "q":
            self._safe_destroy()
            return

        # 简单校验（不耗时，直接做）
        if re.match(r"^[0-9\s]+$", text):
            self.term.configure(state="normal")
            self.term.delete("1.0", "end")
            self.term.insert("end", "❌ 输入错误：请不要输入纯数字！请输入拼音字母（如 ni hao）。")
            self.term.configure(state="disabled")
            return
        if not re.match(r"^[a-zA-Z\s]+$", text):
            self.term.configure(state="normal")
            self.term.delete("1.0", "end")
            self.term.insert("end", "❌ 输入错误：包含非法字符，请只输入拼音。")
            self.term.configure(state="disabled")
            return

        # 隐藏上一轮结果
        self.result_frame.pack_forget()
        self.term.configure(state="normal")
        self.term.delete("1.0", "end")

        # 情况1：硬编码命中（瞬间完成，直接处理）
        if text in self.hardcode_map:
            self._last_result = self.hardcode_map[text]
            self.term.insert("end", "⚡ 热词直通！")
            self._show_result_and_copy()
            self.term.configure(state="disabled")
            return

        # 情况2：本地词库命中（也是瞬间）
        candidates = self.pinyin_dict.get(text, [])
        if candidates:
            self.term.insert("end", "✅ 本地词库命中：\n")
            for i, word in enumerate(candidates, 1):
                self.term.insert("end", f"  [{i}] {word}\n")
            self.term.insert("end", "\n（直接按键盘数字键 1 选择，结果会显示在下方复制区）")
            self._last_candidates = candidates
            self.bind_all("<Key>", self._select_candidate)
            self.term.configure(state="disabled")
            return

        # 情况3：需要 AI 翻译（耗时操作，放入线程）
        self.term.insert("end", "🤖 正在处理拼音...\n（AI推理较慢，请稍候，界面不会卡死）")
        self.term.configure(state="disabled")
        self._processing = True
        self._ime_input.configure(state="disabled")  # 防止重复提交

        # 启动后台线程
        def ai_task():
            if " " in text:
                reply, _ = self.shell._local_ai_reply(
                    f"请将拼音句子翻译成中文，只输出中文结果。拼音：'{text}'"
                )
            else:
                reply, _ = self.shell._local_ai_reply(
                    f"请将连续拼音字符串 '{text}' 翻译成中文，只输出纯中文结果。"
                )
            # 通过 after 回到主线程更新 UI
            self.after(0, lambda: self._on_ai_done(reply))

        threading.Thread(target=ai_task, daemon=True).start()

    def _on_ai_done(self, reply):
        if not self._alive or not self.winfo_exists():
            return
        self._processing = False
        self._ime_input.configure(state="normal")
        self._ime_input.focus_set()

        self.term.configure(state="normal")
        match = re.search(r"[\u4e00-\u9fff]+", reply)
        if match:
            self._last_result = match.group(0)
            self.term.insert("end", "\n✅ AI 翻译结果生成完毕！")
        else:
            self._last_result = reply.strip()
            self.term.insert("end", f"\n⚠️ 翻译结果：\n{reply}")
        self.term.configure(state="disabled")
        self._show_result_and_copy()

    def _show_result_and_copy(self):
        if not self._last_result:
            return
        self.result_label.configure(text=f"📝 结果：{self._last_result}")
        self.result_frame.pack(fill="x", padx=10, pady=5)
        self.copy_btn.configure(text="📋 复制", fg_color="#4a9eff")

    def _select_candidate(self, event):
        if not self._alive or not self.winfo_exists():
            return
        if not self._last_candidates:
            return
        try:
            idx = int(event.keysym)
            if idx == 1:
                self._last_result = self._last_candidates[0]
                self.term.configure(state="normal")
                self.term.insert("end", f"\n✅ 已选择：{self._last_result}")
                self.term.configure(state="disabled")
                self._show_result_and_copy()
                self._safe_destroy()
        except ValueError:
            pass


class SnapshotManager:
    def __init__(self, shell):
        self.shell = shell
        self.snapshots_dir = os.path.join(KIKI_DATA_DIR, "snapshots")
        os.makedirs(self.snapshots_dir, exist_ok=True)

    def create(self, description=""):
        import json
        import os
        import shutil
        import time

        ts = time.strftime("%Y%m%d_%H%M%S")
        snap_name = f"snapshot_{ts}"
        snap_path = os.path.join(self.snapshots_dir, snap_name)
        os.makedirs(snap_path, exist_ok=True)

        # 1. 复制数据库（核心数据，包含所有 VFS 文件及配置）
        shutil.copy2(DB_PATH, os.path.join(snap_path, "kiki_fs.db"))

        # 2. 尝试复制宿主机配置文件，如果不存在就跳过（不报错）
        config_path = os.path.join(KIKI_DATA_DIR, "kiki_config.json")
        if os.path.exists(config_path):
            shutil.copy2(config_path, os.path.join(snap_path, "kiki_config.json"))
        else:
            # 提示用户，但绝不影响快照成功
            print(
                "ℹ️ 提示: 宿主机独立配置文件未生成，快照将只包含数据库（配置已安全存储于数据库内）。"
            )

        # 3. 保存描述信息
        with open(os.path.join(snap_path, "meta.json"), "w") as f:
            json.dump({"timestamp": ts, "description": description}, f)

        print(f"✅ 快照已创建: {snap_name}")
        return snap_name

    def list(self):
        snapshots = []
        for entry in os.listdir(self.snapshots_dir):
            if os.path.isdir(os.path.join(self.snapshots_dir, entry)) and entry.startswith(
                "snapshot_"
            ):
                meta_path = os.path.join(self.snapshots_dir, entry, "meta.json")
                if os.path.exists(meta_path):
                    with open(meta_path) as f:
                        meta = json.load(f)
                    snapshots.append((entry, meta["timestamp"], meta["description"]))
        # 按时间倒序
        snapshots.sort(key=lambda x: x[1], reverse=True)
        return snapshots

    def restore(self, snap_name):
        snap_path = os.path.join(self.snapshots_dir, snap_name)
        if not os.path.exists(snap_path):
            print("❌ 快照不存在")
            return False

        import shutil

        # 1. 恢复数据库（核心数据）
        shutil.copy2(os.path.join(snap_path, "kiki_fs.db"), DB_PATH)

        # 2. 尝试恢复配置文件，如果不存在则忽略（不会因此崩溃）
        config_src = os.path.join(snap_path, "kiki_config.json")
        config_dst = os.path.join(KIKI_DATA_DIR, "kiki_config.json")
        if os.path.exists(config_src):
            shutil.copy2(config_src, config_dst)
            print("✅ 配置文件已恢复")
        else:
            print("ℹ️ 快照中无配置文件，将保留当前配置或使用默认配置")

        # 3. 清空缓存并重新加载配置
        self.shell.fs._node_cache.clear()
        self.shell.fs._perm_cache.clear()
        self.shell.config.config = self.shell.config._load()

        print(f"🔄 快照 {snap_name} 已恢复！")
        return True


import os


class ChatManager:
    def __init__(self, db_path="chat.db", shell=None):
        self.db_path = db_path
        self.shell = shell  # 保存 KIKIShell 引用，用于 VFS 操作
        self._init_db()

    def _init_db(self):
        conn = sqlite3.connect(self.db_path)
        conn.execute("PRAGMA journal_mode=WAL;")
        conn.execute("""
            CREATE TABLE IF NOT EXISTS rooms (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                type TEXT,
                name TEXT,
                owner TEXT,
                created_at TIMESTAMP
            );
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS members (
                room_id INTEGER,
                user TEXT,
                role TEXT,
                joined_at TIMESTAMP,
                PRIMARY KEY (room_id, user)
            );
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS messages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                room_id INTEGER,
                sender TEXT,
                content_hash TEXT,
                file_hash TEXT,
                reply_to INTEGER,
                sent_at TIMESTAMP,
                deleted INTEGER DEFAULT 0
            );
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS contents (
                hash TEXT PRIMARY KEY,
                type TEXT,
                text TEXT,
                file_path TEXT,
                size INTEGER,
                mime TEXT,
                data BLOB
            );
        """)
        # 自动升级：添加 data 列（若不存在）
        cur = conn.cursor()
        cur.execute("PRAGMA table_info(contents)")
        cols = [col[1] for col in cur.fetchall()]
        if "data" not in cols:
            cur.execute("ALTER TABLE contents ADD COLUMN data BLOB;")
        # 自动升级：添加 deleted 列（若不存在）
        cur.execute("PRAGMA table_info(messages)")
        cols = [col[1] for col in cur.fetchall()]
        if "deleted" not in cols:
            cur.execute("ALTER TABLE messages ADD COLUMN deleted INTEGER DEFAULT 0;")
        conn.commit()
        conn.close()

    def create_room(self, type_, name, owner):
        conn = sqlite3.connect(self.db_path)
        cur = conn.cursor()
        cur.execute(
            "INSERT INTO rooms (type, name, owner, created_at) VALUES (?,?,?,?)",
            (type_, name, owner, datetime.now().isoformat()),
        )
        room_id = cur.lastrowid
        cur.execute(
            "INSERT INTO members (room_id, user, role, joined_at) VALUES (?,?,?,?)",
            (room_id, owner, "owner", datetime.now().isoformat()),
        )
        conn.commit()
        conn.close()
        return room_id

    def add_member(self, room_id, user, role="member"):
        conn = sqlite3.connect(self.db_path)
        cur = conn.cursor()
        cur.execute(
            "INSERT OR IGNORE INTO members (room_id, user, role, joined_at) VALUES (?,?,?,?)",
            (room_id, user, role, datetime.now().isoformat()),
        )
        conn.commit()
        conn.close()

    def rename_room(self, room_id, new_name, user):
        conn = sqlite3.connect(self.db_path)
        cur = conn.cursor()
        cur.execute("SELECT role FROM members WHERE room_id = ? AND user = ?", (room_id, user))
        mem = cur.fetchone()
        if not mem or mem[0] not in ("admin", "owner"):
            conn.close()
            return False
        cur.execute("UPDATE rooms SET name = ? WHERE id = ?", (new_name, room_id))
        conn.commit()
        conn.close()
        return True

    def leave_room(self, room_id, user):
        conn = sqlite3.connect(self.db_path)
        cur = conn.cursor()
        cur.execute("SELECT role FROM members WHERE room_id = ? AND user = ?", (room_id, user))
        mem = cur.fetchone()
        if not mem:
            conn.close()
            return False
        if mem[0] == "owner":
            conn.close()
            print("❌ 所有者不能直接退出，请先转让所有权")
            return False
        cur.execute("DELETE FROM members WHERE room_id = ? AND user = ?", (room_id, user))
        conn.commit()
        conn.close()
        return True

    def send_message(self, room_id, sender, text=None, file_path=None, reply_to=None):
        file_data = None
        if text:
            hash_ = hashlib.sha256(text.encode()).hexdigest()
            type_ = "text"
        elif file_path:
            # ---------- 处理文件 ----------
            if file_path.startswith("/"):
                # VFS 路径
                content = self.shell.fs.read_file(file_path, self.shell.username)
                if content is None:
                    return False
                vfs_path = file_path
                if isinstance(content, str):
                    content = content.encode("utf-8")
                hash_ = hashlib.sha256(content).hexdigest()
                file_data = content  # 读取到的原始字节数据
            else:
                # 宿主机路径：读取并存入 VFS
                try:
                    with open(file_path, "rb") as f:
                        data = f.read()
                except FileNotFoundError:
                    return False
                hash_ = hashlib.sha256(data).hexdigest()
                import os

                base = os.path.basename(file_path)
                vfs_dir = f"/home/{self.shell.username}/Downloads"
                if not self.shell.fs.resolve(vfs_dir, self.shell.username):
                    self.shell.fs.mkdir(vfs_dir, self.shell.username)
                vfs_path = f"{vfs_dir}/{base}"
                if self.shell.fs.resolve(vfs_path, self.shell.username):
                    name, ext = os.path.splitext(base)
                    vfs_path = f"{vfs_dir}/{name}_{int(time.time())}{ext}"
                self.shell.fs.create_file(vfs_path, data, self.shell.username)
                file_data = data
            type_ = "file"
        else:
            return False

        conn = sqlite3.connect(self.db_path)
        cur = conn.cursor()
        # ----- 核心补丁：检查内容是否已存在，如果 data 为空则强制覆盖 -----
        cur.execute("SELECT hash, data FROM contents WHERE hash=?", (hash_,))
        existing = cur.fetchone()

        if existing:
            # 如果记录已存在，但 data 是空的，且当前有文件数据，强制更新它！
            if existing[1] is None and file_data is not None:
                cur.execute("UPDATE contents SET data = ? WHERE hash = ?", (file_data, hash_))
        else:
            # 如果不存在，则正常插入
            if type_ == "text":
                cur.execute(
                    "INSERT INTO contents (hash, type, text) VALUES (?,?,?)",
                    (hash_, type_, text),
                )
            else:
                if file_path.startswith("/"):
                    node = self.shell.fs.resolve(vfs_path, self.shell.username)
                    size = node.get_size() if node else 0
                else:
                    size = len(file_data)
                mime = "application/octet-stream"
                cur.execute(
                    "INSERT INTO contents (hash, type, file_path, size, mime, data) VALUES (?,?,?,?,?,?)",
                    (hash_, type_, vfs_path, size, mime, file_data),
                )
        # ----------------------------------------------------------------
        # 插入消息
        cur.execute(
            """
            INSERT INTO messages (room_id, sender, content_hash, file_hash, reply_to, sent_at)
            VALUES (?,?,?,?,?,?)
        """,
            (
                room_id,
                sender,
                hash_,
                hash_ if type_ == "file" else None,
                reply_to,
                datetime.now().isoformat(),
            ),
        )
        msg_id = cur.lastrowid
        conn.commit()
        conn.close()
        return msg_id

    def delete_message(self, msg_id, user):
        conn = sqlite3.connect(self.db_path)
        cur = conn.cursor()
        cur.execute(
            "SELECT room_id, sender FROM messages WHERE id = ? AND deleted = 0",
            (msg_id,),
        )
        row = cur.fetchone()
        if not row:
            conn.close()
            return False
        room_id, sender = row

        cur.execute("SELECT role FROM members WHERE room_id = ? AND user = ?", (room_id, user))
        mem = cur.fetchone()
        if not mem:
            conn.close()
            return False
        role = mem[0]
        if user != sender and role not in ("admin", "owner"):
            conn.close()
            return False

        cur.execute("UPDATE messages SET deleted = 1 WHERE id = ?", (msg_id,))
        conn.commit()
        conn.close()
        return True

    def get_messages(self, room_id, limit=50):
        conn = sqlite3.connect(self.db_path)
        cur = conn.cursor()
        cur.execute(
            """
            SELECT m.id, m.sender, m.sent_at, c.type, c.text, c.file_path, m.reply_to
            FROM messages m
            LEFT JOIN contents c ON m.content_hash = c.hash
            WHERE m.room_id = ? AND m.deleted = 0
            ORDER BY m.sent_at DESC
            LIMIT ?
        """,
            (room_id, limit),
        )
        rows = cur.fetchall()
        conn.close()
        return rows

    def list_rooms(self, user):
        conn = sqlite3.connect(self.db_path)
        cur = conn.cursor()
        cur.execute(
            """
            SELECT r.id, r.type, r.name, r.owner
            FROM rooms r
            JOIN members m ON r.id = m.room_id
            WHERE m.user = ?
        """,
            (user,),
        )
        rows = cur.fetchall()
        conn.close()
        return rows


# ================= 画图程序 =================
class PaintApp(KikiWindow):
    def __init__(self, master, shell, username):
        super().__init__(master, title="画图", width=800, height=600)
        self.shell = shell
        self.username = username
        self.color = "black"
        self.brush_size = 5
        self.eraser_mode = False
        self.drawing = False
        self.last_x = None
        self.last_y = None
        self.file_path = None
        self._create_widgets()
        self._bind_canvas_events()

    def _bind_events(self):
        # 父类的 _bind_events 被重写为空，因为 canvas 尚未创建
        pass

    def _bind_canvas_events(self):
        self.canvas.bind("<Button-1>", self.start_draw)
        self.canvas.bind("<B1-Motion>", self.draw_line)
        self.canvas.bind("<ButtonRelease-1>", self.stop_draw)
        self.canvas.bind("<Configure>", self.resize_image)

    def _create_widgets(self):
        self.main_frame = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        self.main_frame.pack(fill="both", expand=True)
        self._create_toolbar()
        self._create_canvas()

    def _create_toolbar(self):
        toolbar = ctk.CTkFrame(self.main_frame, width=120, fg_color="#3a3a3a")
        toolbar.pack(side="left", fill="y", padx=5, pady=5)

        ctk.CTkLabel(toolbar, text="颜色", font=("Arial", 12)).pack(pady=(10, 5))
        color_frame = ctk.CTkFrame(toolbar, fg_color="transparent")
        color_frame.pack(pady=5)
        colors = [
            "black",
            "red",
            "green",
            "blue",
            "yellow",
            "white",
            "orange",
            "purple",
            "pink",
            "brown",
        ]
        for c in colors:
            btn = ctk.CTkButton(
                color_frame,
                text="",
                width=24,
                height=24,
                fg_color=c,
                command=lambda col=c: self.set_color(col),
            )
            btn.pack(side="left", padx=2, pady=2)

        ctk.CTkLabel(toolbar, text="大小", font=("Arial", 12)).pack(pady=(10, 5))
        self.size_slider = ctk.CTkSlider(toolbar, from_=1, to=30, command=self.set_brush_size)
        self.size_slider.set(5)
        self.size_slider.pack(pady=5, padx=10)

        self.eraser_btn = ctk.CTkButton(toolbar, text="🧹 橡皮擦", command=self.toggle_eraser)
        self.eraser_btn.pack(pady=5)
        ctk.CTkButton(toolbar, text="🗑️ 清空", command=self.clear_canvas).pack(pady=5)
        ctk.CTkButton(toolbar, text="💾 保存", command=self.save_image).pack(pady=5)
        ctk.CTkButton(toolbar, text="📂 打开", command=self.open_image).pack(pady=5)

        self.status_label = ctk.CTkLabel(toolbar, text="画笔", font=("Arial", 10))
        self.status_label.pack(pady=10)

    def _create_canvas(self):
        self.canvas_frame = ctk.CTkFrame(self.main_frame, fg_color="white")
        self.canvas_frame.pack(side="right", fill="both", expand=True, padx=5, pady=5)
        self.canvas = tk.Canvas(self.canvas_frame, bg="white", highlightthickness=0)
        self.canvas.pack(fill="both", expand=True)
        from PIL import Image, ImageDraw

        self.image = Image.new("RGB", (800, 600), "white")
        self.draw = ImageDraw.Draw(self.image)

    # 以下方法保持不变（set_color, set_brush_size, toggle_eraser, start_draw, draw_line, stop_draw, resize_image, clear_canvas, save_image, open_image, _show_notification）
    def set_color(self, color):
        self.color = color
        self.eraser_mode = False
        self.eraser_btn.configure(text="🧹 橡皮擦")
        self.status_label.configure(text=f"颜色: {color}")

    def set_brush_size(self, value):
        self.brush_size = int(value)

    def toggle_eraser(self):
        self.eraser_mode = not self.eraser_mode
        if self.eraser_mode:
            self.eraser_btn.configure(text="✏️ 画笔")
            self.status_label.configure(text="橡皮擦")
        else:
            self.eraser_btn.configure(text="🧹 橡皮擦")
            self.status_label.configure(text="画笔")

    def start_draw(self, event):
        self.drawing = True
        self.last_x = event.x
        self.last_y = event.y

    def draw_line(self, event):
        if not self.drawing:
            return
        x, y = event.x, event.y
        color = "white" if self.eraser_mode else self.color
        self.canvas.create_line(
            self.last_x,
            self.last_y,
            x,
            y,
            fill=color,
            width=self.brush_size,
            capstyle=tk.ROUND,
            smooth=True,
        )
        self.draw.line([self.last_x, self.last_y, x, y], fill=color, width=self.brush_size)
        self.last_x, self.last_y = x, y

    def stop_draw(self, event):
        self.drawing = False

    def resize_image(self, event):
        pass

    def clear_canvas(self):
        self.canvas.delete("all")
        self.image = Image.new(
            "RGB", (self.canvas.winfo_width(), self.canvas.winfo_height()), "white"
        )
        self.draw = ImageDraw.Draw(self.image)

    def save_image(self):
        from PIL import ImageGrab

        x0 = self.canvas.winfo_rootx()
        y0 = self.canvas.winfo_rooty()
        x1 = x0 + self.canvas.winfo_width()
        y1 = y0 + self.canvas.winfo_height()
        if x1 <= x0 or y1 <= y0:
            messagebox.showerror("错误", "画布尺寸无效")
            return
        img = ImageGrab.grab(bbox=(x0, y0, x1, y1))
        pics_path = f"/home/{self.username}/Pictures"
        if not self.shell.fs.resolve(pics_path, self.username):
            self.shell.fs.mkdir(pics_path, self.username)
        from datetime import datetime

        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        fname = f"paint_{ts}.png"
        vfs_path = f"{pics_path}/{fname}"
        import base64
        import io

        buf = io.BytesIO()
        img.save(buf, format="PNG")
        b64 = base64.b64encode(buf.getvalue()).decode("ascii")
        if self.shell.fs.create_file(vfs_path, "", self.username):
            self.shell.fs.write_file(vfs_path, b64, self.username)
            self._show_notification(f"图片已保存: {vfs_path}")
        else:
            messagebox.showerror("错误", "保存失败")

    def open_image(self):
        from tkinter import filedialog

        f = filedialog.askopenfilename(
            title="选择图片", filetypes=[("PNG图片", "*.png"), ("所有文件", "*.*")]
        )
        if f:
            content = self.shell.fs.read_file(f, self.username)
            if content:
                import base64
                import io

                from PIL import Image, ImageTk

                try:
                    img_data = base64.b64decode(content)
                    img = Image.open(io.BytesIO(img_data))
                    self.canvas.delete("all")
                    tk_img = ImageTk.PhotoImage(img)
                    self.canvas.create_image(0, 0, anchor="nw", image=tk_img)
                    self.canvas.image = tk_img
                    self.image = img
                    self.draw = ImageDraw.Draw(self.image)
                    self.file_path = f
                except Exception as e:
                    messagebox.showerror("错误", f"无法打开图片: {e}")

    def _show_notification(self, msg):
        if self.master and hasattr(self.master, "_show_notification"):
            self.gui._show_notification(msg)


# ================= 便签 =================
class StickyNote(ctk.CTkToplevel):
    def __init__(self, master, shell, username, content="", color="#FFFF88", note_id=None):
        super().__init__(master)
        self.gui = master
        self.title("便签")
        self.overrideredirect(True)
        self.shell = shell
        self.username = username
        self.color = color
        self.note_id = note_id
        self._dragging = False
        self._drag_x = 0
        self._drag_y = 0
        self._resizing = False
        self._maximized = False
        self._normal_geometry = None

        self.geometry("250x200")
        self.configure(fg_color=color)
        self.resizable(True, True)

        # 标题栏
        self.title_bar = ctk.CTkFrame(self, height=25, fg_color=color, corner_radius=0)
        self.title_bar.pack(side="top", fill="x")
        self.title_bar.pack_propagate(False)

        self.title_label = ctk.CTkLabel(
            self.title_bar, text="📌 便签", font=("Arial", 10), text_color="black"
        )
        self.title_label.pack(side="left", padx=5)

        self.close_btn = ctk.CTkButton(
            self.title_bar,
            text="✕",
            width=20,
            height=20,
            fg_color="transparent",
            text_color="black",
            hover_color="#cc0000",
            command=self.destroy,
        )
        self.close_btn.pack(side="right", padx=2)

        self.color_btn = ctk.CTkButton(
            self.title_bar,
            text="🎨",
            width=20,
            height=20,
            fg_color="transparent",
            text_color="black",
            command=self.choose_color,
        )
        self.color_btn.pack(side="right", padx=2)

        # 最小化按钮
        self.min_btn = ctk.CTkButton(
            self.title_bar,
            text="─",
            width=20,
            height=20,
            fg_color="transparent",
            text_color="white",
            hover_color="#555555",
            command=self._minimize_widget,
        )
        self.min_btn.pack(side="right", padx=2)

        # 最大化按钮
        self.max_btn = ctk.CTkButton(
            self.title_bar,
            text="☐",
            width=20,
            height=20,
            fg_color="transparent",
            text_color="white",
            hover_color="#555555",
            command=self._maximize_widget,
        )
        self.max_btn.pack(side="right", padx=2)

        self.text_box = ctk.CTkTextbox(
            self,
            font=("Arial", 11),
            wrap="word",
            fg_color=color,
            text_color="black",
            border_width=0,
        )
        self.text_box.pack(fill="both", expand=True, padx=5, pady=5)
        self.text_box.insert("1.0", content)

        self.resize_handle = ctk.CTkLabel(
            self,
            text="⤵",
            font=("Arial", 14),
            fg_color=color,
            text_color="black",
            cursor="sizing",
        )
        self.resize_handle.place(relx=1.0, rely=1.0, anchor="se", x=-5, y=-5)

        self.title_bar.bind("<Button-1>", self.start_move)
        self.title_bar.bind("<B1-Motion>", self.on_move)
        self.title_bar.bind("<Double-Button-1>", self.toggle_maximize)

        self.resize_handle.bind("<Button-1>", self.start_resize)
        self.resize_handle.bind("<B1-Motion>", self.on_resize)

        self._auto_save_after = None
        self.text_box.bind("<KeyRelease>", self.schedule_save)
        self.bind("<Destroy>", self.on_destroy)
        self.schedule_save()

    def _minimize_widget(self):
        self.iconify()

    def _maximize_widget(self):
        if self._maximized:
            self.geometry(self._normal_geometry)
            self._maximized = False
            self.max_btn.configure(text="☐")
        else:
            self._normal_geometry = self.geometry()
            sw = self.winfo_screenwidth()
            sh = self.winfo_screenheight()
            self.geometry(f"{sw}x{sh}+0+0")
            self._maximized = True
            self.max_btn.configure(text="⛶")

    def start_move(self, event):
        self._dragging = True
        self._drag_x = event.x_root - self.winfo_x()
        self._drag_y = event.y_root - self.winfo_y()

    def on_move(self, event):
        if self._dragging:
            x = event.x_root - self._drag_x
            y = event.y_root - self._drag_y
            self.geometry(f"+{x}+{y}")

    def start_resize(self, event):
        self._resizing = True
        self._resize_start_x = self.winfo_width()
        self._resize_start_y = self.winfo_height()

    def on_resize(self, event):
        if self._resizing:
            new_w = max(150, self._resize_start_x + (event.x_root - self.winfo_rootx()))
            new_h = max(100, self._resize_start_y + (event.y_root - self.winfo_rooty()))
            self.geometry(f"{new_w}x{new_h}")

    def choose_color(self):
        from tkinter import colorchooser

        color = colorchooser.askcolor(title="选择便签颜色", color=self.color)
        if color and color[1]:
            self.color = color[1]
            self.configure(fg_color=color[1])
            self.title_bar.configure(fg_color=color[1])
            self.text_box.configure(fg_color=color[1])
            self.resize_handle.configure(fg_color=color[1])

    def schedule_save(self, event=None):
        if self._auto_save_after:
            self.after_cancel(self._auto_save_after)
        self._auto_save_after = self.after(1000, self.save_note)

    def save_note(self):
        if not self.winfo_exists():
            return
        try:
            if not self.text_box.winfo_exists():
                return
        except tk.TclError:
            return
        content = self.text_box.get("1.0", "end-1c")
        notes_path = f"/home/{self.username}/Notes"
        if not self.shell.fs.resolve(notes_path, self.username):
            self.shell.fs.mkdir(notes_path, self.username)
        if self.note_id is None:
            from datetime import datetime

            self.note_id = f"note_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
        vfs_path = f"{notes_path}/{self.note_id}"
        meta = f"#COLOR:{self.color}\n"
        self.shell.fs.write_file(vfs_path, meta + content, self.username)

    def on_destroy(self, event):
        if self._auto_save_after:
            self.after_cancel(self._auto_save_after)
        try:
            self.save_note()
        except Exception:
            pass

    def toggle_maximize(self, event=None):
        if self._maximized:
            if self._normal_geometry:
                self.geometry(self._normal_geometry)
            self._maximized = False
        else:
            self._normal_geometry = self.geometry()
            sw = self.winfo_screenwidth()
            sh = self.winfo_screenheight()
            self.geometry(f"{sw}x{sh}+0+0")
            self._maximized = True


class AIChatWindow(KikiWindow):
    def __init__(self, master, shell):
        super().__init__(master, title="AI 助手（文本输入）", width=650, height=580)
        self.gui = master
        self.shell = shell
        self.ai_engine = shell.ai_engine
        self.ai_engine._popup_parent = self
        self.ai_engine.reply_callback = self._show_ai_reply
        self.ai_engine.thinking_callback = self._show_thinking

        # ============ 状态 + 模型选择 ============
        status_frame = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        status_frame.pack(fill="x", padx=10, pady=5)

        self.status_label = ctk.CTkLabel(status_frame, text="", font=("Arial", 10))
        self.status_label.pack(side="left", padx=(0, 10))

        # ★ 模型下拉框（仅当有多个模型时显示）
        self.model_combo = None
        self.model_var = None
        self._build_model_selector(status_frame)

        self.refresh_model_btn = ctk.CTkButton(
            status_frame, text="刷新", width=50, command=self.refresh_model
        )
        self.refresh_model_btn.pack(side="right", padx=(5, 0))

        self.speak_btn = ctk.CTkCheckBox(status_frame, text="语音朗读", command=self.toggle_speak)
        self.speak_btn.pack(side="right", padx=10)

        # ============ 思考区 ============
        self.think_frame = ctk.CTkFrame(self.content_frame, fg_color="#1a1a2e")
        self.think_frame.pack(fill="x", padx=10, pady=5)
        self.think_display = ctk.CTkTextbox(
            self.think_frame, height=80, font=("Courier New", 10), state="disabled"
        )
        self.think_display.pack(fill="both", expand=True)
        self.think_toggle_btn = ctk.CTkButton(
            self.think_frame, text="🧠 思考过程 ▲", command=self.toggle_thinking
        )
        self.think_toggle_btn.pack(side="bottom")
        self.think_visible = True

        # ============ 聊天显示 ============
        self.chat_display = ctk.CTkTextbox(
            self.content_frame, font=("Courier New", 11), wrap="word", state="disabled"
        )
        self.chat_display.pack(fill="both", expand=True, padx=10, pady=5)

        # ============ 输入区 ============
        input_frame = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        input_frame.pack(fill="x", padx=10, pady=5)
        self.input_entry = ctk.CTkEntry(input_frame, placeholder_text="输入问题...")
        self.input_entry.pack(side="left", fill="x", expand=True, padx=5)
        self.input_entry.bind("<Return>", self.send_message)
        self.send_btn = ctk.CTkButton(input_frame, text="发送", command=self.send_message, width=80)
        self.send_btn.pack(side="right")

        self.speak_enabled = False

        # 欢迎信息先显示
        self.chat_display.insert("end", "欢迎使用 AI 助手！\n")
        self.chat_display.configure(state="disabled")

        # ★ 所有网络 / 弹窗操作都延迟到窗口渲染完之后
        self.after(100, self._initial_model_setup)

    def _initial_model_setup(self):
        """窗口渲染完后再做的初始化。★ 只做异步检测，绝不弹窗。"""
        # 只调异步刷新，不碰 _try_enable_model_sync
        self.refresh_model()

    # ---------- 模型下拉框构建 ----------
    def _build_model_selector(self, parent):
        """构建模型下拉框。选项包含：离线 / 在线AI / 本地 Ollama 模型。"""
        options, default = self._collect_model_options()

        # 移除旧的下拉框和提示（如果已存在）
        try:
            if getattr(self, "model_combo", None) is not None:
                if self.model_combo.winfo_exists():
                    self.model_combo.destroy()
        except Exception:
            pass
        try:
            if hasattr(self, "_no_model_label") and self._no_model_label.winfo_exists():
                self._no_model_label.destroy()
        except Exception:
            pass

        ctk.CTkLabel(parent, text="模型:", font=("Arial", 10)).pack(side="left", padx=(5, 2))

        self.model_var = ctk.StringVar(value=default)
        self.model_combo = ctk.CTkComboBox(
            parent,
            values=options,
            variable=self.model_var,
            command=self._on_model_change,
            width=240,
            font=("Arial", 10),
        )
        self.model_combo.pack(side="left", padx=2)

    def _collect_model_options(self):
        """收集所有可选项，返回 (选项列表, 默认选中项)。"""
        options = ["📴 离线模式"]

        # 在线 AI（仅当配置齐全时出现）
        try:
            base_url = (self.shell.config.get("ai.base_url", "") or "").strip()
            api_key = (self.shell.config.get("ai.api_key", "") or "").strip()
            provider = self.shell.config.get("ai.provider", "mock")
            if provider not in ("mock", "ollama", "") and base_url and api_key:
                online_model = (self.shell.config.get("ai.model", "") or "").strip()
                label = f"🌐 在线 AI ({provider}"
                if online_model:
                    label += f" / {online_model}"
                label += ")"
                options.append(label)
        except Exception:
            pass

        # 本地 Ollama 模型
        try:
            text_models = self.ai_engine.get_text_models() or []
        except Exception:
            text_models = []
        for m in text_models:
            options.append(f"🖥️ {m}")

        # 决定默认选中
        default = "📴 离线模式"
        current_provider = self.ai_engine.provider
        current_model = self.ai_engine.model

        if current_provider == "ollama" and current_model:
            cand = f"🖥️ {current_model}"
            if cand in options:
                default = cand
        elif current_provider and current_provider != "ollama":
            for opt in options:
                if opt.startswith("🌐 在线 AI"):
                    default = opt
                    break

        return options, default

    def _sync_model_selector(self):
        """刷新下拉框内容（检测到新模型或引擎切换后调用）。"""
        # 清掉旧的"无模型"提示（新逻辑里我们不再隐藏下拉框）
        try:
            if hasattr(self, "_no_model_label") and self._no_model_label.winfo_exists():
                self._no_model_label.destroy()
        except Exception:
            pass

        # 下拉框不存在 → 重建
        if getattr(self, "model_combo", None) is None or not self.model_combo.winfo_exists():
            parent = self.status_label.master
            self._build_model_selector(parent)
            return

        options, default = self._collect_model_options()

        try:
            self.model_combo.configure(values=options)
            # 当前选中项不在新列表 → 重置为默认
            current = self.model_var.get() if self.model_var else ""
            if current not in options:
                self.model_var.set(default)
        except Exception:
            pass

    def _on_model_change(self, choice):
        """用户从下拉框选择。choice 是带 emoji 前缀的显示文本。"""
        if not choice:
            return

        # ---------- 1. 离线模式 ----------
        if choice == "📴 离线模式":
            self.ai_engine.provider = None
            self.ai_engine.model = None
            self.ai_engine._model_user_choice = False
            self.ai_engine.messages = []
            try:
                self.ai_engine.clear_history()
            except Exception:
                pass
            try:
                self.shell.config.set("ai.online_enabled", False, self.shell.username)
                self.shell.config.save_user_config(self.shell.username)
            except Exception:
                pass
            self.chat_display.configure(state="normal")
            self.chat_display.insert("end", "📴 已切换到离线模式（规则匹配）\n\n")
            self.chat_display.configure(state="disabled")
            self.status_label.configure(text="状态: 离线模式")
            return

        # ---------- 2. 在线 AI ----------
        if choice.startswith("🌐 在线 AI"):
            provider = self.shell.config.get("ai.provider", "openai")
            model = self.shell.config.get("ai.model", "gpt-3.5-turbo")
            self.ai_engine.provider = provider
            self.ai_engine.model = model
            self.ai_engine._model_user_choice = True
            self.ai_engine.messages = []
            try:
                self.ai_engine.clear_history()
            except Exception:
                pass
            try:
                self.shell.config.set("ai.online_enabled", True, self.shell.username)
                self.shell.config.save_user_config(self.shell.username)
            except Exception:
                pass
            self.chat_display.configure(state="normal")
            self.chat_display.insert("end", f"🌐 已切换到在线 AI: {provider} / {model}\n\n")
            self.chat_display.configure(state="disabled")
            self.status_label.configure(text=f"状态: 在线（{provider}）| 模型: {model}")
            return

        # ---------- 3. 本地 Ollama 模型 ----------
        if choice.startswith("🖥️ "):
            model_name = choice[2:].strip()
            if not model_name:
                return
            self.ai_engine.model = model_name
            self.ai_engine.provider = "ollama"
            self.ai_engine._model_user_choice = True
            self.ai_engine.messages = []
            try:
                self.ai_engine.clear_history()
            except Exception:
                pass
            try:
                self.shell.config.set("ai.model", model_name, self.shell.username)
                self.shell.config.set("ai.online_enabled", True, self.shell.username)
                self.shell.config.save_user_config(self.shell.username)
            except Exception:
                pass
            self.chat_display.configure(state="normal")
            self.chat_display.insert("end", f"🔄 已切换到模型: {model_name}\n\n")
            self.chat_display.configure(state="disabled")
            self.status_label.configure(text=f"状态: 在线（Ollama）| 模型: {model_name}")
            return

    # ---------- 原有方法保持 ----------
    def refresh_model(self):
        """刷新模型列表（异步，不阻塞界面）"""
        try:
            self.status_label.configure(text="状态: 正在检测...")
        except Exception:
            pass

        def worker():
            try:
                self.ai_engine.detect_local_ollama()
                if hasattr(self.shell, "model_registry"):
                    try:
                        self.shell.model_registry._fetch_models(force=True)
                    except Exception:
                        pass
                self.after(0, self._finalize_refresh)
            except Exception as e:
                msg = str(e)
                self.after(0, lambda m=msg: self._on_refresh_error(m))

        import threading
        threading.Thread(target=worker, daemon=True).start()

    def _on_refresh_error(self, msg):
        try:
            self.status_label.configure(text=f"状态: 检测失败 ({msg})")
        except Exception:
            pass

    def _finalize_refresh(self):
        """在主线程里完成：启用引擎 + 更新 UI"""
        # 1. 只有当用户从没选过时，才自动启用
        if self.ai_engine.provider is None and self.ai_engine._model_user_choice is None:
            try:
                text_models = self.ai_engine.get_text_models()
            except Exception:
                text_models = []
            if text_models:
                chosen = text_models[0]
                self.ai_engine.provider = "ollama"
                self.ai_engine.model = chosen
                self.ai_engine._model_user_choice = True
                try:
                    self.shell.config.set("ai.model", chosen, self.shell.username)
                    self.shell.config.set("ai.online_enabled", True, self.shell.username)
                    self.shell.config.save_user_config(self.shell.username)
                except Exception:
                    pass

        # 2. 更新状态栏
        try:
            status, model = self.ai_engine.get_status()
            self.status_label.configure(text=f"状态: {status} | 模型: {model or '无'}")
        except Exception:
            pass

        # 3. 刷新下拉框
        try:
            self._sync_model_selector()
        except Exception:
            pass

    def _apply_refresh_result(self, status, model):
        """在主线程里更新状态栏 + 下拉框"""
        try:
            self.status_label.configure(text=f"状态: {status} | 模型: {model or '无'}")
        except Exception:
            pass
        self._sync_model_selector()

    def toggle_thinking(self):
        self.think_visible = not self.think_visible
        if self.think_visible:
            self.think_display.pack(fill="both", expand=True)
            self.think_toggle_btn.configure(text="🧠 思考过程 ▲")
        else:
            self.think_display.pack_forget()
            self.think_toggle_btn.configure(text="🧠 思考过程 ▼")

    def toggle_speak(self):
        self.speak_enabled = not self.speak_enabled

    def send_message(self, event=None):
        text = self.input_entry.get().strip()
        if not text:
            return
        self.input_entry.delete(0, "end")
        self.chat_display.configure(state="normal")
        self.chat_display.insert("end", f"👤 您: {text}\n")
        self.chat_display.configure(state="disabled")

        if self.ai_engine.provider is None and self.ai_engine._model_user_choice is None:
            self.ai_engine._try_enable_model_sync()

        self.ai_engine.chat(text, target="chat", reply_callback=self._show_ai_reply)

    def _show_thinking(self, thinking):
        self.think_display.configure(state="normal")
        self.think_display.insert("end", thinking + "\n")
        self.think_display.configure(state="disabled")

    def _show_ai_reply(self, reply, emoji="🤖"):
        self.chat_display.configure(state="normal")
        self.chat_display.insert("end", f"{emoji} AI: {reply}\n\n")
        self.chat_display.configure(state="disabled")
        if self.speak_enabled:
            self.ai_engine.speak(reply)

    def destroy(self):
        if self.ai_engine:
            self.ai_engine.reply_callback = None
            self.ai_engine.thinking_callback = None
        super().destroy()


import os

# ==================== 单元测试 ====================
import unittest
import uuid


class TestVirtualFS(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        # 保存原DB路径并设置临时数据库
        global DB_PATH
        cls._orig_db_path = DB_PATH
        cls._temp_db = tempfile.mktemp(suffix=".db")
        DB_PATH = cls._temp_db
        init_db()
        cls.fs = VirtualFS()
        cls.user = "root"  # 使用 root 用户，避免权限问题
        # 确保 /root 存在（默认已存在）
        # 清空 root 用户的回收站
        cls.fs.empty_trash(cls.user)
        # 确保 /root/.trash 存在（empty_trash 会创建）
        cls.uid = uuid.uuid4().hex[:8]
        # 当前工作目录设为根
        cls.fs.cwd = cls.fs.root
        builtins.play_sound = lambda *args, **kwargs: None

    @classmethod
    def tearDownClass(cls):
        global DB_PATH
        # 删除临时数据库
        if os.path.exists(cls._temp_db):
            os.unlink(cls._temp_db)
        DB_PATH = cls._orig_db_path

    def _unique_path(self, name):
        """生成根目录下的唯一路径"""
        return f"/{name}_{self.uid}"

    def _clear_caches(self):
        """强制清除 VFS 缓存"""
        self.fs._node_cache.clear()
        self.fs._perm_cache.clear()

    def test_mkdir_and_resolve(self):
        path = self._unique_path("test_dir")
        self.assertTrue(self.fs.mkdir(path, self.user))
        node = self.fs.resolve(path, self.user)
        self.assertIsNotNone(node)
        self.assertIsInstance(node, Directory)

    def test_create_file_and_read(self):
        path = self._unique_path("hello.txt")
        self.assertTrue(self.fs.create_file(path, "Hello World", self.user))
        content = self.fs.read_file(path, self.user)
        self.assertEqual(content, "Hello World")

    def test_delete_file(self):
        path = self._unique_path("delete_me.txt")
        self.assertTrue(self.fs.create_file(path, "Temporary", self.user))
        self.assertTrue(self.fs.delete(path, self.user, permanent=True))
        node = self.fs.resolve(path, self.user)
        self.assertIsNone(node)

    def test_move_to_trash_and_restore(self):
        path = self._unique_path("test_trash.txt")
        self.assertTrue(self.fs.create_file(path, "Trash Me", self.user))
        success, _trash_path = self.fs.move_to_trash(path, self.user)
        self.assertTrue(success)
        self._clear_caches()
        node = self.fs.resolve(path, self.user)
        self.assertIsNone(node)
        items = self.fs.list_trash(self.user)
        self.assertTrue(len(items) > 0)
        filename = os.path.basename(path)
        self.assertTrue(self.fs.restore_from_trash(filename, self.user))
        self._clear_caches()
        node = self.fs.resolve(path, self.user)
        self.assertIsNotNone(node)

    def test_copy_and_move(self):
        src = self._unique_path("source.txt")
        dst = self._unique_path("dest.txt")
        moved = self._unique_path("moved.txt")
        self.assertTrue(self.fs.create_file(src, "Source Content", self.user))
        self.assertTrue(self.fs.copy(src, dst, self.user))
        dest_content = self.fs.read_file(dst, self.user)
        self.assertEqual(dest_content, "Source Content")
        self.assertTrue(self.fs.move(src, moved, self.user))
        src_node = self.fs.resolve(src, self.user)
        self.assertIsNone(src_node)
        moved_content = self.fs.read_file(moved, self.user)
        self.assertEqual(moved_content, "Source Content")


class DefineAIWindow(KikiWindow):
    def __init__(self, master, shell, pattern=None):
        super().__init__(
            master, title=f"定义 AI 规则: {pattern or '新规则'}", width=700, height=500
        )
        self.shell = shell
        self.pattern = pattern or "未命名"

        # 提示标签
        info = ctk.CTkLabel(
            self.content_frame,
            text=f"编写 Python 代码定义规则 '{self.pattern}'\n必须定义 response(text, context, shell) 函数",
            font=("Arial", 12),
        )
        info.pack(pady=5)

        # 代码编辑器
        self.code_editor = ctk.CTkTextbox(self.content_frame, font=("Courier New", 12), wrap="none")
        self.code_editor.pack(fill="both", expand=True, padx=10, pady=5)

        # 状态标签（用于显示操作结果）
        self.status_label = ctk.CTkLabel(self.content_frame, text="", font=("Arial", 12))
        self.status_label.pack(pady=5)

        # 按钮栏
        btn_frame = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        btn_frame.pack(pady=10)

        ctk.CTkButton(
            btn_frame,
            text="保存并关闭",
            command=self._save_and_close,
            width=120,
            fg_color="#4CAF50",
        ).pack(side="left", padx=5)
        ctk.CTkButton(
            btn_frame, text="取消", command=self.destroy, width=80, fg_color="#f44336"
        ).pack(side="left", padx=5)

        # 默认示例代码
        default_code = '''def response(text, context, shell):
    """处理用户输入的规则，返回 (回复文本, emoji)"""
    # 示例：识别“你好”返回问候
    if "你好" in text:
        return "你好呀！", "👋"
    return "我不理解这个指令", "🤔"
'''
        self.code_editor.insert("1.0", default_code)

    def _save_and_close(self):
        code = self.code_editor.get("1.0", "end-1c")
        if not code.strip():
            self.status_label.configure(text="❌ 请输入代码", text_color="red")
            return
        if "def response" not in code:
            self.status_label.configure(
                text="❌ 必须定义 response(text, context, shell) 函数", text_color="red"
            )
            return
        try:
            compile(code, "<ai_define>", "exec")
        except SyntaxError as e:
            self.status_label.configure(text=f"❌ 语法错误: {e}", text_color="red")
            return

        # 检查规则是否已存在
        import json
        import os

        rules_path = os.path.join(os.path.dirname(__file__), "config", "ai_rules.json")
        try:
            with open(rules_path, "r", encoding="utf-8") as f:
                rules = json.load(f)
        except Exception:
            rules = []
        for rule in rules:
            if rule.get("pattern") == self.pattern:
                self.status_label.configure(
                    text=f"❌ 规则 '{self.pattern}' 已存在，请先删除", text_color="red"
                )
                return

        # 保存规则（不打印到终端）
        success = self.shell._add_ai_rule(self.pattern, "自定义函数", "🔧", code=code, silent=True)
        if success:
            self.status_label.configure(
                text=f"✅ 规则 '{self.pattern}' 已成功添加！窗口将自动关闭...",
                text_color="green",
            )
            self.gui.after(1500, self.destroy)


class AppStoreWindow(KikiWindow):
    def __init__(self, master, shell):
        super().__init__(master, title="KIKI OS 应用商店", width=900, height=600)
        self.shell = shell
        self.repo = {}
        self.installed = []
        self.app_list = []
        self.selected_app = None

        self._build_ui()
        self._refresh()

    # ---------- 界面构建 ----------
    def _build_ui(self):
        main_frame = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        main_frame.pack(fill="both", expand=True, padx=10, pady=10)

        # 搜索栏
        search_frame = ctk.CTkFrame(main_frame, fg_color="transparent")
        search_frame.pack(fill="x", pady=(0, 10))

        ctk.CTkLabel(search_frame, text="搜索:", font=("Arial", 12)).pack(side="left", padx=5)
        self.search_var = ctk.StringVar()
        self.search_entry = ctk.CTkEntry(search_frame, textvariable=self.search_var, width=300)
        self.search_entry.pack(side="left", fill="x", expand=True, padx=5)
        self.search_entry.bind("<KeyRelease>", self._filter_apps)

        ctk.CTkButton(search_frame, text="刷新", command=self._refresh, width=80).pack(
            side="right", padx=5
        )

        # 内容
        content_frame = ctk.CTkFrame(main_frame, fg_color="transparent")
        content_frame.pack(fill="both", expand=True)

        # 左侧列表
        list_frame = ctk.CTkFrame(content_frame, fg_color="#2a2a2a", corner_radius=8)
        list_frame.pack(side="left", fill="both", expand=True, padx=(0, 10))

        self.app_listbox = ctk.CTkScrollableFrame(list_frame, fg_color="transparent")
        self.app_listbox.pack(fill="both", expand=True, padx=5, pady=5)

        # 右侧详情
        detail_frame = ctk.CTkFrame(content_frame, fg_color="#2a2a2a", corner_radius=8, width=250)
        detail_frame.pack(side="right", fill="y")
        detail_frame.pack_propagate(False)

        self.detail_title = ctk.CTkLabel(detail_frame, text="", font=("Arial", 16, "bold"))
        self.detail_title.pack(pady=(15, 5))

        self.detail_version = ctk.CTkLabel(detail_frame, text="", font=("Arial", 12))
        self.detail_version.pack(pady=2)

        self.detail_author = ctk.CTkLabel(detail_frame, text="", font=("Arial", 12))
        self.detail_author.pack(pady=2)

        self.detail_desc = ctk.CTkLabel(
            detail_frame, text="", font=("Arial", 11), wraplength=230, justify="left"
        )
        self.detail_desc.pack(pady=10, padx=10)

        self.detail_status = ctk.CTkLabel(detail_frame, text="", font=("Arial", 10))
        self.detail_status.pack(pady=5)

        btn_frame = ctk.CTkFrame(detail_frame, fg_color="transparent")
        btn_frame.pack(pady=10)

        self.install_btn = ctk.CTkButton(
            btn_frame,
            text="安装",
            command=self._install_selected,
            width=80,
            fg_color="#4CAF50",
        )
        self.install_btn.pack(side="left", padx=5)

        self.uninstall_btn = ctk.CTkButton(
            btn_frame,
            text="卸载",
            command=self._uninstall_selected,
            width=80,
            fg_color="#f44336",
        )
        self.uninstall_btn.pack(side="left", padx=5)

    # ---------- 数据加载 ----------
    def _refresh(self):
        # 强制从配置重新加载已安装列表
        self.shell._load_installed_apps()
        self.repo = self.shell._load_repo()
        self.installed = self.shell.installed_apps if hasattr(self.shell, "installed_apps") else []
        self.app_list = list(self.repo.keys())
        self._display_apps(self.app_list)
        if hasattr(self, "selected_app") and self.selected_app in self.repo:
            self._show_detail(self.selected_app)
        else:
            self._clear_detail()

    def _display_apps(self, app_names):
        for widget in self.app_listbox.winfo_children():
            widget.destroy()

        for app_name in sorted(app_names):
            info = self.repo.get(app_name, {})
            installed = app_name in self.installed

            item_frame = ctk.CTkFrame(self.app_listbox, fg_color="transparent")
            item_frame.pack(fill="x", pady=2)

            name_label = ctk.CTkLabel(
                item_frame, text=app_name, font=("Arial", 12, "bold"), cursor="hand2"
            )
            name_label.pack(side="left", padx=5)
            name_label.bind("<Button-1>", lambda e, app=app_name: self._select_app(app))

            version = info.get("version", "")
            ctk.CTkLabel(item_frame, text=version, font=("Arial", 10), text_color="#aaa").pack(
                side="left", padx=5
            )

            if installed:
                ctk.CTkLabel(item_frame, text="✅", font=("Arial", 12)).pack(side="right", padx=5)

    def _select_app(self, app_name):
        self.selected_app = app_name
        self._show_detail(app_name)

    def _show_detail(self, app_name):
        info = self.repo.get(app_name, {})
        self.detail_title.configure(text=app_name)
        self.detail_version.configure(text=f"版本: {info.get('version', '未知')}")
        self.detail_author.configure(text=f"作者: {info.get('author', '未知')}")
        self.detail_desc.configure(text=info.get("description", "无描述"))

        installed = app_name in self.installed
        self.detail_status.configure(
            text="已安装" if installed else "未安装",
            text_color="#4CAF50" if installed else "#f44336",
        )
        self.install_btn.configure(state="normal" if not installed else "disabled")
        self.uninstall_btn.configure(state="normal" if installed else "disabled")

    def _clear_detail(self):
        self.detail_title.configure(text="")
        self.detail_version.configure(text="")
        self.detail_author.configure(text="")
        self.detail_desc.configure(text="")
        self.detail_status.configure(text="")
        self.install_btn.configure(state="disabled")
        self.uninstall_btn.configure(state="disabled")

    def _filter_apps(self, event=None):
        keyword = self.search_var.get().strip().lower()
        if not keyword:
            self._display_apps(self.app_list)
        else:
            filtered = [app for app in self.app_list if keyword in app.lower()]
            self._display_apps(filtered)

    # ---------- 核心操作（缩进已对齐） ----------
    def _install_selected(self):
        if not hasattr(self, "selected_app"):
            return
        app = self.selected_app
        if app in self.shell.installed_apps or app in self.shell.COMMANDS:
            messagebox.showinfo("提示", f"应用 '{app}' 已安装")
            return

        import sys
        from io import StringIO

        old_stdout = sys.stdout
        sys.stdout = StringIO()
        try:
            self.shell.store_cmd(f"install {app}")
            output = sys.stdout.getvalue()

            # 强制重新加载已安装列表
            self.shell._load_installed_apps()

            # 检查是否安装成功
            if app in self.shell.COMMANDS or app in self.shell.installed_apps:
                messagebox.showinfo("安装成功", f"应用 '{app}' 安装成功！")
                self._refresh()
            else:
                self.shell._load_third_party_apps()
                if app in self.shell.COMMANDS:
                    messagebox.showinfo("安装成功", f"应用 '{app}' 安装成功！")
                    self._refresh()
                else:
                    messagebox.showerror("安装失败", output or "安装失败，请检查日志")
        except Exception as e:
            messagebox.showerror("安装失败", str(e))
        finally:
            sys.stdout = old_stdout

    def _uninstall_selected(self):
        if not hasattr(self, "selected_app"):
            return
        app = self.selected_app
        if app not in self.shell.installed_apps and app not in self.shell.COMMANDS:
            messagebox.showinfo("提示", f"应用 '{app}' 未安装")
            return

        if not messagebox.askyesno("确认卸载", f"确定要卸载 '{app}' 吗？"):
            return

        import sys
        from io import StringIO

        old_stdout = sys.stdout
        sys.stdout = StringIO()
        try:
            self.shell.store_cmd(f"remove {app}")
            output = sys.stdout.getvalue()

            # 强制重新加载已安装列表
            self.shell._load_installed_apps()

            if app not in self.shell.COMMANDS and app not in self.shell.installed_apps:
                messagebox.showinfo("卸载成功", f"应用 '{app}' 已卸载。")
                self._refresh()
            else:
                self.shell._register_commands()
                if app not in self.shell.COMMANDS:
                    messagebox.showinfo("卸载成功", f"应用 '{app}' 已卸载。")
                    self._refresh()
                else:
                    messagebox.showerror("卸载失败", output or "卸载失败，请检查日志")
        except Exception as e:
            messagebox.showerror("卸载失败", str(e))
        finally:
            sys.stdout = old_stdout


