class WeatherWindow(KikiWindow):
    def __init__(self, master, shell):
        super().__init__(master, title="天气查询", width=480, height=380)
        self.shell = shell
        self._build_ui()
        self._query("Beijing")

    def _build_ui(self):
        frame = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        frame.pack(fill="x", padx=10, pady=5)
        self.city_entry = ctk.CTkEntry(frame, placeholder_text="输入城市名...")
        self.city_entry.pack(side="left", fill="x", expand=True, padx=5)
        self.search_btn = ctk.CTkButton(frame, text="查询", command=self._on_search)
        self.search_btn.pack(side="right", padx=5)
        self.city_entry.bind("<Return>", lambda e: self._on_search())
        self.info_frame = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        self.info_frame.pack(fill="both", expand=True, padx=10, pady=5)
        self.weather_label = ctk.CTkLabel(self.info_frame, text="", font=("Arial", 24))
        self.weather_label.pack(pady=10)
        self.temp_label = ctk.CTkLabel(self.info_frame, text="", font=("Arial", 16))
        self.temp_label.pack()
        self.detail_label = ctk.CTkLabel(self.info_frame, text="", font=("Arial", 12))
        self.detail_label.pack()

    def _on_search(self):
        city = self.city_entry.get().strip()
        if city:
            self._query(city)

    def _query(self, city):
        import requests
        try:
            r = requests.get(
                f"https://wttr.in/{city}",
                params={"format": "j1", "lang": "zh"},
                timeout=10,
            )
            if r.status_code != 200:
                self.weather_label.configure(text=f"❌ 查询失败: HTTP {r.status_code}")
                return
            data = r.json()
            cur = data["current_condition"][0]
            desc = cur.get("lang_zh", [{}])[0].get("value") or cur["weatherDesc"][0]["value"]
            t = cur["temp_C"]
            h = cur["humidity"]
            w = cur["windspeedKmph"]
            self.weather_label.configure(text=f"🌤 {desc}")
            self.temp_label.configure(text=f"温度: {t}°C")
            self.detail_label.configure(text=f"湿度: {h}%  风速: {w}km/h")
        except Exception as e:
            self.weather_label.configure(text=f"错误: {e}")
            

class PingWindow(KikiWindow):
    def __init__(self, master, shell):
        super().__init__(master, title="网络诊断", width=600, height=450)
        self.shell = shell
        self.running = False
        self._build_ui()
        self._stats = {"sent": 0, "received": 0, "lost": 0, "times": []}

    def _build_ui(self):
        top = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        top.pack(fill="x", padx=10, pady=5)
        self.host_entry = ctk.CTkEntry(top, placeholder_text="输入IP或域名...")
        self.host_entry.pack(side="left", fill="x", expand=True, padx=5)
        self.start_btn = ctk.CTkButton(top, text="开始", command=self._toggle)
        self.start_btn.pack(side="right", padx=5)
        self.stat_frame = ctk.CTkFrame(self.content_frame)
        self.stat_frame.pack(fill="x", padx=10, pady=5)
        self.sent_l = ctk.CTkLabel(self.stat_frame, text="已发送: 0")
        self.sent_l.pack(side="left", padx=10)
        self.recv_l = ctk.CTkLabel(self.stat_frame, text="已接收: 0")
        self.recv_l.pack(side="left", padx=10)
        self.lost_l = ctk.CTkLabel(self.stat_frame, text="丢包率: 0%")
        self.lost_l.pack(side="left", padx=10)
        self.avg_l = ctk.CTkLabel(self.stat_frame, text="平均延迟: 0ms")
        self.avg_l.pack(side="left", padx=10)
        self.canvas = tk.Canvas(self.content_frame, bg="#1e1e1e", highlightthickness=0)
        self.canvas.pack(fill="both", expand=True, padx=10, pady=5)

    def _toggle(self):
        if self.running:
            self.running = False
            self.start_btn.configure(text="开始")
        else:
            host = self.host_entry.get().strip() or "127.0.0.1"
            self.running = True
            self.start_btn.configure(text="停止")
            self._stats = {"sent": 0, "received": 0, "lost": 0, "times": []}
            threading.Thread(target=self._ping_loop, args=(host,), daemon=True).start()

    def _ping_loop(self, host):
        import re
        import subprocess
        import time

        while self.running:
            try:
                p = subprocess.run(
                    ["ping", "-n", "1", "-w", "1000", host],
                    capture_output=True,
                    text=True,
                    timeout=2,
                )
                self._stats["sent"] += 1
                if p.returncode == 0:
                    m = re.search(r"time[=<](\d+\.?\d*)ms", p.stdout)
                    if m:
                        t = float(m.group(1))
                        self._stats["times"].append(t)
                        self._stats["received"] += 1
                    else:
                        self._stats["lost"] += 1
                else:
                    self._stats["lost"] += 1
            except Exception:
                self._stats["lost"] += 1
            self.after(0, self._update_stats)
            time.sleep(0.5)

    def _update_stats(self):
        s = self._stats
        self.sent_l.configure(text=f"已发送: {s['sent']}")
        self.recv_l.configure(text=f"已接收: {s['received']}")
        lost_rate = (s["lost"] / max(1, s["sent"])) * 100
        self.lost_l.configure(text=f"丢包率: {lost_rate:.1f}%")
        avg = sum(s["times"]) / len(s["times"]) if s["times"] else 0
        self.avg_l.configure(text=f"平均延迟: {avg:.1f}ms")
        self.canvas.delete("all")
        if s["times"]:
            max_t = max(max(s["times"]), 1)
            w = self.canvas.winfo_width() - 20
            h = self.canvas.winfo_height() - 20
            pts = []
            for i, t in enumerate(s["times"][-60:]):
                x = 10 + (i / 60) * w
                y = 10 + h - (t / max_t) * h * 0.9
                pts.append((x, y))
            if len(pts) > 1:
                for i in range(len(pts) - 1):
                    self.canvas.create_line(
                        pts[i][0],
                        pts[i][1],
                        pts[i + 1][0],
                        pts[i + 1][1],
                        fill="#00ff00",
                        width=2,
                    )


class DiskUsageWindow(KikiWindow):
    def __init__(self, master, shell):
        super().__init__(master, title="磁盘使用情况", width=600, height=400)
        self.shell = shell
        self._build_ui()
        self._update()

    def _build_ui(self):
        self.tree = ttk.Treeview(
            self.content_frame,
            columns=("size", "used", "free", "percent"),
            show="tree headings",
        )
        self.tree.heading("#0", text="路径")
        self.tree.heading("size", text="总大小")
        self.tree.heading("used", text="已用")
        self.tree.heading("free", text="可用")
        self.tree.heading("percent", text="使用率")
        self.tree.pack(fill="both", expand=True, padx=10, pady=10)
        self.tree.bind("<<TreeviewSelect>>", self._on_select)
        self.canvas_frame = ctk.CTkFrame(self.content_frame, height=200)
        self.canvas_frame.pack(fill="x", padx=10, pady=5)

    def _update(self):
        for item in self.tree.get_children():
            self.tree.delete(item)
        try:
            import psutil

            for part in psutil.disk_partitions():
                try:
                    usage = psutil.disk_usage(part.mountpoint)
                    self.tree.insert(
                        "",
                        "end",
                        text=part.mountpoint,
                        values=(
                            self._fmt(usage.total),
                            self._fmt(usage.used),
                            self._fmt(usage.free),
                            f"{usage.percent:.1f}%",
                        ),
                    )
                except Exception:
                    pass
        except Exception:
            total = self.shell.hw.ram_mb * 1024 * 1024
            used = self.shell.fs.get_total_size()
            free = total - used
            self.tree.insert(
                "",
                "end",
                text="/",
                values=(
                    self._fmt(total),
                    self._fmt(used),
                    self._fmt(free),
                    f"{used/total*100:.1f}%",
                ),
            )

    def _fmt(self, b):
        for u in ["B", "KB", "MB", "GB"]:
            if b < 1024:
                return f"{b:.1f}{u}"
            b /= 1024
        return f"{b:.1f}TB"

    def _on_select(self, evt):
        sel = self.tree.selection()
        if not sel:
            return
        path = self.tree.item(sel[0], "text")
        try:
            import psutil

            usage = psutil.disk_usage(path)
            used, free = usage.used, usage.free
            total = used + free
        except Exception:
            return
        for w in self.canvas_frame.winfo_children():
            w.destroy()
        c = ctk.CTkCanvas(self.canvas_frame, bg="#1e1e1e", highlightthickness=0)
        c.pack(fill="both", expand=True)
        w = c.winfo_width() or 300
        h = c.winfo_height() or 150
        c.create_rectangle(10, 10, w - 10, h - 10, fill="#3a3a3a")
        used_w = (used / total) * (w - 20) if total else 0
        c.create_rectangle(10, 10, 10 + used_w, h - 10, fill="#4CAF50", tags="used")
        c.create_text(30, h // 2, text=f"已用: {self._fmt(used)}", fill="white", anchor="w")
        c.create_text(30, h // 2 + 20, text=f"可用: {self._fmt(free)}", fill="white", anchor="w")
        c.create_text(
            w - 20,
            20,
            text=f"使用率: {used/total*100:.1f}%" if total else "0%",
            fill="white",
            anchor="e",
        )


class HTTPServerWindow(KikiWindow):
    def __init__(self, master, shell):
        super().__init__(master, title="HTTP 服务器", width=700, height=500)
        self.shell = shell
        self.server = None
        self.thread = None
        self._build_ui()

    def _build_ui(self):
        top = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        top.pack(fill="x", padx=10, pady=5)
        ctk.CTkLabel(top, text="端口:").pack(side="left", padx=5)
        self.port_entry = ctk.CTkEntry(top, width=80)
        self.port_entry.insert(0, "8000")
        self.port_entry.pack(side="left", padx=5)
        self.toggle_btn = ctk.CTkButton(top, text="启动", command=self._toggle)
        self.toggle_btn.pack(side="left", padx=5)
        self.status_label = ctk.CTkLabel(top, text="状态: 停止", text_color="red")
        self.status_label.pack(side="left", padx=20)
        self.log_text = ctk.CTkTextbox(
            self.content_frame, font=("Courier New", 10), wrap="none", state="disabled"
        )
        self.log_text.pack(fill="both", expand=True, padx=10, pady=5)

    def _toggle(self):
        if self.server:
            self._stop()
        else:
            self._start()

    def _start(self):
        port = int(self.port_entry.get().strip() or 8000)
        import http.server
        import socketserver

        handler = http.server.SimpleHTTPRequestHandler
        self.server = socketserver.TCPServer(("", port), handler)
        self.thread = threading.Thread(target=self._serve, daemon=True)
        self.thread.start()
        self.toggle_btn.configure(text="停止")
        self.status_label.configure(text=f"状态: 运行中 :{port}", text_color="green")

    def _serve(self):
        self.log("服务器启动")
        self.server.serve_forever()

    def _stop(self):
        if self.server:
            self.server.shutdown()
            self.server = None
            self.thread = None
            self.toggle_btn.configure(text="启动")
            self.status_label.configure(text="状态: 停止", text_color="red")
            self.log("服务器停止")

    def log(self, msg):
        self.log_text.configure(state="normal")
        self.log_text.insert("end", f"[{datetime.now().strftime('%H:%M:%S')}] {msg}\n")
        self.log_text.see("end")
        self.log_text.configure(state="disabled")


class ScheduleWindow(KikiWindow):
    def __init__(self, master, shell):
        super().__init__(master, title="定时任务", width=600, height=400)
        self.shell = shell
        self.tasks = []
        self._load()
        self._build_ui()
        self._refresh()

    def _build_ui(self):
        self.tree = ttk.Treeview(self.content_frame, columns=("time", "command"), show="headings")
        self.tree.heading("time", text="执行时间")
        self.tree.heading("command", text="命令")
        self.tree.pack(fill="both", expand=True, padx=10, pady=10)
        btn_frame = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        btn_frame.pack(fill="x", padx=10, pady=5)
        ctk.CTkButton(btn_frame, text="添加任务", command=self._add_task).pack(side="left", padx=5)
        ctk.CTkButton(btn_frame, text="删除选中", command=self._del_task).pack(side="left", padx=5)
        ctk.CTkButton(btn_frame, text="刷新", command=self._refresh).pack(side="left", padx=5)

    def _load(self):
        self.tasks = self.shell.config.get("schedule_tasks", [])

    def _save(self):
        self.shell.config.set("schedule_tasks", self.tasks, self.shell.username)
        self.shell.config.save_user_config(self.shell.username)

    def _refresh(self):
        for item in self.tree.get_children():
            self.tree.delete(item)
        now = time.time()
        for t in self.tasks:
            if t["time"] > now:
                dt = datetime.fromtimestamp(t["time"]).strftime("%Y-%m-%d %H:%M")
                self.tree.insert("", "end", values=(dt, t["command"]))

    def _add_task(self):
        from tkinter import simpledialog

        dt_str = simpledialog.askstring("定时任务", "输入执行时间 (格式: YYYY-MM-DD HH:MM):")
        if not dt_str:
            return
        try:
            dt = datetime.strptime(dt_str, "%Y-%m-%d %H:%M")
            if dt <= datetime.now():
                raise ValueError("时间在过去")
        except Exception:
            messagebox.showerror("错误", "时间格式无效或早于当前时间")
            return
        # ===== 关键修复：命令支持完整的带参数字符串 =====
        cmd = simpledialog.askstring("定时任务", "输入完整的命令 (支持参数，例如: ai 你好):")
        if not cmd:
            return
        self.tasks.append({"time": dt.timestamp(), "command": cmd})
        self._save()
        self._refresh()

    def _del_task(self):
        sel = self.tree.selection()
        if not sel:
            return
        idx = self.tree.index(sel[0])
        if idx < len(self.tasks):
            del self.tasks[idx]
            self._save()
            self._refresh()


class CryptoWindow(KikiWindow):
    def __init__(self, master, shell, mode="encrypt"):
        super().__init__(
            master,
            title=f"{'加密' if mode=='encrypt' else '解密'}文件",
            width=600,
            height=400,
        )
        self.shell = shell
        self.mode = mode
        self._build_ui()

    def _build_ui(self):
        top = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        top.pack(fill="x", padx=10, pady=5)
        self.path_entry = ctk.CTkEntry(top, placeholder_text="文件或目录路径")
        self.path_entry.pack(side="left", fill="x", expand=True, padx=5)
        ctk.CTkButton(top, text="浏览", command=self._browse).pack(side="left", padx=5)
        ctk.CTkButton(top, text="执行", command=self._run).pack(side="left", padx=5)
        self.pwd_frame = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        self.pwd_frame.pack(fill="x", padx=10, pady=5)
        ctk.CTkLabel(self.pwd_frame, text="密码:").pack(side="left", padx=5)
        self.pwd_entry = ctk.CTkEntry(self.pwd_frame, show="*")
        self.pwd_entry.pack(side="left", fill="x", expand=True, padx=5)
        self.log_text = ctk.CTkTextbox(
            self.content_frame, font=("Courier New", 10), wrap="none", state="disabled"
        )
        self.log_text.pack(fill="both", expand=True, padx=10, pady=5)

    def _browse(self):
        from tkinter import filedialog

        f = filedialog.askopenfilename(title="选择文件")
        if f:
            self.path_entry.delete(0, "end")
            self.path_entry.insert(0, f)

    def _run(self):
        path = self.path_entry.get().strip()
        if not path:
            messagebox.showerror("错误", "请选择文件")
            return
        pwd = self.pwd_entry.get()
        if not pwd:
            messagebox.showerror("错误", "请输入密码")
            return
        import threading

        def worker():
            import sys
            from io import StringIO

            old = sys.stdout
            sys.stdout = StringIO()
            try:
                if self.mode == "encrypt":
                    self.shell.encrypt_cmd(f"{path} --password {pwd}")
                else:
                    self.shell.decrypt_cmd(f"{path} --password {pwd}")
                out = sys.stdout.getvalue()
                self.after(0, self._log, out)
            except Exception as e:
                self.after(0, self._log, f"错误: {e}")
            finally:
                sys.stdout = old

        threading.Thread(target=worker, daemon=True).start()

    def _log(self, msg):
        self.log_text.configure(state="normal")
        self.log_text.insert("end", msg + "\n")
        self.log_text.see("end")
        self.log_text.configure(state="disabled")


class RSSWindow(KikiWindow):
    def __init__(self, master, shell):
        super().__init__(master, title="RSS 阅读器", width=800, height=550)
        self.shell = shell
        self.feeds = self.shell.config.get("rss_feeds", [])
        self.entries = []
        self._build_ui()
        self._load_feeds()

    def _build_ui(self):
        main = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        main.pack(fill="both", expand=True, padx=10, pady=10)
        top = ctk.CTkFrame(main, fg_color="transparent")
        top.pack(fill="x", pady=(0, 5))
        self.feed_entry = ctk.CTkEntry(top, placeholder_text="订阅源 URL")
        self.feed_entry.pack(side="left", fill="x", expand=True, padx=5)
        ctk.CTkButton(top, text="添加", command=self._add_feed).pack(side="left", padx=5)
        ctk.CTkButton(top, text="刷新", command=self._refresh_feeds).pack(side="left", padx=5)
        mid = ctk.CTkFrame(main, fg_color="transparent")
        mid.pack(fill="both", expand=True)
        left = ctk.CTkFrame(mid, width=200, fg_color="#2a2a2a", corner_radius=5)
        left.pack(side="left", fill="y", padx=(0, 5))
        self.feed_list = ctk.CTkScrollableFrame(left, fg_color="transparent")
        self.feed_list.pack(fill="both", expand=True, padx=5, pady=5)
        right = ctk.CTkFrame(mid, fg_color="#2a2a2a", corner_radius=5)
        right.pack(side="right", fill="both", expand=True)
        self.entry_list = ctk.CTkScrollableFrame(right, fg_color="transparent")
        self.entry_list.pack(fill="both", expand=True, padx=5, pady=5)
        bottom = ctk.CTkFrame(main, fg_color="transparent")
        bottom.pack(fill="x", pady=(5, 0))
        self.preview = ctk.CTkTextbox(bottom, font=("Arial", 11), wrap="word", height=120)
        self.preview.pack(fill="x", expand=True)

    def _load_feeds(self):
        for child in self.feed_list.winfo_children():
            child.destroy()
        for url in self.feeds:
            btn = ctk.CTkButton(
                self.feed_list,
                text=url[:30] + "...",
                command=lambda u=url: self._load_entries(u),
                fg_color="transparent",
                hover_color="#404040",
                anchor="w",
            )
            btn.pack(fill="x", pady=2)

    def _add_feed(self):
        url = self.feed_entry.get().strip()
        if url and url not in self.feeds:
            self.feeds.append(url)
            self.shell.config.set("rss_feeds", self.feeds, self.shell.username)
            self.shell.config.save_user_config(self.shell.username)
            self._load_feeds()
            self.feed_entry.delete(0, "end")

    def _refresh_feeds(self):
        for url in self.feeds:
            self._load_entries(url)

    def _load_entries(self, url):
        import feedparser

        for child in self.entry_list.winfo_children():
            child.destroy()
        feed = feedparser.parse(url)
        self.entries = feed.entries[:50]
        for entry in self.entries:
            btn = ctk.CTkButton(
                self.entry_list,
                text=entry.title,
                command=lambda e=entry: self._show_preview(e),
                fg_color="transparent",
                hover_color="#404040",
                anchor="w",
            )
            btn.pack(fill="x", pady=2)

    def _show_preview(self, entry):
        self.preview.delete("1.0", "end")
        self.preview.insert("1.0", f"{entry.title}\n\n{entry.get('summary', '')}")


class DownloadWindow(KikiWindow):
    def __init__(self, master, shell):
        super().__init__(master, title="下载管理器", width=700, height=500)
        self.shell = shell
        self.tasks = []
        self._build_ui()

    def _build_ui(self):
        top = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        top.pack(fill="x", padx=10, pady=5)
        self.url_entry = ctk.CTkEntry(top, placeholder_text="下载 URL")
        self.url_entry.pack(side="left", fill="x", expand=True, padx=5)
        ctk.CTkButton(top, text="添加", command=self._add_task).pack(side="left", padx=5)
        self.tree = ttk.Treeview(
            self.content_frame,
            columns=("url", "status", "progress", "speed"),
            show="headings",
        )
        self.tree.heading("url", text="URL")
        self.tree.heading("status", text="状态")
        self.tree.heading("progress", text="进度")
        self.tree.heading("speed", text="速度")
        self.tree.pack(fill="both", expand=True, padx=10, pady=10)
        btn_frame = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        btn_frame.pack(fill="x", padx=10, pady=5)
        ctk.CTkButton(btn_frame, text="暂停", command=self._pause_selected).pack(
            side="left", padx=5
        )
        ctk.CTkButton(btn_frame, text="删除", command=self._del_selected).pack(side="left", padx=5)

    def _add_task(self):
        url = self.url_entry.get().strip()
        if not url:
            return
        filename = url.split("/")[-1] or "downloaded"
        task = {
            "url": url,
            "filename": filename,
            "status": "等待",
            "progress": 0,
            "speed": 0,
        }
        self.tasks.append(task)
        self._refresh()
        threading.Thread(target=self._download, args=(task,), daemon=True).start()

    def _download(self, task):
        import requests

        try:
            task["status"] = "下载中"
            r = requests.get(task["url"], stream=True, timeout=10)
            total = int(r.headers.get("content-length", 0))
            downloaded = 0
            start = time.time()

            # ===== 👇 修改：把原本的宿主机 open 改成 VFS 沙盒写入 👇 =====
            buffer = bytearray()
            chunk_size = 8192
            for chunk in r.iter_content(chunk_size):
                if chunk:
                    buffer.extend(chunk)
                    downloaded += len(chunk)
                    task["progress"] = (downloaded / total * 100) if total else 0
                    task["speed"] = (
                        downloaded / (time.time() - start) if (time.time() - start) > 0 else 0
                    )
                    self.after(0, self._refresh)

            # 下载完毕后，把数据写入沙盒 VFS
            vfs_path = f"/home/{self.shell.username}/Downloads/{task['filename']}"
            # 确保 Downloads 目录存在
            if not self.shell.fs.resolve("/home/admin/Downloads", self.shell.username):
                self.shell.fs.mkdir("/home/admin/Downloads", self.shell.username)

            # 👇 最关键的一步：直接用 buffer（它本身就是 bytes），不要用 decode！👇
            self.shell.fs.create_file(vfs_path, buffer, self.shell.username)
            task["status"] = f"完成 (已存入VFS: {vfs_path})"
            # ===== 👆 修改结束 👆 =====

        except Exception as e:
            task["status"] = f"错误: {e}"
        self.after(0, self._refresh)

    def _refresh(self):
        for item in self.tree.get_children():
            self.tree.delete(item)
        for t in self.tasks:
            self.tree.insert(
                "",
                "end",
                values=(
                    t["url"],
                    t["status"],
                    f"{t['progress']:.1f}%",
                    f"{t['speed']/1024:.1f}KB/s",
                ),
            )

    def _pause_selected(self):
        pass

    def _del_selected(self):
        sel = self.tree.selection()
        if not sel:
            return
        idx = self.tree.index(sel[0])
        if idx < len(self.tasks):
            del self.tasks[idx]
            self._refresh()


class Process:
    """进程控制块"""

    def __init__(self, pid, name, instructions, priority=0):
        self.pid = pid
        self.name = name
        self.instructions = instructions
        self.pc = 0
        self.state = "READY"  # READY, RUNNING, BLOCKED, TERMINATED
        self.priority = priority
        self.registers = {"R1": 0, "R2": 0, "R3": 0}
        self.open_files = []
        self.page_table = {}  # 逻辑页 -> 物理页框
        self.memory_used = 0  # 字节数

    def __repr__(self):
        return f"Process({self.pid},{self.name},{self.state})"


class MemoryPaging:
    """分页内存管理"""

    PAGE_SIZE = 64
    NUM_PAGES = 16  # 总物理页框数
    TOTAL_MEM = PAGE_SIZE * NUM_PAGES

    def __init__(self):
        self.bitmap = [False] * self.NUM_PAGES  # False=空闲
        self.page_frames = {}  # 物理页框号 -> (pid, 逻辑页)
        self.pid_to_pages = {}  # pid -> [物理页框列表]

    def allocate_pages(self, pid, num_pages):
        """分配连续num_pages个物理页框（首次适应）"""
        frames = []
        free_run = 0
        start = -1
        for i in range(self.NUM_PAGES):
            if not self.bitmap[i]:
                if free_run == 0:
                    start = i
                free_run += 1
                if free_run == num_pages:
                    # 分配这些页
                    for j in range(start, start + num_pages):
                        self.bitmap[j] = True
                        self.page_frames[j] = (pid, len(frames))
                        frames.append(j)
                    self.pid_to_pages[pid] = frames
                    return frames
            else:
                free_run = 0
        raise MemoryError("Not enough free page frames")

    def deallocate_pages(self, pid):
        """释放进程的所有页"""
        if pid in self.pid_to_pages:
            for frame in self.pid_to_pages[pid]:
                self.bitmap[frame] = False
                del self.page_frames[frame]
            del self.pid_to_pages[pid]

    def get_frame(self, pid, logical_page):
        """获取逻辑页对应的物理页框号，若不存在则触发缺页（这里简单分配新页）"""
        if pid not in self.pid_to_pages:
            return None
        frames = self.pid_to_pages[pid]
        if logical_page < len(frames):
            return frames[logical_page]
        else:
            return None

    def status(self):
        return {
            "bitmap": self.bitmap,
            "page_frames": self.page_frames,
            "pid_to_pages": self.pid_to_pages,
        }


class PyOSScheduler:
    """多级反馈队列调度 (MLFQ) + 可选优先级"""

    def __init__(self, time_quantum=3):
        self.time_quantum = time_quantum
        self.queues = [deque(), deque(), deque()]  # Q0高优先级，时间片1, Q1:2, Q2:4
        self.current = None
        self.ticks_used = 0
        self.algorithm = "MLFQ"  # "RR", "PRIO", "MLFQ"

    def add_process(self, process):
        process.state = "READY"
        if self.algorithm == "PRIO":
            self.queues[0].append(process)
        else:
            self.queues[0].append(process)

    def schedule(self):
        """选择下一个进程"""
        if self.algorithm == "RR":
            if self.current and self.current.state == "RUNNING":
                if self.ticks_used >= self.time_quantum:
                    self.current.state = "READY"
                    self.queues[0].append(self.current)
                    self.current = None
                    self.ticks_used = 0
            if self.current is None and self.queues[0]:
                self.current = self.queues[0].popleft()
                self.current.state = "RUNNING"
                self.ticks_used = 0
            return self.current

        elif self.algorithm == "MLFQ":
            if self.current and self.current.state == "RUNNING":
                if self.ticks_used >= self.get_quantum_for_process(self.current):
                    self.current.state = "READY"
                    current_q = self.get_queue_level(self.current)
                    new_q = min(current_q + 1, 2)
                    self.queues[new_q].append(self.current)
                    self.current = None
                    self.ticks_used = 0

            if self.current is None:
                for i in range(3):
                    if self.queues[i]:
                        self.current = self.queues[i].popleft()
                        self.current.state = "RUNNING"
                        self.ticks_used = 0
                        break
            return self.current

        elif self.algorithm == "PRIO":
            if self.current is None and self.queues[0]:
                sorted_list = sorted(self.queues[0], key=lambda p: p.priority)
                self.current = sorted_list[0]
                self.queues[0].remove(self.current)
                self.current.state = "RUNNING"
            return self.current

    def get_quantum_for_process(self, process):
        level = self.get_queue_level(process)
        return [1, 2, 4][level]

    def get_queue_level(self, process):
        for i, q in enumerate(self.queues):
            if process in q:
                return i
        return 0

    def remove_process(self, pid):
        for q in self.queues:
            for p in list(q):
                if p.pid == pid:
                    q.remove(p)
                    return p
        if self.current and self.current.pid == pid:
            p = self.current
            self.current = None
            self.ticks_used = 0
            return p
        return None

    def set_algorithm(self, alg):
        self.algorithm = alg
        all_procs = []
        for q in self.queues:
            all_procs.extend(q)
        if self.current:
            all_procs.append(self.current)
        self.queues = [deque(), deque(), deque()]
        for p in all_procs:
            p.state = "READY"
            self.add_process(p)


class SystemCall:
    @staticmethod
    def print_text(text):
        return f"[SYSOUT] {text}"

    @staticmethod
    def halt(process):
        process.state = "TERMINATED"

    @staticmethod
    def open_file(fs, process, filename):
        if filename in fs.files:
            if filename not in process.open_files:
                process.open_files.append(filename)
            return True
        else:
            return False

    @staticmethod
    def read_file(fs, process, filename):
        if filename in process.open_files or filename in fs.files:
            content = fs.read(filename)
            if content is not None:
                return f"Content of {filename}: {content}"
            else:
                return f"File '{filename}' is empty"
        else:
            return f"[ERROR] File '{filename}' not opened or does not exist"

    @staticmethod
    def write_file(fs, process, filename, content):
        fs.write(filename, content)
        if filename not in process.open_files:
            process.open_files.append(filename)
        return f"Written to {filename}"


class CPU:
    def __init__(self, os_sim):
        self.os = os_sim

    def execute_one_instruction(self, process):
        """执行一条指令，返回 (继续运行, 输出信息)"""
        output = ""
        if process.pc >= len(process.instructions):
            process.state = "TERMINATED"
            return False, "Process finished (no more instructions)"

        instr = process.instructions[process.pc]
        opcode = instr[0]
        process.pc += 1

        if opcode == "PRINT":
            text = instr[1]
            output = SystemCall.print_text(text)
        elif opcode == "ADD":
            dest, src = instr[1], instr[2]
            if dest in process.registers and src in process.registers:
                process.registers[dest] += process.registers[src]
            elif dest in process.registers and isinstance(src, int):
                process.registers[dest] += src
            else:
                output = f"[WARN] Invalid ADD: {instr}"
        elif opcode == "SUB":
            dest, src = instr[1], instr[2]
            if dest in process.registers and src in process.registers:
                process.registers[dest] -= process.registers[src]
            elif dest in process.registers and isinstance(src, int):
                process.registers[dest] -= src
            else:
                output = f"[WARN] Invalid SUB: {instr}"
        elif opcode == "JMP":
            target = instr[1]
            if isinstance(target, int) and 0 <= target < len(process.instructions):
                process.pc = target
            else:
                output = f"[WARN] Invalid JMP target: {target}"
        elif opcode == "JZ":
            reg, target = instr[1], instr[2]
            if reg in process.registers and process.registers[reg] == 0:
                if isinstance(target, int) and 0 <= target < len(process.instructions):
                    process.pc = target
                else:
                    output = f"[WARN] Invalid JZ target: {target}"
        elif opcode == "HALT":
            SystemCall.halt(process)
            return False, "Process halted"
        elif opcode == "OPEN":
            filename = instr[1]
            success = SystemCall.open_file(self.os.fs, process, filename)
            output = f"OPEN {filename}: {'success' if success else 'failed'}"
        elif opcode == "READ":
            filename = instr[1]
            output = SystemCall.read_file(self.os.fs, process, filename)
        elif opcode == "WRITE":
            filename, content = instr[1], instr[2]
            output = SystemCall.write_file(self.os.fs, process, filename, content)
        else:
            output = f"[WARN] Unknown opcode: {opcode}"

        return process.state != "TERMINATED", output


class FileSystem:
    def __init__(self):
        self.files = {}

    def create(self, name, content=""):
        self.files[name] = content

    def read(self, name):
        return self.files.get(name, None)

    def write(self, name, content):
        self.files[name] = content

    def list(self):
        return list(self.files.keys())

    def delete(self, name):
        if name in self.files:
            del self.files[name]


class OSSimulator:
    def __init__(self):
        self.pid_counter = 0
        self.processes = {}
        self.memory = MemoryPaging()
        self.fs = FileSystem()
        self.scheduler = PyOSScheduler()
        self.cpu = CPU(self)
        self.running = False
        self.paused = False
        self.ticks = 0
        self.callbacks = []
        self.output_log = []

    def create_process(self, name, instructions, priority=0):
        pid = self.pid_counter
        self.pid_counter += 1
        num_pages = max(1, (len(instructions) + self.memory.PAGE_SIZE - 1) // self.memory.PAGE_SIZE)
        try:
            frames = self.memory.allocate_pages(pid, num_pages)
        except MemoryError as e:
            self.log(f"Memory allocation failed: {e}")
            return None
        process = Process(pid, name, instructions, priority)
        process.page_table = {i: frames[i] for i in range(len(frames))}
        process.memory_used = len(frames) * self.memory.PAGE_SIZE
        self.processes[pid] = process
        self.scheduler.add_process(process)
        self.log(f"Created process {pid} ({name}) with {len(frames)} pages")
        self.update_gui()
        return process

    def terminate_process(self, pid):
        if pid in self.processes:
            proc = self.processes[pid]
            self.scheduler.remove_process(pid)
            self.memory.deallocate_pages(pid)
            proc.state = "TERMINATED"
            del self.processes[pid]
            self.log(f"Terminated process {pid}")
            self.update_gui()
        else:
            self.log(f"Process {pid} not found")

    def run_tick(self):
        if self.paused:
            return
        process = self.scheduler.schedule()
        if process is None:
            self.log("Idle (no ready processes)")
            return

        keep, output = self.cpu.execute_one_instruction(process)
        if output:
            self.log(output)
        if not keep or process.state == "TERMINATED":
            self.terminate_process(process.pid)
        else:
            self.scheduler.ticks_used += 1
        self.ticks += 1
        self.update_gui()

    def run_forever(self, steps=None):
        self.running = True
        self.paused = False
        count = 0
        while self.running and not self.paused:
            if self.scheduler.current is None and not any(
                self.scheduler.queues[i] for i in range(3)
            ):
                self.log("No processes left, halting")
                self.running = False
                break
            self.run_tick()
            count += 1
            if steps and count >= steps:
                break
        self.running = False

    def log(self, message):
        self.output_log.append(message)
        self.update_gui()

    def update_gui(self):
        for cb in self.callbacks:
            cb()

    def set_scheduler_algorithm(self, alg):
        self.scheduler.set_algorithm(alg)
        self.log(f"Scheduler algorithm set to {alg}")

    def get_process_info(self):
        info = []
        for pid, p in self.processes.items():
            info.append(
                {
                    "pid": pid,
                    "name": p.name,
                    "state": p.state,
                    "pc": p.pc,
                    "priority": p.priority,
                    "regs": p.registers.copy(),
                    "pages": len(p.page_table),
                }
            )
        return info

    def get_memory_status(self):
        return self.memory.status()

    def get_file_list(self):
        return self.fs.list()

    def read_file(self, name):
        return self.fs.read(name)


class PyOSLabWindow(KikiWindow):
    def __init__(self, master, shell=None):
        super().__init__(master, title="系统实验室", width=1000, height=800)
        self.geometry(f"{self.winfo_screenwidth()}x{self.winfo_screenheight()}+0+0")
        self.layout_container = ctk.CTkFrame(self.content_frame, fg_color="transparent")
        self.layout_container.pack(fill="both", expand=True)
        self.title("PyOS - Operating System Simulator")
        self.geometry("1200x700")
        self.resizable(True, True)

        self.os = OSSimulator()
        self.create_widgets()  # 先创建组件
        self.os.callbacks.append(self.refresh_ui)  # 再绑定回调
        self.os.set_scheduler_algorithm("MLFQ")
        self.after(500, self.refresh_ui)
        self.protocol("WM_DELETE_WINDOW", self.on_close)
        self.init_demo()

    def on_close(self):
        # 1. 强制停止虚拟机的循环
        self.os.running = False
        self.os.paused = False
        # 2. 把自己从回调列表中移除，防止后台线程反复撞墙
        if self.refresh_ui in self.os.callbacks:
            self.os.callbacks.remove(self.refresh_ui)
        # 3. 真正地销毁这个窗口
        self.destroy()

    def create_widgets(self):
        # 主布局
        self.layout_container.grid_columnconfigure(0, weight=3)  # 左边占 3 份宽
        self.layout_container.grid_columnconfigure(1, weight=2)  # 右边占 2 份宽
        self.layout_container.grid_rowconfigure(0, weight=1)  # 上下撑满

        # 左框架
        left_frame = ctk.CTkFrame(self.layout_container)
        left_frame.grid(row=0, column=0, sticky="nsew", padx=5, pady=5)
        left_frame.grid_rowconfigure(0, weight=1)
        left_frame.grid_rowconfigure(1, weight=1)
        left_frame.grid_columnconfigure(0, weight=1)

        # 进程列表
        process_frame = ctk.CTkFrame(left_frame)
        process_frame.grid(row=0, column=0, sticky="nsew", padx=5, pady=5)
        process_frame.grid_rowconfigure(0, weight=0)
        process_frame.grid_rowconfigure(1, weight=1)
        process_frame.grid_columnconfigure(0, weight=1)

        ctk.CTkLabel(process_frame, text="Processes", font=("Arial", 16, "bold")).grid(
            row=0, column=0, pady=5
        )

        # 使用 ttk.Treeview（已导入 ttk）
        self.process_tree = ttk.Treeview(
            process_frame,
            columns=("PID", "Name", "State", "PC", "Priority", "Pages"),
            show="headings",
            height=8,
        )
        self.process_tree.heading("PID", text="PID")
        self.process_tree.heading("Name", text="Name")
        self.process_tree.heading("State", text="State")
        self.process_tree.heading("PC", text="PC")
        self.process_tree.heading("Priority", text="Priority")
        self.process_tree.heading("Pages", text="Pages")
        self.process_tree.column("PID", width=50)
        self.process_tree.column("Name", width=100)
        self.process_tree.column("State", width=80)
        self.process_tree.column("PC", width=60)
        self.process_tree.column("Priority", width=60)
        self.process_tree.column("Pages", width=60)
        self.process_tree.grid(row=1, column=0, sticky="nsew", padx=5, pady=5)

        # 内存视图
        mem_frame = ctk.CTkFrame(left_frame)
        mem_frame.grid(row=1, column=0, sticky="nsew", padx=5, pady=5)
        mem_frame.grid_rowconfigure(0, weight=0)
        mem_frame.grid_rowconfigure(1, weight=1)
        mem_frame.grid_columnconfigure(0, weight=1)

        ctk.CTkLabel(mem_frame, text="Memory (Page Frames)", font=("Arial", 16, "bold")).grid(
            row=0, column=0, pady=5
        )
        self.mem_text = ctk.CTkTextbox(mem_frame, height=100)
        self.mem_text.grid(row=1, column=0, sticky="nsew", padx=5, pady=5)

        # 右框架
        right_frame = ctk.CTkFrame(self.layout_container)
        right_frame.grid(row=0, column=1, sticky="nsew", padx=5, pady=5)
        right_frame.grid_rowconfigure(0, weight=1)
        right_frame.grid_rowconfigure(1, weight=2)
        right_frame.grid_rowconfigure(2, weight=0)
        right_frame.grid_rowconfigure(3, weight=0)
        right_frame.grid_columnconfigure(0, weight=1)

        # 文件系统（使用 tk.Listbox 替代 CTkListbox）
        file_frame = ctk.CTkFrame(right_frame)
        file_frame.grid(row=0, column=0, sticky="nsew", padx=5, pady=5)
        file_frame.grid_rowconfigure(0, weight=0)
        file_frame.grid_rowconfigure(1, weight=1)
        file_frame.grid_columnconfigure(0, weight=3)
        file_frame.grid_columnconfigure(1, weight=1)

        ctk.CTkLabel(file_frame, text="File System", font=("Arial", 16, "bold")).grid(
            row=0, column=0, columnspan=2, pady=5
        )
        self.file_listbox = tk.Listbox(
            file_frame, height=12, bg="#2b2b2b", fg="white", selectbackground="#1f6aa5"
        )
        self.file_listbox.grid(row=1, column=0, sticky="nsew", padx=5, pady=5)
        self.file_listbox.bind("<<ListboxSelect>>", self.on_file_select)

        file_btn_frame = ctk.CTkFrame(file_frame)
        file_btn_frame.grid(row=1, column=1, sticky="n", padx=5, pady=5)
        ctk.CTkButton(file_btn_frame, text="Create", command=self.create_file_dialog).pack(pady=2)
        ctk.CTkButton(file_btn_frame, text="Delete", command=self.delete_file).pack(pady=2)
        ctk.CTkButton(file_btn_frame, text="Refresh", command=self.refresh_files).pack(pady=2)

        # 控制台
        console_frame = ctk.CTkFrame(right_frame)
        console_frame.grid(row=1, column=0, sticky="nsew", padx=5, pady=5)
        console_frame.grid_rowconfigure(0, weight=0)
        console_frame.grid_rowconfigure(1, weight=1)
        console_frame.grid_columnconfigure(0, weight=1)

        ctk.CTkLabel(console_frame, text="Console Output", font=("Arial", 16, "bold")).grid(
            row=0, column=0, pady=5
        )
        self.console_text = scrolledtext.ScrolledText(console_frame, height=10, wrap="word")
        self.console_text.grid(row=1, column=0, sticky="nsew", padx=5, pady=5)

        # 控制按钮
        control_frame = ctk.CTkFrame(right_frame)
        control_frame.grid(row=2, column=0, sticky="ew", padx=5, pady=5)
        control_frame.grid_columnconfigure(0, weight=1)
        control_frame.grid_columnconfigure(1, weight=1)
        control_frame.grid_columnconfigure(2, weight=1)
        control_frame.grid_columnconfigure(3, weight=1)
        control_frame.grid_columnconfigure(4, weight=1)

        ctk.CTkButton(control_frame, text="Start", command=self.start_sim).grid(
            row=0, column=0, padx=2, pady=5
        )
        ctk.CTkButton(control_frame, text="Pause", command=self.pause_sim).grid(
            row=0, column=1, padx=2, pady=5
        )
        ctk.CTkButton(control_frame, text="Step", command=self.step_sim).grid(
            row=0, column=2, padx=2, pady=5
        )
        ctk.CTkButton(control_frame, text="Stop", command=self.stop_sim).grid(
            row=0, column=3, padx=2, pady=5
        )
        ctk.CTkButton(
            control_frame, text="Create Process", command=self.create_process_dialog
        ).grid(row=0, column=4, padx=2, pady=5)

        # 调度器设置
        alg_frame = ctk.CTkFrame(right_frame)
        alg_frame.grid(row=3, column=0, sticky="ew", padx=5, pady=5)
        alg_frame.grid_columnconfigure(0, weight=1)
        alg_frame.grid_columnconfigure(1, weight=1)
        alg_frame.grid_columnconfigure(2, weight=1)
        alg_frame.grid_columnconfigure(3, weight=1)

        ctk.CTkLabel(alg_frame, text="Scheduler:").grid(row=0, column=0, padx=5)
        self.alg_var = ctk.StringVar(value="MLFQ")
        alg_menu = ctk.CTkOptionMenu(
            alg_frame,
            values=["RR", "PRIO", "MLFQ"],
            variable=self.alg_var,
            command=self.change_scheduler,
        )
        alg_menu.grid(row=0, column=1, padx=5)

        ctk.CTkLabel(alg_frame, text="Speed (ms):").grid(row=0, column=2, padx=5)
        self.speed_var = ctk.StringVar(value="500")
        speed_entry = ctk.CTkEntry(alg_frame, width=60, textvariable=self.speed_var)
        speed_entry.grid(row=0, column=3, padx=5)

    def init_demo(self):
        self.os.fs.create("readme.txt", "Welcome to PyOS!\nThis is a demo file.")
        self.os.fs.create("test.txt", "Hello, world!")
        self.refresh_files()

        prog1 = [
            ("PRINT", "Hello from Process 1"),
            ("ADD", "R1", 5),
            ("PRINT", "R1 value:"),
            ("PRINT", "R1"),
        ]
        prog2 = [
            ("PRINT", "Process 2 starting"),
            ("SUB", "R2", 3),
            ("JZ", "R2", 0),
            ("PRINT", "R2 is not zero"),
        ]
        prog3 = [
            ("PRINT", "Process 3 with loop"),
            ("ADD", "R1", 1),
            ("PRINT", "R1"),
            ("JMP", 1),
            ("HALT",),
        ]
        self.os.create_process("P1", prog1, priority=1)
        self.os.create_process("P2", prog2, priority=2)
        self.os.create_process("P3", prog3, priority=0)
        self.refresh_ui()

    def refresh_ui(self):
        self.refresh_processes()
        self.refresh_memory()
        self.refresh_console()

    def refresh_processes(self):
        for item in self.process_tree.get_children():
            self.process_tree.delete(item)
        for info in self.os.get_process_info():
            self.process_tree.insert(
                "",
                "end",
                values=(
                    info["pid"],
                    info["name"],
                    info["state"],
                    info["pc"],
                    info["priority"],
                    info["pages"],
                ),
            )

    def refresh_memory(self):
        status = self.os.get_memory_status()
        bitmap = status["bitmap"]
        frames = status["page_frames"]
        text = "Page Frame Map:\n"
        for i in range(0, len(bitmap), 4):
            line = f"{i:2d}-{i+3:2d}: "
            for j in range(i, min(i + 4, len(bitmap))):
                if bitmap[j]:
                    pid, lpage = frames.get(j, (None, None))
                    line += f"[P{pid} L{lpage}] "
                else:
                    line += "[FREE] "
            text += line + "\n"
        self.mem_text.delete("1.0", "end")
        self.mem_text.insert("1.0", text)

    def refresh_files(self):
        self.file_listbox.delete(0, "end")
        for fname in self.os.get_file_list():
            self.file_listbox.insert("end", fname)

    def refresh_console(self):
        self.console_text.config(state="normal")
        self.console_text.delete("1.0", "end")
        logs = self.os.output_log[-20:]
        self.console_text.insert("1.0", "\n".join(logs))
        self.console_text.see("end")
        self.console_text.config(state="disabled")

    def on_file_select(self, event):
        selection = self.file_listbox.curselection()
        if selection:
            fname = self.file_listbox.get(selection[0])
            content = self.os.read_file(fname)
            if content is not None:
                messagebox.showinfo(f"File: {fname}", content)

    def create_file_dialog(self):
        dialog = ctk.CTkInputDialog(text="Enter filename:", title="Create File")
        fname = dialog.get_input()
        if fname:
            dialog2 = ctk.CTkInputDialog(text="Enter content:", title="File Content")
            content = dialog2.get_input()
            if content is not None:
                self.os.fs.create(fname, content)
                self.refresh_files()
                self.os.log(f"Created file '{fname}'")

    def delete_file(self):
        selection = self.file_listbox.curselection()
        if selection:
            fname = self.file_listbox.get(selection[0])
            if messagebox.askyesno("Delete", f"Delete '{fname}'?"):
                self.os.fs.delete(fname)
                self.refresh_files()
                self.os.log(f"Deleted file '{fname}'")

    def create_process_dialog(self):
        dialog = ctk.CTkInputDialog(text="Enter process name:", title="Create Process")
        name = dialog.get_input()
        if not name:
            return
        dialog2 = ctk.CTkInputDialog(
            text="Enter instructions as tuple list:\ne.g. [('PRINT','Hello'),('HALT',)]",
            title="Instructions",
        )
        instr_str = dialog2.get_input()
        if instr_str:
            try:
                instr_list = ast.literal_eval(instr_str)  # ← 替换 eval
                if not isinstance(instr_list, list):
                    raise ValueError("Must be a list")
                priority_dialog = ctk.CTkInputDialog(
                    text="Enter priority (0=high, higher number=lower):",
                    title="Priority",
                )
                prio_str = priority_dialog.get_input()
                priority = int(prio_str) if prio_str and prio_str.isdigit() else 0
                self.os.create_process(name, instr_list, priority)
            except Exception as e:
                messagebox.showerror("Error", f"Invalid instructions: {e}")

    def start_sim(self):
        if self.os.running:
            return
        self.os.paused = False
        self.os.running = True

        def run():
            speed = int(self.speed_var.get()) if self.speed_var.get().isdigit() else 500
            while self.os.running and not self.os.paused:
                if not self.os.processes:
                    break
                self.os.run_tick()
                time.sleep(speed / 1000.0)
            self.os.running = False
            self.refresh_ui()

        threading.Thread(target=run, daemon=True).start()

    def pause_sim(self):
        self.os.paused = True
        self.os.running = False

    def step_sim(self):
        self.os.run_tick()

    def stop_sim(self):
        self.os.running = False
        self.os.paused = False

    def change_scheduler(self, choice):
        self.os.set_scheduler_algorithm(choice)
        self.refresh_ui()


if __name__ == "__main__":
    import sys

    # ==================== 测试模式 ====================
    if len(sys.argv) > 1 and sys.argv[1] == "--test":
        unittest.main(argv=[""], exit=False)
        sys.exit(0)

    # ==================== 直接启动游戏 ====================
    if len(sys.argv) >= 4 and sys.argv[1] == "--play":
        game = sys.argv[2]
        user = sys.argv[3]
        shell = KIKIShell()
        with shell._lock:
            if user not in shell.users:
                print(f"用户 {user} 不存在")
                sys.exit(1)
        shell.username = user
        shell.fs.cwd = shell.fs.resolve(f"/home/{user}", user)
        shell._load_user_env()
        shell.apply_config()
        gm = getattr(shell, f"{game}_cmd", None)
        if gm:
            gm("")
        else:
            print(f"游戏 {game} 未找到")
        sys.exit(0)

    # ==================== 执行单条命令后退出 ====================
    if len(sys.argv) >= 3 and sys.argv[1] == "--exec":
        shell = KIKIShell()
        if "--auto-login" in sys.argv:
            idx = sys.argv.index("--auto-login") + 1
            if idx < len(sys.argv):
                user = sys.argv[idx]
                shell.username = user
                shell.fs.cwd = shell.fs.resolve(f"/home/{user}", user)
                shell._load_user_env()
                shell.apply_config()
            else:
                print("错误：--auto-login 需要用户名")
                sys.exit(1)
        else:
            shell.login()
        cmd_idx = sys.argv.index("--exec") + 1
        if cmd_idx < len(sys.argv):
            shell._execute(sys.argv[cmd_idx])
        else:
            print("错误：--exec 需要命令")
            sys.exit(1)
        sys.exit(0)

    # ==================== 纯终端模式（新增） ====================
    if "--terminal" in sys.argv or "-t" in sys.argv:
        shell = KIKIShell()
        # 检查是否附带 --auto-login
        if "--auto-login" in sys.argv:
            idx = sys.argv.index("--auto-login") + 1
            if idx < len(sys.argv):
                user = sys.argv[idx]
                shell.username = user
                shell.fs.cwd = shell.fs.resolve(f"/home/{user}", user)
                shell._load_user_env()
                shell.apply_config()
            else:
                print("错误：--auto-login 需要用户名")
                sys.exit(1)
        else:
            shell.login()  # 普通交互式登录
        shell.run()  # 进入 Shell 命令循环
        sys.exit(0)

    # ==================== 默认：启动 GUI ====================
    app = KIKIGUI()
    app.mainloop()
